INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','fees-0324-review','{"key": "fees-0324-review", "category": "pricing", "branch": "all", "title": "제공 수가표 0324 · 비공개 대조 초안", "body": "이미지 PDF에서 추출한 검토용 목록입니다. 적용 연도·적용일·지점과 금액을 병원이 대조하기 전 공개하지 마세요. 특히 임플란트 보증 연수의 의미·조건과 진료기록 사본 비용의 산정 단위를 확인해야 합니다. 원본 표기 자체가 현행 법정 비급여 고지 요건 충족을 뜻하지 않습니다.", "source": "제공 Drive: 더굿모닝치과 비급여수가표_0324.pdf · 파일 ID 1S5Od4XI3fbbNGiV4FnuvHEQNqte_anTX", "verified": false, "effectiveDate": "", "items": [{"name": "레진 코어", "amount": "8만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name": "Fiber post", "amount": "20만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name": "레진 · 치경부", "amount": "8만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name": "레진 · 단순 (구치)", "amount": "10만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name": "레진 · 복잡 (전치)", "amount": "15만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name": "레진 · Diastema", "amount": "25만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name": "인레이 · Gold", "amount": "40만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name": "인레이 · 이맥스", "amount": "30만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name": "인레이 · 테세라", "amount": "25만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name": "크라운 · Gold", "amount": "70만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name": "크라운 · 지르코니아 (전치)", "amount": "60만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name": "크라운 · 지르코니아 (구치)", "amount": "50만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name": "크라운 · 이맥스 오버레이", "amount": "50만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name": "크라운 · PFM", "amount": "45만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name": "임플란트 · 보증 4년", "amount": "80만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name": "임플란트 · 보증 6년", "amount": "100만원", "unit": "", "note": "원본 대조·현행 여부·지점·적용일 확인 대기"}, {"name":