INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','staff-schedule','{"key": "staff-schedule", "category": "approval", "branch": "all", "title": "의료진 재직·요일·지점 확인", "body": "5인의 현재 재직, 지점별 근무 요일, 휴진을 확인하세요. 확인 후 의료진 관리의 진료 일정에 반영하세요. 더블보드는 강도욱·이상훈 2인만 원본 및 공식 홈페이지에서 확인했습니다.", "source": "병원 확인 대기", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','parking-review','{"key": "parking-review", "category": "parking", "branch": "all", "title": "지점별 주차 안내 확인", "body": "주차장 위치·입구·지원 시간·주차권 발급·주말 이용 조건을 지점별로 확인하세요. 확인 후 지점 관리에도 반영하세요.", "source": "병원 확인 대기", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','access-review','{"key": "access-review", "category": "accessibility", "branch": "all", "title": "휠체어·엘리베이터 접근 확인", "body": "건물 입구 턱, 승강기 크기, 휠체어 이동 경로, 진료실 진입과 이동 보조 가능 범위를 지점별로 확인하세요.", "source": "병원 확인 대기", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','sedation-policy','{"key": "sedation-policy", "category": "sedation", "branch": "all", "title": "수면진료 준비 안내 승인", "body": "사전 평가 항목, 담당 인력, 복용 약 안내, 개인별 금식 시간, 보호자 동반·귀가 정책과 응급 대응 범위를 확인하세요. 임의로 금식 시간을 확정하거나 약 중단을 안내하지 않습니다.", "source": "병원 확인 대기", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','equipment-review','{"key": "equipment-review", "category": "equipment", "branch": "all", "title": "장비 모델·운영 지점 확인", "body": "제안서: HDX willmaster 3D CT, 3shape TRIOS 4.5, NO PAIN, 모니터링·기공소. 기존 공식 홈페이지: HDX willmaster, 3shape TRIOS 5, NO PAIN, infunix 환자감시장치. 스캐너 모델 표기가 달라 최신 모델·보유 지점을 확인해야 합니다. 통증 없음·안전 보장 표현을 사용하지 않습니다.", "source": "병원 확인 대기", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','holiday-review','{"key": "holiday-review", "category": "approval", "branch": "all", "title": "청량리 공휴일·대체공휴일 확인", "body": "청량리 일요일 안내와 별도로 공휴일·대체공휴일 진료 정책을 확인하세요. 지점 관리의 날짜별 예외에 휴진 또는 변경 시간을 등록하면 헤더에 반영됩니다.", "source": "병원 확인 대기", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','cases-consent','{"key": "cases-consent", "category": "case", "branch": "all", "title": "환자 사례 공개 승인 체크리스트", "body": "동의서 확보 여부, 공개 동의 범위·기간, 촬영일·치료기간, 사진 조건, 치료 설명·부작용, 비식별화와 의료광고 검토를 확인해야 합니다. 환자 개인정보나 실제 동의서를 이 편집기에 올리지 마세요. 현재 사례 자료는 비공개 검토 전용이며 직접 공개는 차단합니다.", "source": "병원 확인 대기", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','careers-review','{"key": "careers-review", "category": "careers", "branch": "all", "title": "채용 공고·접수 채널 확인", "body": "직군, 모집 지점, 인원, 근무 요일·시간, 급여 공개 범위, 복지, 필수 자격, 제출 서류, 공식 접수 이메일과 개인정보 처리 안내를 확인하세요.", "source": "병원 확인 대기", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','legal-review','{"key": "legal-review", "category": "legal", "branch": "all", "title": "사업자·개인정보처리방침 승인", "body": "지점별 의료기관 운영 주체·사업자 정보, 개인정보 보호책임자와 공식 연락 창구, 처리 목적·항목·기간·위탁 및 외부 서비스 안내를 법률 검토 후 확정하세요.", "source": "병원 확인 대기", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','travel-review','{"key": "travel-review", "category": "approval", "branch": "all", "title": "해외·타지역 방문 운영 범위", "body": "통역 제공 여부와 가능 언어, 진료자료 접수 방식, 귀국 후 연락·추적관리 방식은 확인 필요합니다. 항공권 예약이나 하루 치료 완료를 보장하지 않습니다.", "source": "병원 확인 대기", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','domain-review','{"key": "domain-review", "category": "approval", "branch": "all", "title": "기존 도메인·인블로그 유지", "body": "현재 공식 원장 칼럼 https://thegoodmorningdental.com/blog/ 는 인블로그입니다. 향후 정식 전환 때 해당 경로와 기존 SEO를 보존할 라우팅을 따로 설계해야 합니다. 이번 작업은 DNS·도메인·정식 배포를 변경하지 않습니다.", "source": "병원 확인 대기", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','mission-copy-review','{"key": "mission-copy-review", "category": "approval", "branch": "all", "title": "핵심 미션 원문·조정문 승인", "body": "원문: 대학병원까지 가지 않으셔도 됩니다. 교정을 제외한 모든 치료를 동대문구 안에서 끝내실 수 있도록 준비했습니다.\n\n현재 제안: 대학병원까지 가기 전에, 동네에서 폭넓은 진료를. 교정을 제외한 여러 진료 분야를 연결하되, 원내 치료가 어려우면 상급병원이 필요한 이유와 다음 방법을 안내합니다.\n\n조정 이유: 모든 치료를 원내에서 끝낸다는 보장을 피하면서 지역 완결적 진료라는 브랜드 의도를 살렸습니다. 원장 확인 후 site > mission에서 최종 문구를 저장·공개하세요.", "source": "병원 확인 대기", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-implant-sedation','{"key": "copy-review-implant-sedation", "category": "approval", "branch": "all", "title": "수면 임플란트 · 원문/현재 답변 대조", "body": "제공 제안서 276–333행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n① 수면임플란트 ( /treatments/implant-sedation )\n환자분이 편안할수록, 식립은 정확해집니다\n긴장이 심해 걱정이셨던 분도, 움직임 없이 편안하게 계획한 대로 수술받으실 수 있습니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 치과 기계 소리만 들어도 긴장이 돼요.\n· 심을 곳이 여러 군데라 수술 시간이 오래걸릴것같아요.\n· 상악동 거상술, 수술이 어려운 뼈이식을 함께 해야 한다고 들었어요.\n· 입에 기구가 들어오면 헛구역질이 나요.\n· 회사일 때문에, 집이 멀어서 자주 여러 번 치과에 가기 어려워요.\n· 갑자기 몸을 움직여서 수술이 잘못되지는 않을까요?\n③ 치료 설명\n\n수면임플란트란?\n수면임플란트란 정맥으로 진정제를 투여해 긴장과 불안을 낮춘 상태에서 진행하는 임플란트 수술입니다. 인공호흡기 없이 스스로 호흡하는 의식하 진정 방식(수면치료)이라, 시술 내내 모니터링 장비로 상태를 확인하며 안전하게 진행합니다.\n· 의식하진정 상태에서 임플란트를 식립하는 방식\n· 일반 임플란트와의 차이 : 수술 중 기억 · 긴장 · 갑작스러운 움직임\n· 수면으로 진행하면 좋은 경우 : 다수 식립 / 뼈이식 동반 / 치과 공포 / 구역 반사가 심한 경우\n· 한 번에 여러 부위를 진행할 수 있어 수술 횟수와 전체 치료 기간이 줄어듭니다\n④ 차별점\n1. 치과마취과학회 정회원 원장이 진정 깊이를 조절합니다\n2. 시술 내내 모니터링 장비로 상태를 확인합니다\n3. 치주과 전문의가 식립을 담당해, 뼈이식이 필요한 케이스도 같은 날 함께 진행합니다\n4. 다양한 케이스 숙련경험이 풍부한 원장이 진료합니다.\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 상담·정밀진단(3D CT) → ② 수면 계획 수립·사전 안내(금식·보호자) → ③ 진정 하 식립 → ④ 회복 확인 후 귀가 · 경과 관찰\n⑥ 전후 사례\n고령 환자 전체 임플란트 · 다수 식립 케이스 중심 3건 → 비포/애프터 연결\n⑦ FAQ\nQ.수면 임플란트는 완전히 잠드는 건가요?A.의식이 옅게 남아 있는 진정 상태입니다. 스스로 호흡하고 부르면 반응하지만, 대부분 수술 과정이 기억나지 않아 치과공포증이 있는 분도 편하게 치료받을수 있습니다.\nQ.의식이 남아 있다면 움직여서 다칠 수도 있지 않나요?A.진정 상태에서는 몸에 힘이 빠지고 반사적인 움직임이 억제되어 오히려 안정적으로 수술할 수 있습니다. 구역반사가 심하거나 섬유근육통처럼 오래 누워 있기 힘든 분도 편하게 치료받으실 수 있습니다. <수면치료 링크>\nQ.전신마취와는 무엇이 다른가요?A.전신마취는 기도에 관을 넣고 호흡을 기계가 담당하지만, 수면 임플란트는 스스로 호흡하는 상태라 회복이 빠르고 부담이 적습니다.\nQ.수술 전 금식을 해야 하나요?A.보통 6~8시간 전부터 음식을, 2시간 전부터는 물도 제한합니다. 진정 중 역류를 막기 위해서입니다.\nQ.먹던 약은 끊어야 하나요?A.임의로 중단하지 마시고 알려 주세요. 혈압약처럼 유지해야 하는 약과 항응고제처럼 조절이 필요한 약이 다릅니다. <전신질환 임플/수면 링크>\nQ.수면으로 하면 여러 개를 한 번에 할 수 있나요?A.네, 오래 입을 벌리는 부담이 줄어 전악임플란트처럼 시간이 긴 수술에 유리합니다. 다만 수술 범위는 잇몸뼈 상태에 따라 결정됩니다. <전체임플 링크>\nQ.치료 중에는 어떻게 관찰하나요?A.진정부터 회복까지 혈압, 맥박, 심전도, 산소포화도를 계속 감시하며 산소 공급 장치와 응급 약제를 갖춘 상태로 진행합니다.\nQ.끝나면 바로 집에 갈 수 있나요?A.회복실에서 30분~1시간 안정 후 귀가합니다.\nQ.고령이어도 수면으로 수술할 수 있나요?A.나이 자체는 제한이 아닙니다. 전신 상태와 복용 약을 확인한 뒤 약물 용량을 낮춰 조절하며, 오히려 오래 앉아 계시기 힘든 분께 도움이 됩니다.\nQ.당일 귀가는 어떻게 하나요? 운전해도 되나요?A.운전은 절대 안 됩니다. 판단력과 반응 속도가 완전히 돌아오지 않으므로 반드시 보호자와 동행하시고, 대중교통 단독 이용도 피해 주세요.\nQ.수면으로 하면 수술이 더 잘 되나요?A. 환자가 움직이지 않아 정밀한 식립에 유리하고, 긴장으로 혈압이 오르는 것을 막아 줍니다. <수면치료 링크>\nQ.추가 비용은 얼마인가요?A.수면 마취는 비급여이며 상담 시 임플란트 비용과 함께 미리 안내드립니다. <비용안내링크>\nQ. 수면 임플란트는 한 번에 몇 개까지 심을 수 있나요?\nA. 정해진 개수 제한은 없습니다. 잇몸뼈 상태와 전신 상태, 예상 수술 시간을 함께 보고 판단하며, 전악 식립을 한 회차에 진행한 경우도 있습니다. <전체임플란트 링크>\nQ. 임신 중이거나 수유 중에도 가능한가요?\nA. 임신 중에는 권해드리지 않습니다. 임신 가능성이 있으시면 반드시 미리 알려주세요.\nQ. 수면 임플란트 다음 날 출근해도 되나요?\nA. 대부분 가능합니다. 다만 수술 범위가 넓으면 붓기가 있어 하루 정도 여유를 두시는 편이 편안합니다.\nQ. 수면 임플란트는 보험이 되나요?\nA. 진정(수면)은 비급여입니다. 임플란트 자체는 만 65세 이상 부분 무치악에 한해 평생 2개까지 건강보험이 적용됩니다. <비용안내 링크>\nQ. 뼈이식이나 상악동거상술을 같이 해도 수면으로 되나요?\nA. 가능하며, 오히려 이런 경우에 더 권해드립니다. 뼈이식과 상악동거상술은 시간이 길고 움직임 억제가 중요한 수술이라 진정이 도움이 됩니다. <고난도 뼈이식 / 상악동거상술 링크>\n연결\n수면센터 > 수면치료 페이지와 상호 링크 / 고난도 뼈이식 / 전체 임플란트\n영상 자산\n''수면 임플란트로 빠른 전체 치료'', ''수면 전체 임플란트 수면마취에 대한 오해'', ''70대 80대 고령 환자의 전체 임플란트''\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 수면 임플란트는 완전히 잠드는 건가요?\n현재 답변: 의식이 옅게 남아 있는 진정 상태입니다. 스스로 호흡하고 부르면 반응할 수 있으나 깊이와 기억 정도는 개인마다 다릅니다. 완전한 수면이나 기억 소실을 보장하지 않습니다.\n\n질문: 의식이 남아 있다면 움직여서 다칠 수도 있지 않나요?\n현재 답변: 진정이 긴장과 반사적 움직임을 줄이는 데 도움이 될 수 있지만 움직임을 완전히 막지는 못합니다. 의료진이 반응과 호흡·순환 상태를 관찰하며 필요하면 치료를 중단하거나 계획을 바꿉니다.\n\n질문: 전신마취와는 무엇이 다른가요?\n현재 답변: 의식하진정은 보통 스스로 호흡하고 말이나 자극에 반응할 수 있는 상태입니다. 전신마취는 의식이 없는 상태로 기도·호흡 관리가 필요합니다. 다만 진정도 예상보다 깊어져 호흡 억제가 생길 수 있어 상태 관찰과 응급 대응이 필요합니다.\n\n질문: 수술 전 금식을 해야 하나요?\n현재 답변: 금식은 위 내용물의 역류와 흡인 위험을 줄이기 위해 필요합니다. 음식 종류와 진정 계획, 건강 상태에 따라 기준이 다르므로 예약 시 받은 개별 안내를 따르세요. 안내와 다르게 드셨다면 숨기지 말고 알려주세요.\n\n질문: 수면으로 하면 여러 개를 한 번에 할 수 있나요?\n현재 답변: 여러 부위의 치료를 한 회차에 묶어 진행할 수 있는 경우가 있습니다. 다만 잇몸뼈와 전신 상태, 예상 수술 시간을 함께 보고 무리하지 않는 범위를 정합니다.\n\n질문: 치료 중에는 어떻게 관찰하나요?\n현재 답변: 진정부터 회복까지 혈압·맥박·산소포화도 등 환자 상태를 관찰합니다. 감시는 위험을 조기에 확인하기 위한 것이며 합병증이 없음을 보장하지는 않습니다.\n\n질문: 끝나면 바로 집에 갈 수 있나요?\n현재 답변: 회복 시간은 약물과 전신 상태에 따라 다릅니다. 의료진이 회복을 확인한 뒤 성인 보호자와 귀가합니다. 당일 운전·음주·기계 조작·중요한 의사결정은 피하고, 활동 재개는 개별 안내를 따르세요.\n\n질문: 고령이어도 수면으로 수술할 수 있나요?\n현재 답변: 나이만으로 결정하지 않습니다. 전신 상태와 복용 약, 기도 위험, 필요한 수술 시간을 확인하고 주치의 협의나 상급병원 진료가 필요한지 평가합니다.\n\n질문: 수면으로 하면 수술이 더 잘 되나요?\n현재 답변: 진정은 불안과 긴장을 낮추는 방법이지 식립의 정확도나 성공을 보장하는 방법은 아닙니다. 위치 계획, 잇몸뼈 상태, 수술 후 관리가 함께 중요합니다.\n\n질문: 수면 임플란트는 한 번에 몇 개까지 심을 수 있나요?\n현재 답변: 일률적인 개수보다 잇몸뼈와 전신 상태, 예상 수술 시간이 기준입니다. 여러 개가 필요하더라도 나누어 진행하는 편이 적합할 수 있습니다.\n\n질문: 임신 중이거나 수유 중에도 가능한가요?\n현재 답변: 임신 중에는 선택적인 진정 치료를 미루는 경우가 많습니다. 임신 가능성이나 수유 여부를 미리 알려주시면 치료의 필요성, 약물과 시점을 확인해 개별 안내합니다.\n\n질문: 수면 임플란트 다음 날 출근해도 되나요?\n현재 답변: 회복 시간은 약물과 전신 상태에 따라 다릅니다. 의료진이 회복을 확인한 뒤 성인 보호자와 귀가합니다. 당일 운전·음주·기계 조작·중요한 의사결정은 피하고, 활동 재개는 개별 안내를 따르세요.\n\n질문: 수면 임플란트는 보험이 되나요?\n현재 답변: 보험 적용 여부는 연령, 구강 상태, 진료 목적과 항목별 현행 기준에 따라 달라집니다. 진단 후 적용 가능한 항목과 비급여 항목을 구분해 안내받으세요. 진정 비용과 함께 받는 치료 비용도 별도로 확인해야 합니다.\n\n질문: 뼈이식이나 상악동거상술을 같이 해도 수면으로 되나요?\n현재 답변: 의식하진정이 도움이 될 수 있지만 모든 분께 적합하지는 않습니다. 전신 상태·복용 약·기도 위험과 치료 범위를 확인한 뒤 결정하며, 필요한 경우 상급 의료기관 진료를 안내합니다.", "source": "제공 개편 제안서 276–333행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-implant-front','{"key": "copy-review-implant-front", "category": "approval", "branch": "all", "title": "앞니 임플란트 · 원문/현재 답변 대조", "body": "제공 제안서 334–421행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n② 앞니 임플란트   ( /treatments/implant-front )\n앞니는 가장 먼저 보이는 자리이기에\n앞니는 씹는 기능뿐 아니라 인상과 발음까지 좌우합니다.잇몸라인과 형태를 먼저 설계하고, 임시 보철로 확인한 뒤 완성합니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 앞니가 벌어져보여요\n· 앞니 사이에 틈이 생긴것같아요.\n· 예전에 한 앞니 임플란트부분이 잇몸이 분리된 것처럼 보여요.\n· 앞니 사이가 벌어져 보이고 검은 삼각형 틈이 생겼어요.\n· 잇몸이 사라져서 심었던 금속이 보여요.\n· 잇몸이 내려앉아 앞니가 길어 보여요.\n· 잇몸이 없어져서 앞니끼리 이어진것처럼 보여요\n· 좌우 잇몸 높이가 달라 웃을 때 어색해요.\n· 잇몸 경계가 검게 비쳐 보여요.\n· 넘어져서 앞니가 뿌리까지 부러졌어요.\n· 부딪혀서 앞니가 흔들려요.\n③ 치료 설명\n\n앞니임플란트란?\n앞니 임플란트란?\n· 앞니는 잇몸 라인과 색·형태가 옆 자연치아와 맞아야 하는 심미 영역\n· 앞니 부위는 잇몸뼈가 얇아 뼈·잇몸 보강이 함께 필요한 경우가 많음\n· 앞니 임플란트 vs 브릿지 vs 라미네이트 비교 표 (적응증·삭제량·기간·비용)\n\n앞니는 잇몸이 결과를 좌우합니다\n앞니 임플란트는 심는 것으로 끝나지 않습니다. 임플란트를 감싸는 뼈와 그 위를 덮는 잇몸이 얇으면 시간이 지나며 잇몸이 뒤로 물러나고, 그때부터 아래 문제들이 하나씩 드러납니다. 그래서 처음부터 식립·뼈이식·잇몸이식을 한 묶음으로 계획합니다.\n\n· 잇몸이 분리된 것처럼 보이는 경우 — 임플란트 주변 잇몸이 얇아 내려앉으면서 보철물과 잇몸 사이에 경계가 생긴 상태입니다. 잇몸 두께를 키우는 이식술로 볼륨을 회복시킵니다\n· 나사(임플란트 표면)가 드러난 경우 — 잇몸과 뼈가 함께 내려간 상태입니다. 노출된 표면을 정리한 뒤 골재생술과 잇몸이식을 병행해 다시 덮어줍니다\n· 앞니 사이가 벌어져 보이는 경우 — 치아 사이를 채우던 잇몸(치간유두)이 사라져 검은 삼각형 틈이 생긴 상태입니다. 연조직 이식이나 보철 형태 조정으로 개선합니다\n· 잇몸 경계가 검게 비치는 경우 — 보철물의 아래쪽 경계가 잇몸 밖으로 드러난 상태입니다. 금속을 쓰지 않는 재료로 교체하면서 잇몸 두께를 함께 확보합니다\n· 좌우 잇몸 높이가 다른 경우 — 보철만 다시 해도 어색하게 남습니다. 잇몸 라인을 먼저 정리한 뒤 그 라인에 맞춰 보철을 제작합니다 <잇몸라인 링크>\n\n· 잇몸 이식술 : 입천장(구개)에서 본인 조직을 채취해 옮겨 심습니다. 본인 조직이라 색과 질감이 주변과 자연스럽게 어우러집니다\n④ 차별점\n1. 치주과 전문의가 잇몸 라인까지 고려해 식립 위치를 설계합니다\n2. 뼈이식과 잇몸이식을 처음부터 한 묶음으로 계획해, 몇 년 뒤에도 잇몸선이 유지되도록 합니다\n3. 이미 잇몸이 내려앉거나 나사가 드러난 케이스도 골재생술·잇몸이식으로 되돌립니다\n4. 원내 자체 기공소에서 색조·형태를 직접 조정합니다\n5. 수면치료(링크)로 정확한 식립이 가능합니다.\n6. 고령·전신질환 환자는 확인 후 수면 병행 가능\n7. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 정밀진단 (CT·구강스캔으로 뼈 폭·잇몸 두께 확인) → ② 발치·식립 (필요 시 뼈이식 동반) → ③ 잇몸이식으로 두께·볼륨 확보 → ④ 임시 보철로 형태·잇몸선 확인 → ⑤ 최종 보철 장착\n⑥ 전후 사례\n앞니 전후 사진 6건 (24.8.14/25.6.26/25.10.4/24.6.15/26.5.27/25.2.7) → 비포/애프터 연결\n⑦ FAQ\nQ. 앞니 임플란트, 티가 많이 나나요?\nA. 자연치아와 완전히 같게 만들 수는 없지만, 잇몸 라인과 색·투명도를 맞추면 가까이에서도 구분이 어려운 정도까지 만들 수 있습니다. 임시 보철로 형태를 먼저 확인하신 뒤 최종 보철을 제작합니다.\nQ. 나중에 앞니 잇몸이 검게 비친다던데요?\nA. 보철물의 아래쪽 경계가 잇몸 밖으로 드러나면 그 부분이 그림자처럼 검게 보일 수 있습니다. 임플란트를 감싸는 뼈나 잇몸이 얇으면 시간이 지나며 잇몸이 내려앉고, 그때 경계선이 노출됩니다. 처음부터 뼈와 잇몸 두께를 함께 확보해야 이 문제를 줄일 수 있습니다.\nQ. 임시치아를 수술 당일에 바로 넣을 수 있나요?\nA. 가능한 경우가 있습니다. 발치 후 즉시 식립하고 당일 임시 보철물까지 장착한 사례가 있습니다. 다만 염증 상태와 초기 고정력에 따라 달라지므로 3D CT 확인 후 판단합니다. <원데이 임플란트 링크>\nQ. 옆 치아와 색을 맞출 수 있나요? 티나지 않을까요?\nA. 원내 자체 기공소에서 기공사와 직접 확인하며 색조와 투명도를 조정합니다. 외부 기공소를 오가지 않아 색이 맞지 않으면 당일 수정이 가능합니다.\nQ. 브릿지와 임플란트 중 무엇이 나은가요?\nA. 양옆 치아가 건강하다면 임플란트를 권해드립니다. 브릿지는 멀쩡한 양옆 치아를 깎아 걸치는 방식이기 때문입니다. 다만 뼈 상태와 비용, 기간을 함께 고려해 상담 시 정합니다.\nQ. 앞니 임플란트는 몇 개월 걸리나요?\nA. 뼈와 잇몸 상태에 따라 다릅니다. 이식 없이 진행하면 약 3개월, 뼈이식과 잇몸이식을 병행하면 약 6개월 정도가 걸립니다. 그 사이에는 임시치아를 착용하십니다.\nQ. 앞니 임플란트 비용은 어금니보다 비싼가요?\nA. 식립 자체의 비용은 크게 다르지 않지만, 앞니는 잇몸 라인과 색을 맞추는 과정이 더해지고 뼈이식·잇몸이식이 함께 필요한 경우가 많아 총액이 올라갈 수 있습니다. 진단 후 필요한 항목만 포함해 서면으로 안내드립니다. <비용안내 링크>\nQ. 앞니 임플란트에도 뼈이식을 해야 하나요?\nA. 앞니 부위는 원래 잇몸뼈가 얇아 뼈이식이 필요한 경우가 많습니다. 뼈가 부족한 채로 심으면 시간이 지나 잇몸이 내려앉을 수 있어, 처음부터 함께 계획하는 편이 결과가 안정적입니다. <고난도 뼈이식 링크>\nQ. 앞니 임플란트 후 발음이 이상해지지 않나요?\nA. 보철물의 두께와 형태가 발음에 영향을 줄 수 있어, 임시 보철 단계에서 발음을 확인하고 조정한 뒤 최종 보철을 만듭니다.\nQ. 앞니 임플란트도 수면으로 할 수 있나요?\nA. 가능합니다. 뼈이식과 잇몸이식을 함께 진행하는 경우 특히 도움이 됩니다. <수면임플란트 링크>\nQ. 앞니 임플란트 수명은 얼마나 되나요?\nA. 관리에 따라 10~20년 이상 쓰시는 경우가 많습니다. 다만 앞니는 잇몸 라인이 조금만 변해도 눈에 띄기 때문에, 정기검진으로 잇몸 상태를 함께 확인하는 것이 중요합니다.\nQ. 다른 치과에서 한 앞니 임플란트를 다시 할 수 있나요?\nA. 가능한 경우가 많습니다. 기존 임플란트를 살리면서 뼈와 잇몸을 보강하는 방법과, 제거 후 다시 심는 방법이 있습니다. 정밀 검진으로 어느 쪽이 가능한지부터 확인합니다. <임플란트 재수술 링크>\nQ. 앞니 임플란트에 건강보험이 되나요?\nA. 만 65세 이상 부분 무치악이라면 평생 2개까지 건강보험이 적용되며, 앞니도 대상에 포함됩니다. 뼈이식·잇몸이식은 비급여입니다. <비용안내 링크>\nQ. 예전에 한 앞니 임플란트 위 잇몸이 분리된 것처럼 보여요.\nA. 임플란트 주변 잇몸이 얇아 내려앉으면서 보철물과 잇몸 사이에 경계가 생긴 상태입니다. 잇몸 두께를 키우는 이식술로 볼륨을 회복시킬 수 있으며, 뼈까지 녹았다면 골재생술을 함께 진행합니다.\nQ. 심었던 나사가 드러났는데 다시 덮을 수 있나요?\nA. 가능한 경우가 많습니다. 노출된 임플란트 표면을 정리한 뒤 골재생술과 잇몸이식을 병행해 다시 덮어줍니다. 잔존 뼈의 양에 따라 회복 범위가 달라져 CT로 먼저 확인합니다.\nQ. 앞니 사이가 벌어져 보이고 검은 틈이 생겼어요.\nA. 치아 사이를 채우던 잇몸(치간유두)이 사라진 상태입니다. 연조직 이식으로 볼륨을 채우거나 보철 형태를 조정해 개선합니다. 완전히 원래대로 돌리기는 어려워 상태를 보고 가능한 범위를 말씀드립니다.\nQ. 앞니 잇몸이 내려가 이가 길어 보입니다.\nA. 치은 퇴축으로 잇몸선이 내려앉은 경우입니다. 잇몸 볼륨을 회복시키는 이식술로 개선 가능한지 판단하며, 좌우 높이가 다르면 잇몸 라인을 함께 정리합니다. <잇몸라인 링크>\nQ. 잇몸이식은 어디서 떼어 오나요?\nA. 대부분 본인의 입천장(구개)에서 채취합니다. 본인 조직이라 색과 질감이 주변과 자연스럽게 어우러지며, 채취 부위는 보통 1~2주 안에 아뭅니다.\nQ. 앞니 임플란트에 뼈이식과 잇몸이식을 꼭 같이 해야 하나요?\nA. 뼈와 잇몸이 충분하면 필요 없습니다. 다만 앞니 부위는 원래 잇몸뼈가 얇아 두 가지를 함께 계획하는 경우가 많고, 그래야 몇 년 뒤에도 잇몸선이 유지됩니다.\n연결\n잇몸라인 / 심미보철 / 라미네이트 / 고난도 뼈이식 / 임플란트 재수술·재치료\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 앞니 임플란트, 티가 많이 나나요?\n현재 답변: 자연치아와 완전히 같게 만들 수는 없습니다. 잇몸 라인과 옆 치아의 색·투명도를 함께 보고 임시 보철로 형태를 먼저 확인한 뒤 최종 보철을 제작합니다.\n\n질문: 옆 치아와 색을 맞출 수 있나요? 티나지 않을까요?\n현재 답변: 원내 자체 기공소에서 색조와 투명도를 확인하며 조정합니다. 자연치아와 완전히 같은 색을 보장하지 않으며 수정 가능 범위와 일정은 보철 상태에 따라 다릅니다.\n\n질문: 브릿지와 임플란트 중 무엇이 나은가요?\n현재 답변: 양옆 치아가 건강하면 이를 삭제하지 않는 임플란트를 검토할 수 있습니다. 브릿지는 인접 치아를 지지대로 사용하므로 옆 치아 상태, 뼈 상태, 수술 부담, 비용과 기간을 함께 보고 결정합니다.\n\n질문: 앞니 임플란트는 몇 개월 걸리나요?\n현재 답변: 골유착과 잇몸 회복에 수개월이 필요할 수 있으며, 뼈이식·잇몸이식 여부에 따라 더 길어집니다. 임시치아의 사용 방법과 예상 일정은 진단 후 안내합니다.\n\n질문: 앞니 임플란트에도 뼈이식을 해야 하나요?\n현재 답변: 앞니 부위는 잇몸뼈가 얇아 뼈이식이 필요한 경우가 있습니다. 뼈가 충분하면 이식이 필요하지 않으며, 잇몸 두께도 함께 확인해 계획합니다.\n\n질문: 앞니 임플란트도 수면으로 할 수 있나요?\n현재 답변: 의식하진정이 도움이 될 수 있지만 모든 분께 적합하지는 않습니다. 전신 상태·복용 약·기도 위험과 치료 범위를 확인한 뒤 결정하며, 필요한 경우 상급 의료기관 진료를 안내합니다.\n\n질문: 앞니 임플란트 수명은 얼마나 되나요?\n현재 답변: 정해진 수명을 보장할 수는 없습니다. 잇몸뼈와 연조직, 씹는 힘, 흡연과 위생 관리에 따라 달라져 정기검진이 중요합니다.\n\n질문: 앞니 임플란트에 건강보험이 되나요?\n현재 답변: 보험 적용 여부는 연령, 구강 상태, 진료 목적과 항목별 현행 기준에 따라 달라집니다. 진단 후 적용 가능한 항목과 비급여 항목을 구분해 안내받으세요. 진정 비용과 함께 받는 치료 비용도 별도로 확인해야 합니다.\n\n질문: 예전에 한 앞니 임플란트 위 잇몸이 분리된 것처럼 보여요.\n현재 답변: 잇몸이 내려가면서 보철물과 잇몸 사이 경계가 드러난 경우일 수 있습니다. 염증과 뼈 소실 여부도 확인하고 잇몸이식이나 보철 조정 등 개선 가능한 범위를 안내합니다.\n\n질문: 심었던 나사가 드러났는데 다시 덮을 수 있나요?\n현재 답변: 골재생술·잇몸이식을 검토할 수 있지만 항상 다시 덮을 수 있는 것은 아닙니다. 잔존 뼈, 염증과 식립 위치를 확인하고 보존 가능성과 한계를 설명합니다.\n\n질문: 앞니 임플란트에 뼈이식과 잇몸이식을 꼭 같이 해야 하나요?\n현재 답변: 뼈와 잇몸이 충분하면 필요 없습니다. 부족한 경우에는 함께 계획하지만 이식 후에도 잇몸선이 변할 수 있어 지속적인 관리가 필요합니다.", "source": "제공 개편 제안서 334–421행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-implant-full','{"key": "copy-review-implant-full", "category": "approval", "branch": "all", "title": "전체 임플란트 · 원문/현재 답변 대조", "body": "제공 제안서 422–530행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n③ 전체 임플란트   ( /treatments/implant-full )\n전체적인 구강구조를 파악하여 진행하는 전체 임플란트\n치아가 거의 없거나 하나도 없는 경우 진행하는 시술입니다. \n블록\n화면에 들어갈 내용\n② 이런 분께\n· 위아래 치아가 대부분 없어요.\n· 틀니가 씹는 힘이 약해서 불편해요.\n· 잇몸뼈가 많이 녹았다고 들었어요.\n· 씹는 높이가 낮아져 얼굴이 달라 보여요.\n· 나이가 많으신 부모님인데 가능할지 모르겠어요.\n· 당뇨·고혈압·골다공증 약을 드시는데 괜찮을까요?\n· 거동이 어려우셔서 오래 앉아 계시기 힘들어요.\n· 치과가 무서워 몇 년째 미루다 여기까지 왔어요.\n· 수술하고 나서 관리는 어떻게 받는지 궁금해요.\n③ 치료 설명\n전체 임플란트란?\n치아가 거의 없거나 하나도 남지 않은 경우 진행하는 치료입니다. 모든 치아 자리에 심는 것이 아니라 꼭 필요한 자리에만 심고 그 사이를 인공치아로 연결해, 자연치아에 가까운 저작력을 회복하면서 비용 부담을 줄입니다.\n· 전악은 개별 치아보다 교합(씹는 높이) 재설정이 핵심입니다\n· 치료 기간 안내 — 발치부터 최종 보철까지 「○」개월\n· 식립 개수 범위 「○~○」개\n\n· 잇몸뼈가 부족한 경우\n전체 임플란트를 알아보시는 분의 상당수는 이미 잇몸뼈가 많이 흡수된 상태입니다. 치아를 오래 비워두었거나 치주염이 진행됐거나 틀니를 오래 사용하신 경우입니다. 남은 뼈의 양과 형태를 3D CT로 먼저 확인한 뒤, 부족하면 뼈이식이나 상악동거상술을 함께 계획하고, 뼈가 남은 부위에 기울여 심는 방법도 검토합니다. <고난도 뼈이식 / 상악동거상술 링크>\n\n· 고령 환자\n나이 자체는 제한이 아닙니다. 다만 오래 앉아 계시기 어렵거나 입을 오래 벌리기 힘드신 경우가 많아, 수술 시간과 진행 순서를 나이에 맞춰 조정합니다. 수면(의식하진정)을 병행하면 부담을 크게 줄일 수 있습니다.\n\n· 전신질환이 있는 경우\n당뇨·고혈압·골다공증·심혈관질환이 있으셔도 조절되고 있으면 가능한 경우가 많습니다. 복용 중인 약과 최근 검사 수치를 먼저 확인하고, 필요하면 주치의 소견을 받아 진행합니다. 수술 중에는 모니터링 장비로 상태를 확인합니다. <전신질환 임플란트 링크>\n\n· 거동이 불편하거나 진료 협조가 어려운 경우\n휠체어로 내원하시거나 진료 중 협조가 어려운 분도 진행 가능합니다. 보호자분과 먼저 상담해 진행 방식을 정하고, 필요하면 수면 하에 여러 부위를 한 번에 정리합니다. <장애인 임플란트 링크>\n\n· 치과 공포증이 있는 경우\n무서워서 미루다 보면 남은 치아가 줄고 잇몸뼈도 함께 녹아, 나중에는 치료 범위가 더 커집니다. 의식하진정으로 진행하면 소리와 진동을 거의 인지하지 못한 채 여러 부위를 한 회차에 마칠 수 있습니다. <수면임플란트 링크>\n\n\n④ 차별점\n1. 치주과 전문의가 뼈 상태를 먼저 평가해 식립 계획을 세웁니다\n2. 잇몸뼈가 부족한 케이스도 뼈이식·상악동거상술을 함께 진행합니다\n3. 고령·전신질환 환자는 복용약과 검사 수치를 확인한 뒤 수면 병행 가능\n4. 치과 공포증이 있으셔도 여러 부위를 한 회차에 정리할 수 있습니다\n5. 골유착을 기다리는 동안 원내 기공소에서 제작한 임시 보철을 착용하므로 식사와 일상생활이 가능합니다\n6. 완성 후 보증 기간과 정기검진 주기를 서면으로 안내드립니다\n7. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n· 보증과 사후 관리\n임플란트는 식립으로 끝나는 치료가 아닙니다. 주변 잇몸뼈가 유지되어야 오래 쓰실 수 있어, 완성 후에도 정기적으로 상태를 확인합니다. 보증 기간과 범위, 정기검진 주기를 치료 시작 전에 서면으로 안내드립니다.\n  - 보증 기간 : 「○」년\n  - 보증 범위 : 「픽스처 / 보철물 / 나사 파절 등 항목별로 기재」\n  - 정기검진 주기 : 3~6개월\n  - 보증에서 제외되는 경우 : 「정기검진 미이행, 외상, 흡연 등 병원 기준으로 기재」\n⑤ 치료 과정\n① 정밀진단 · 전신상태 확인 (3D CT, 복용약·검사 수치 확인) → ② 발치 및 식립 (필요 시 뼈이식·상악동거상술, 수면 병행) → ③ 임시 보철로 교합·발음 확인 → ④ 최종 보철 완성 → ⑤ 정기검진 및 보증 관리\n⑥ 전후 사례\n전체 임플란트 케이스 6건 -> before/After 페이지로 연결\n⑦ FAQ\nQ.수술은 몇 시간 걸리나요?A.한쪽 턱은 약 1~2시간, 위아래 모두 진행하면 2~4시간 정도입니다. 발치나 뼈이식이 함께 필요하면 더 길어지며, 입원 없이 당일 귀가하십니다.\nQ.전체 치료 기간은 얼마나 걸리나요?A.평균 3~6개월입니다. 임플란트와 뼈가 붙는 기간이 아래턱 2~3개월, 위턱 4~6개월 필요하고 이후 최종 보철물을 제작합니다.\nQ.잇몸뼈가 없다고 들었는데 가능한가요?A.대부분 가능합니다. 뼈이식이나 상악동거상술을 함께 하거나, 뼈가 남은 부위에 기울여 심는 방식으로 해결하며 3D CT 검사 후 판단합니다. <고난도 뼈이식,상악동거상술링크>\nQ.나이가 많아도, 지병이 있어도 되나요?A.나이 자체는 제한이 아닙니다. 당뇨·고혈압도 조절되고 있으면 가능하지만, 골다공증 주사제나 항응고제 복용 중이라면 반드시 미리 알려주셔야 합니다. <전신질환임플 링크>\nQ.건강보험이 적용되나요?A.전체(전악) 임플란트는 원칙적으로 비급여입니다. 건강보험 임플란트는 만 65세 이상 부분 무치악 환자에게 평생 2개까지 적용되며, 치아가 하나도 없는 완전 무치악은 대상에서 제외됩니다. <비용안내페이지 링크>\nQ임플란트 후 통증은 얼마나 가나요?A.붓기와 통증은 2~3일째 가장 심하고 보통 일주일 안에 가라앉습니다. 진통제로 조절되며, 일주일 후에도 심해지면 내원해 주세요.\nQ.술과 담배는 언제부터 가능한가요?A.음주는 최소 1~2주 후, 흡연은 오래 참을수록 좋습니다. 첫 2주가 회복의 고비입니다.\nQ.담배를 피우면 임플란트가 잘 안 되나요?A.흡연은 실패의 가장 큰 위험 요인입니다. 니코틴이 잇몸 혈류를 막아 골유착을 방해하고 임플란트 주위염 위험을 높입니다. <임플재수술 링크>\nQ.식사는 언제부터 할 수 있나요?A.수술 당일부터 죽 등 부드럽고 미지근한 음식이 가능합니다. 뜨거운 음식과 빨대는 피하고, 반대쪽으로 씹어 주세요.\nQ.전체를 하루에 다 심을 수 있나요?A.조건이 맞으면 상·하악 전체 식립도 하루에 가능합니다. 고령이거나 지병이 있으면 한쪽 턱씩 나누어 진행하는 편이 안전합니다. <원데이임플 링크>\nQ.임플란트는 얼마나 오래 쓰나요?A.관리에 따라 10~20년 이상 쓰는 경우가 많습니다. 수명을 좌우하는 건 흡연 여부와 잇몸 관리, 정기검진입니다.\nQ.임플란트와 브릿지는 무엇이 다른가요?A.브릿지는 양옆 건강한 치아를 깎아 걸치고, 임플란트는 빠진 자리에 직접 심어 옆 치아를 건드리지 않습니다.\nQ.임플란트 틀니와는 무엇이 다른가요?A.임플란트 틀니는 2~4개를 심어 틀니를 끼웠다 빼는 방식이고, 개별식립은 치아마다 심어 고정합니다. 틀니임플란트는 비용이 낮은 대신 비교적 저작력이 약합니다.<임플틀니링크>\nQ.임플란트를 했는데 MRI를 찍어도 되나요?A.가능합니다. 티타늄은 자석에 반응하지 않는 비자성 금속이라 안전하며, 촬영 전 임플란트 사실만 알려주시면 됩니다.\nQ. 전체 임플란트 비용은 얼마인가요?\nA. 식립 개수와 뼈이식 여부에 따라 크게 달라집니다. 진단 후 필요한 항목만 포함한 서면 견적서를 드리며, 부위를 나누어 순차적으로 진행하는 방법도 함께 안내드립니다. <비용안내 링크>\nQ. 이가 하나도 없는데 임플란트가 가능한가요?\nA. 가능합니다. 모든 자리에 심는 것이 아니라 꼭 필요한 자리에만 심고 그 사이를 인공치아로 연결하는 방식으로 진행합니다. 잇몸뼈가 많이 흡수된 경우에는 임플란트 틀니를 함께 검토합니다. <틀니 임플란트 링크>\nQ. 틀니를 쓰다가 임플란트로 바꿀 수 있나요?\nA. 가능합니다. 다만 틀니를 오래 사용하면 잇몸뼈가 주저앉은 경우가 많아 뼈이식이 함께 필요할 수 있습니다. CT로 남은 뼈의 양을 먼저 확인합니다. <고난도 뼈이식 링크>\nQ. 전체 임플란트 후 예전처럼 씹을 수 있나요?\nA. 틀니보다 훨씬 안정적으로 씹을 수 있습니다. 다만 자연치아와 완전히 같지는 않아, 아주 단단하거나 질긴 음식은 조심하시는 편이 좋습니다.\nQ. 위아래를 동시에 해도 되나요?\nA. 조건이 맞으면 가능합니다. 다만 고령이시거나 지병이 있으시면 한쪽 턱씩 나누어 진행하는 편이 회복에 유리합니다.\nQ. 치료받는 동안 이 없이 지내야 하나요?\nA. 아닙니다. 골유착을 기다리는 동안 임시 보철이나 임시 틀니를 착용하시므로 식사와 일상생활이 가능합니다.\nQ. 전체 임플란트 후 관리는 어떻게 하나요?\nA. 칫솔질과 치간칫솔로 임플란트 주변을 꼼꼼히 닦아 주셔야 합니다. 임플란트는 충치가 생기지 않지만 주위염으로 뼈가 녹을 수 있어, 3~6개월마다 정기검진을 권해드립니다. <임플란트 재수술 링크>\nQ. 전체 임플란트도 수면으로 할 수 있나요?\nA. 가능하며, 가장 권해드리는 경우입니다. 수술 시간이 길어 오래 입을 벌리기 어려운 분께 특히 도움이 됩니다. <수면임플란트 링크>\nQ. 부모님이 80대이신데 전체 임플란트가 가능할까요?\nA. 나이 자체는 제한이 아닙니다. 전신 상태와 복용 중인 약을 먼저 확인한 뒤 진행하며, 오래 앉아 계시기 힘드시면 수면(의식하진정)으로 부담을 줄입니다.\nQ. 당뇨나 골다공증 약을 먹는데 전체 임플란트가 되나요?\nA. 조절되고 있으면 가능한 경우가 많습니다. 골다공증 약은 종류와 복용 기간에 따라 판단이 달라 처방전을 가져와 주시면 확인해 드립니다. <전신질환 임플란트 링크>\nQ. 거동이 불편하고 진료 협조가 어려운데 가능한가요?\nA. 가능한 경우가 많습니다. 보호자분과 먼저 상담해 진행 방식을 정하고, 필요하면 수면 하에 여러 부위를 한 번에 정리합니다. <장애인 임플란트 링크>\nQ. 치과가 무서워서 몇 년을 미뤘습니다.\nA. 그런 분들을 위해 의식하진정으로 진행하는 방법이 있습니다. 미룰수록 남은 치아와 잇몸뼈가 함께 줄어 치료 범위가 커지므로, 먼저 검진만이라도 받아보시길 권해드립니다.\nQ. 잇몸뼈가 거의 없다는데 전체 임플란트가 가능한가요?\nA. 대부분 가능합니다. 뼈이식이나 상악동거상술을 함께 하거나, 뼈가 남은 부위에 기울여 심는 방식으로 해결합니다. 뼈가 심하게 부족하면 틀니 임플란트를 함께 검토합니다. <틀니 임플란트 링크>\nQ. 전체 임플란트도 보증이 되나요?\nA. 보증 기간과 범위를 치료 시작 전에 서면으로 안내드립니다. 다만 보증의 전제는 정기검진입니다. 임플란트 주변 잇몸뼈 상태를 3~6개월마다 확인해야 오래 쓰실 수 있습니다.\nQ. 수술한 뒤 관리는 어떻게 하나요?\nA. 칫솔질과 치간칫솔로 임플란트 주변을 꼼꼼히 닦아 주셔야 합니다. 임플란트는 충치가 생기지 않지만 주위염으로 뼈가 녹을 수 있어, 정기검진에서 이 부분을 확인합니다. <임플란트 재수술·재치료 링크>\nQ. 보증 기간이 지나면 어떻게 되나요?\nA. 보증 기간이 끝나도 정기검진은 계속 받으시는 것이 좋습니다. 문제가 생겼을 때 초기에 발견하면 재수술 없이 처치로 해결되는 경우가 많습니다.\n연결\n틀니 임플란트 / 고난도 뼈이식 / 상악동거상술 / 수면임플란트 / 전신질환 임플란트 / 장애인 임플란트 / 임플란트 재수술·재치료\n이미지\n기존 sec4_slide01 재사용\n\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 수술은 몇 시간 걸리나요?\n현재 답변: 수술 시간은 식립 개수와 발치·뼈이식 범위, 전신 상태에 따라 달라집니다. 오래 앉아 있기 어렵거나 여러 부위를 치료해야 한다면 나누어 진행하는 방법도 함께 안내합니다.\n\n질문: 전체 치료 기간은 얼마나 걸리나요?\n현재 답변: 골유착과 치유에 수개월이 필요하며 뼈이식 범위와 회복 속도에 따라 달라집니다. 진단 후 발치부터 최종 보철까지 예상 일정을 설명합니다.\n\n질문: 잇몸뼈가 없다고 들었는데 가능한가요?\n현재 답변: 뼈이식·상악동거상술이나 남은 뼈를 활용하는 방법을 검토할 수 있습니다. 다만 모든 경우에 가능한 것은 아니며, 뼈가 심하게 부족하면 임플란트 틀니나 다른 대안도 함께 설명합니다.\n\n질문: 건강보험이 적용되나요?\n현재 답변: 보험 적용 여부는 연령, 구강 상태, 진료 목적과 항목별 현행 기준에 따라 달라집니다. 진단 후 적용 가능한 항목과 비급여 항목을 구분해 안내받으세요. 진정 비용과 함께 받는 치료 비용도 별도로 확인해야 합니다.\n\n질문: 임플란트 후 통증은 얼마나 가나요?\n현재 답변: 붓기와 통증은 수술 범위에 따라 다르고 며칠 동안 심해질 수 있습니다. 처방과 관리 지침을 따르되 통증이 계속 악화되거나 발열·고름·심한 부종·지속 출혈이 있으면 예약일을 기다리지 말고 연락하세요.\n\n질문: 술과 담배는 언제부터 가능한가요?\n현재 답변: 흡연은 골유착과 상처 치유를 방해하고 주위염 위험을 높여 금연을 권합니다. 음주는 출혈·회복 및 약물에 영향을 줄 수 있으므로 의료진이 안내한 제한 기간을 따르세요.\n\n질문: 담배를 피우면 임플란트가 잘 안 되나요?\n현재 답변: 흡연은 골유착과 상처 치유를 방해하고 임플란트 주위염 및 실패 위험을 높이는 요인입니다. 수술 전후뿐 아니라 장기 관리에서도 금연이 중요합니다.\n\n질문: 식사는 언제부터 할 수 있나요?\n현재 답변: 출혈과 마취 회복을 확인하고 의료진의 식사 안내를 따르세요. 처음에는 부드러운 음식을 선택하고, 임시 보철에 강한 힘을 주지 않도록 주의합니다.\n\n질문: 임플란트는 얼마나 오래 쓰나요?\n현재 답변: 수명은 잇몸뼈 상태, 흡연, 씹는 힘, 위생 관리 등에 따라 다릅니다. 일정한 사용 기간을 보장하지 않으며 정기검진이 필요합니다.\n\n질문: 임플란트 틀니와는 무엇이 다른가요?\n현재 답변: 전체 고정식 보철은 필요한 위치의 임플란트를 연결하며 모든 치아 자리에 심는 것은 아닙니다. 임플란트 틀니는 연결 장치를 통해 틀니를 유지하는 방식으로, 고정 방식·관리·비용을 함께 비교합니다.\n\n질문: 임플란트를 했는데 MRI를 찍어도 되나요?\n현재 답변: 대부분의 치과 임플란트는 MRI 촬영이 가능하지만 재료와 다른 의료기기 유무를 촬영 기관에 알려 확인해야 합니다. 영상에 영향을 주는 인공물이 생길 수도 있습니다.\n\n질문: 이가 하나도 없는데 임플란트가 가능한가요?\n현재 답변: 가능한 경우가 있습니다. 필요한 위치에 임플란트를 심고 보철로 연결하며, 남은 뼈의 양과 관리 여건에 따라 임플란트 틀니 등도 함께 검토합니다.\n\n질문: 전체 임플란트 후 예전처럼 씹을 수 있나요?\n현재 답변: 씹는 기능의 개선을 기대할 수 있지만 자연치아와 완전히 같지는 않습니다. 최종 보철 후에도 단단하거나 질긴 음식, 이갈이로 인한 과도한 힘을 주의해야 합니다.\n\n질문: 치료받는 동안 이 없이 지내야 하나요?\n현재 답변: 임시 보철이나 임시 틀니의 사용 가능 여부를 미리 계획합니다. 초기 고정과 이식 부위의 상태에 따라 착용이나 식사에 제한이 있을 수 있습니다.\n\n질문: 전체 임플란트도 수면으로 할 수 있나요?\n현재 답변: 의식하진정이 도움이 될 수 있지만 모든 분께 적합하지는 않습니다. 전신 상태·복용 약·기도 위험과 치료 범위를 확인한 뒤 결정하며, 필요한 경우 상급 의료기관 진료를 안내합니다.\n\n질문: 부모님이 80대이신데 전체 임플란트가 가능할까요?\n현재 답변: 나이만으로 결정하지 않습니다. 전신 상태·복용 약·관리 여건을 먼저 확인하며, 오래 앉아 있기 어렵다면 분할 치료나 진정의 적합성을 검토합니다.\n\n질문: 거동이 불편하고 진료 협조가 어려운데 가능한가요?\n현재 답변: 보호자와 이동·의사소통·평소 상태를 먼저 상담합니다. 진정의 적합성과 원내 치료 가능 여부를 확인하고, 필요한 경우 다른 진료 환경을 안내합니다.\n\n질문: 치과가 무서워서 몇 년을 미뤘습니다.\n현재 답변: 무서웠던 이유를 먼저 말씀해 주세요. 의식하진정은 가능한 선택지 중 하나입니다. 검진부터 시작하고 치료 범위와 진행 방법을 함께 정할 수 있습니다.\n\n질문: 잇몸뼈가 거의 없다는데 전체 임플란트가 가능한가요?\n현재 답변: 남은 뼈의 양과 형태를 확인해 골 재건과 식립 가능성을 평가합니다. 치료가 어렵거나 부담이 크면 임플란트 틀니 등 다른 방법을 함께 검토합니다.\n\n질문: 전체 임플란트도 보증이 되나요?\n현재 답변: 보증 제공 여부와 기간·범위·제외 조건은 병원에서 치료 전에 확인해 주세요. 홈페이지에서 미확정 보증 기간을 약속하지 않습니다. 보증과 별개로 정기검진은 중요합니다.\n\n질문: 보증 기간이 지나면 어떻게 되나요?\n현재 답변: 보증 여부와 별개로 정기검진은 계속 필요합니다. 문제가 생기면 상태를 확인해 필요한 처치와 비용을 안내합니다.", "source": "제공 개편 제안서 422–530행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-implant-revision','{"key": "copy-review-implant-revision", "category": "approval", "branch": "all", "title": "임플란트 재수술 · 재치료 · 원문/현재 답변 대조", "body": "제공 제안서 531–640행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n④ 임플란트 재수술 / 재치료 ( /treatments/implant-revision )\n다른 곳에서 어렵다고 하셨다면\n\n식립된 임플란트가 흔들리거나 주변 잇몸에 염증이 생긴 경우, 원인을 다시 진단하고 제거 후 재식립합니다. 잇몸과 잇몸뼈를 다루는 치주과 전문의의 영역입니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 재수술이 필요한 경우\n· 임플란트가 흔들려요.\n· 임플란트 주변에서 피나 고름이 나와요.\n· 임플란트에 음식물이 너무 자주 껴요\n· 잇몸이 내려가 금속 나사가 비쳐 보여요.\n· 임플란트 주변 잇몸이 자주 붓고 피가 나요.\n· 임플란트 주변 잇몸에서 냄새가 나요.\n· 임플란트 옆 치아까지 흔들리기 시작했어요.\n· 통증이 계속돼요\n· 재치료가 필요한 경우\n· 임플란트 보철물(크라운)이 깨졌어요.\n· 보철물이 자꾸 빠져요.\n· 임플란트 나사가 부러졌다고 들었어요.\n· 임플란트 본체(픽스처)에 금이 갔대요.\n· 씹을 때 딱딱 소리가 나거나 흔들리는 느낌이 들어요.\n③ 치료 설명\n임플란트 재수술이란?\n문제가 생긴 기존 임플란트를 제거하고 다시 심는 치료입니다. 흔들리거나 통증이 있는 경우, 임플란트 주위염으로 뼈가 녹은 경우, 위치가 맞지 않아 씹기 불편한 경우가 대상입니다.\n· 실패 원인 유형별 설명 : 임플란트 주위염 / 골 부족 / 식립 위치 부정확 / 보철 부적합\n· 살릴 수 있는 경우와 제거해야 하는 경우의 판단 기준\n· 제거 후 재식립 시 뼈 재건이 함께 필요한 경우가 많음\n\n잇몸이 문제인 경우 — 임플란트 주위염\n임플란트를 다시 하게 되는 원인 중 가장 많은 것이 임플란트 주위염입니다. 임플란트를 둘러싼 잇몸과 뼈에 염증이 생긴 상태로, 초기에는 잇몸이 붓거나 피가 나는 정도지만 방치하면 임플란트를 붙잡고 있는 잇몸뼈가 서서히 녹아 결국 흔들리게 됩니다.\n· 임플란트는 신경이 없어 통증이 늦게 나타납니다. 붓기·출혈·냄새가 초기 신호입니다\n· 잇몸이 내려가 나사(임플란트 표면)가 드러난 경우 — 노출된 표면을 정리한 뒤 골재생술과 잇몸이식을 병행해 다시 덮어줍니다\n· 임플란트 주변에 단단한 잇몸(각화치은)이 부족하면 관리가 어려워 재발하기 쉽습니다. 필요하면 각화치은 이식술을 함께 시행합니다\n· 염증 정도에 따라 기존 임플란트를 살려 쓸 수 있는 경우와 제거해야 하는 경우로 나뉩니다\n\n재치료 — 깨지거나 부러진 경우\n임플란트가 흔들리지 않아도 위쪽 구조물이 손상되는 경우가 있습니다. 이때는 제거하지 않고 손상된 부분만 교체하는 재치료로 해결됩니다.\n· 보철물(크라운) 파절 — 보철만 다시 제작해 연결합니다. 원내 기공소에서 제작해 기간이 짧습니다\n· 나사(스크류) 파절 — 부러진 나사를 제거하고 새 나사로 교체합니다\n· 지대주(어버트먼트) 손상 — 지대주만 교체합니다\n· 임플란트 본체(픽스처) 파절 — 본체가 부러진 경우는 제거 후 재식립이 필요합니다\n· 파절 원인 확인이 먼저입니다. 이갈이, 교합 부조화, 잇몸뼈 소실이 원인인 경우 같은 문제가 반복됩니다 <이갈이 링크>\n④ 차별점\n1. 치주과 전문의가 원인부터 다시 진단합니다\n2. 임플란트 주위염은 잇몸뼈를 다루는 치주과 영역입니다. 염증 처치부터 골 재건까지 같은 원장이 이어서 진행합니다\n3. 골 재건(GBR·골증강술)과 각화치은 이식술을 직접 시행합니다\n4. 살릴 수 있으면 살리고, 어려우면 뼈를 재건해 다시 심습니다\n5. 보철물·나사 파절은 제거 없이 해당 부분만 교체하는 재치료로 해결합니다\n6. 타 병원에서 하신 임플란트도 진료합니다\n7. 수술 시간이 길어 수면 병행 수요가 높은 진료 — 수면임플란트와 연계\n8. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 원인 진단 (CT로 골 결손 범위·염증 범위·파절 부위 확인) → ② 방향 결정 (살릴지 / 제거할지 / 부품만 교체할지) → ③ 처치 (염증 제거·골 재건·재식립 또는 보철·나사 교체) → ④ 치유 확인 후 보철 및 정기 관리\n⑥ 전후 사례\n재수술 케이스 6건- before/After 페이지로 연결\n⑦ FAQ\nQ. 임플란트를 꼭 빼야 하나요?\nA. 반드시 그렇지는 않습니다. 염증 정도에 따라 임플란트 주변을 청소하고 녹은 뼈를 다시 채우는 골재생술로 기존 임플란트를 살려 쓸 수 있습니다. 정밀 검진으로 살릴 수 있는 상태인지부터 확인하는 것이 먼저입니다.\nQ. 뺀 날 바로 다시 심을 수 있나요?\nA. 가능한 경우가 있습니다. 제거 후 즉시 식립을 당일에 진행한 사례가 있습니다. 다만 염증 범위와 남은 뼈의 양에 따라 달라지므로 CT 확인 후 판단합니다.\nQ. 재수술도 오래 쓸 수 있나요?\nA. 왜 실패했는지를 규명하고 그 원인을 함께 해결하면 처음과 다르지 않게 사용하실 수 있습니다. 원인을 그대로 둔 채 다시 심으면 같은 결과가 반복됩니다.\nQ. 다른 병원에서 한 임플란트도 봐주시나요?\nA. 가능합니다. 타 치과에서 식립한 임플란트의 주위염·파절·잇몸 문제로 오시는 경우가 많습니다. 기존 치료 기록이나 엑스레이가 있으시면 함께 가져와 주세요.\nQ. 임플란트가 흔들리는데 그냥 두면 어떻게 되나요?\nA. 흔들린다는 것은 임플란트를 붙잡고 있는 잇몸뼈가 이미 녹고 있다는 뜻입니다. 방치하면 뼈 소실이 계속 진행되어, 나중에는 다시 심을 뼈조차 부족해집니다. 빨리 확인하실수록 선택지가 많습니다.\nQ. 임플란트 주위염은 어떤 증상이 나타나나요?\nA. 잇몸이 붓고 붉어지거나, 칫솔질할 때 피가 나거나, 임플란트 주변을 눌렀을 때 고름이 나오는 증상이 대표적입니다. 초기에는 통증이 거의 없어 모르고 지나가는 경우가 많습니다.\nQ. 임플란트에서 피나 고름이 나오는데 재수술해야하나요?\nA. 임플란트를 둘러싼 잇몸과 뼈에 염증이 생긴 상태(임플란트 주위염)일 가능성이 높습니다. 윗턱이라면 상악동으로 이어지는 누공이나 상악동염도 함께 확인해야 합니다. <상악동거상술 링크>\nQ. 임플란트 주변 잇몸이 내려가 나사가 보여요.\nA. 잇몸과 뼈가 함께 내려앉아 임플란트 표면이 드러난 상태입니다. 노출된 표면을 정리한 뒤 골재생술과 잇몸이식을 병행해 다시 덮어주는 방법이 있습니다. <잇몸라인 링크>\nQ. 임플란트가 부러질 수도 있나요?\nA. 가능합니다. 관리 상태나 주변 잇몸뼈 상황, 이갈이 여부에 따라 픽스처나 보철물이 파절될 수 있습니다. 그래서 식립 이후에도 정기 점검이 중요합니다. \nQ. 임플란트 재수술 비용은 처음보다 더 드나요?\nA. 제거·골 재건·재식립이 함께 필요하면 처음보다 항목이 늘어날 수 있습니다. 다만 기존 임플란트를 살려 쓸 수 있으면 범위가 줄어듭니다. CT 진단 후 서면 견적서로 안내드립니다. <비용안내 링크>\nQ. 재수술은 얼마나 걸리나요?\nA. 골 재건이 함께 필요하면 이식한 뼈가 자리 잡는 데 수개월이 필요합니다. 반대로 제거 후 즉시 식립이 가능한 경우에는 기간이 크게 줄어듭니다.\nQ. 왜 실패했는지 알 수 있나요?\nA. CT로 골 결손 범위와 임플란트 고정 상태를 확인하면 대부분 원인을 좁힐 수 있습니다. 주위염, 골 부족, 식립 위치, 보철 부적합, 이갈이 등으로 나누어 설명드립니다.\nQ. 임플란트 수명이 다 된 걸까요?\nA. 임플란트는 정해진 수명이 있는 부품이 아니라, 주변 잇몸뼈가 얼마나 유지되느냐에 따라 달라집니다. 관리와 정기검진으로 10~20년 이상 사용하시는 경우가 많습니다.\nQ. 임플란트 보철만 다시 하면 안 되나요?\nA. 보철물만 깨지거나 헐거워진 경우라면 보철 교체로 해결됩니다. 다만 잇몸뼈까지 녹아 있으면 보철만 바꿔서는 같은 문제가 반복되므로, 뼈 상태를 먼저 확인합니다.\nQ. 임플란트 브랜드가 문제였을까요?\nA. 브랜드보다 그 자리에 맞는 픽스처의 두께와 식립 위치·방향이 더 큰 영향을 줍니다. 재수술을 계획할 때 이 부분을 다시 설계합니다.\nQ. 재수술도 수면으로 가능한가요?\nA. 가능합니다. 재수술은 대개 뼈이식이 동반되어 시간이 길어지므로 의식하진정이 특히 도움이 되는 영역입니다. <수면임플란트 링크>\nQ. 재수술 후 또 실패하지 않으려면 어떻게 해야 하나요?\nA. 금연, 잇몸 관리, 3~6개월 정기검진 세 가지가 가장 중요합니다. 이갈이가 있으시면 나이트가드를 함께 사용하시길 권해드립니다.\nQ. 임플란트 주위염은 어떤 증상이 나타나나요?\nA. 잇몸이 붓고 붉어지거나, 칫솔질할 때 피가 나거나, 눌렀을 때 고름이 나오는 증상이 대표적입니다. 임플란트는 신경이 없어 통증이 늦게 나타나므로 이런 초기 신호를 놓치지 않으셔야 합니다.\nQ. 잇몸이 내려가 나사가 보이는데 다시 덮을 수 있나요?\nA. 가능한 경우가 많습니다. 노출된 임플란트 표면을 정리한 뒤 골재생술과 잇몸이식을 병행해 다시 덮어줍니다. 남은 뼈의 양에 따라 회복 범위가 달라져 CT로 먼저 확인합니다.\nQ. 임플란트 주변에서 냄새가 나요.\nA. 임플란트와 잇몸 사이에 세균이 쌓여 염증이 생긴 경우가 많습니다. 방치하면 잇몸뼈가 녹으므로 초기에 확인하시는 것이 좋습니다.\nQ. 임플란트 크라운이 깨졌는데 다시 심어야 하나요?\nA. 아닙니다. 보철물만 깨진 경우라면 임플란트 본체는 그대로 두고 보철만 다시 제작합니다. 원내 기공소에서 제작해 기간이 짧습니다.\nQ. 임플란트 나사가 부러졌다는데 어떻게 하나요?\nA. 부러진 나사를 제거하고 새 나사로 교체합니다. 임플란트 본체가 멀쩡하면 제거하지 않아도 됩니다. 다만 나사가 반복해서 부러지면 교합이나 이갈이가 원인일 수 있어 함께 확인합니다.\nQ. 임플란트 본체가 부러질 수도 있나요?\nA. 드물지만 가능합니다. 이갈이가 심하거나 주변 잇몸뼈가 녹아 힘을 지탱하지 못하면 본체에 금이 가기도 합니다. 이 경우에는 제거 후 재식립이 필요합니다.\nQ. 보철물이 자꾸 빠지는데 왜 그런가요?\nA. 접착 부위가 약해졌거나, 나사가 풀렸거나, 교합이 맞지 않아 특정 부위에 힘이 몰리는 경우입니다. 다시 붙이기 전에 원인을 확인해야 반복되지 않습니다.\nQ. 임플란트 주변에 단단한 잇몸이 없다고 하는데 문제가 되나요?\nA. 각화치은이 부족하면 칫솔질이 어렵고 염증이 반복되기 쉽습니다. 필요하면 각화치은 이식술로 관리하기 좋은 잇몸을 만들어 드립니다.\n연결\n고난도 뼈이식 / 상악동거상술 / 잇몸라인 / 치주염 / 수면임플란트 / 전체 임플란트\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 뺀 날 바로 다시 심을 수 있나요?\n현재 답변: 염증 범위와 남은 뼈의 양, 초기 고정 가능성에 따라 다릅니다. 제거 당일 식립이 가능한 경우도 있지만 먼저 염증을 치료하거나 골 재건 후 기다려야 할 수 있습니다.\n\n질문: 재수술도 오래 쓸 수 있나요?\n현재 답변: 실패 원인을 규명하고 함께 해결하는 것이 중요합니다. 원인을 그대로 둔 채 다시 심으면 같은 문제가 반복될 수 있습니다. 재수술도 합병증과 실패 가능성이 있으며 수명을 보장하지 않습니다.\n\n질문: 임플란트가 흔들리는데 그냥 두면 어떻게 되나요?\n현재 답변: 보철 나사가 풀린 경우와 본체의 지지가 약해진 경우는 다릅니다. 염증이나 뼈 소실이 있다면 방치할수록 치료 범위가 커질 수 있으므로 먼저 원인을 확인하세요.\n\n질문: 임플란트 주변 잇몸이 내려가 나사가 보여요.\n현재 답변: 잇몸 퇴축이나 뼈 소실 등 원인을 확인해야 합니다. 골재생술·잇몸이식으로 개선할 수 있는지 평가하되 모두 다시 덮을 수 있는 것은 아닙니다.\n\n질문: 임플란트 수명이 다 된 걸까요?\n현재 답변: 정해진 수명이 있는 부품처럼 판단하기보다 잇몸뼈, 보철과 부품의 상태를 나누어 봅니다. 보존 가능성과 필요한 처치를 먼저 확인합니다.\n\n질문: 임플란트 보철만 다시 하면 안 되나요?\n현재 답변: 보철물만 깨지거나 헐거워졌다면 보철 수리·교체를 검토합니다. 본체·연결 부품과 잇몸뼈까지 확인해야 하며, 원인을 해결하지 않으면 같은 문제가 반복될 수 있습니다.\n\n질문: 임플란트 브랜드가 문제였을까요?\n현재 답변: 브랜드 하나로 원인을 단정하지 않습니다. 식립 위치·방향·부품, 잇몸뼈 상태와 교합·이갈이 등 여러 요인을 확인합니다.\n\n질문: 재수술도 수면으로 가능한가요?\n현재 답변: 의식하진정이 도움이 될 수 있지만 모든 분께 적합하지는 않습니다. 전신 상태·복용 약·기도 위험과 치료 범위를 확인한 뒤 결정하며, 필요한 경우 상급 의료기관 진료를 안내합니다.\n\n질문: 잇몸이 내려가 나사가 보이는데 다시 덮을 수 있나요?\n현재 답변: 노출 원인과 잔존 뼈, 염증 상태를 확인해 골재생술·잇몸이식을 검토합니다. 완전히 덮기 어렵거나 제거가 필요한 경우도 있습니다.\n\n질문: 임플란트 크라운이 깨졌는데 다시 심어야 하나요?\n현재 답변: 보철물만 깨졌다면 본체를 유지하고 보철만 재제작할 수 있는지 확인합니다. 본체와 연결 부위가 손상되지 않았는지, 왜 깨졌는지부터 확인합니다.", "source": "제공 개편 제안서 531–640행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-bone-graft','{"key": "copy-review-bone-graft", "category": "approval", "branch": "all", "title": "고난도 뼈이식 · 원문/현재 답변 대조", "body": "제공 제안서 641–710행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑤ 고난도 뼈이식 ( /treatments/bone-graft )\n무너진 뼈를 다시 세워야, 심을 자리가 나옵니다\n뼛가루를 채우는 수준을 넘어 잇몸뼈의 폭과 높이를 재건하는 수술입니다. 잇몸과 잇몸뼈를 다루는 치주과 전문의의 고난도 영역입니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 다른 치과에서 \"뼈가 없어서 임플란트가 어렵다\"는 말을 들었어요.\n· 아래턱이 신경이랑 가까워서 수술이 어렵다고 들었어요\n· 치주염(풍치)이 심해서 잇몸뼈가 많이 녹았다고 들었어요.\n· 잇몸뼈가 얇아서 임플란트가 흔들릴까 걱정돼요.\n· 예전에 심은 임플란트 주변 뼈가 녹았대요.\n· 틀니를 오래 써서 잇몸이 주저앉았어요.\n· 치아를 뽑고 오래 방치했어요.\n③ 치료 설명\n고난도 뼈이식이란?\n임플란트는 잇몸뼈에 고정되어 힘을 받는 구조라, 뼈가 부족하면 나사를 심을 자리 자체가 나오지 않습니다. 고난도 뼈이식은 부족한 곳에 뼛가루를 채우는 수준을 넘어, 무너진 잇몸뼈의 폭과 높이를 다시 만들어 임플란트를 심을 토대를 재건하는 수술입니다.\n\n· 시술 구분\n  - 골유도재생술(GBR) : 식립과 동시에 부족한 부분을 채우는 기본 형태의 뼈이식\n  - 골증강술(Ridge Augmentation) : 푹 꺼진 치조제의 폭을 다시 봉긋하게 만드는 수술\n  - 수직 골증강술(Vertical Ridge Augmentation) : 높이 방향으로 크게 함몰된 뼈를 재건 — 난도가 가장 높은 영역\n  - 티타늄와이어보강, 비흡수성 차폐막, 소세지 테크닉 : 비흡수성 차폐막으로 이식재를 감싸 고정하는 방법\n  - 티타늄 메쉬(Titanium mesh) : 티타늄으로 만든 얇은 그물망을 뼈 모양대로 구부려 덮고 나사로 고정하는 방법. 결손 범위가 넓거나 높이 방향으로 재건해야 할 때 사용합니다\n  - 각화치은(연조직) 이식술 : 이식 부위를 덮을 단단한 잇몸이 부족할 때 병행\n\n· 이식재 : 아래턱 등에서 환자 본인의 뼈(자가골)를 소량 채취해 이식재와 섞어 사용하기도 합니다\n· 결과를 좌우하는 것은 \"채워 넣는 것\"이 아니라 \"움직이지 않게 고정하는 것\"입니다. 이식재가 흔들리면 그 자리에 뼈가 아니라 연조직이 들어차기 때문에, 나사와 차폐막(티타늄와이어 위에 비흡수성 차폐막을 덮는 구조) 또는 티타늄 메쉬로 단단히 고정합니다\n· 이식 후 골화가 확인될 때까지 대기 기간이 필요합니다 (수개월)\n· 윗턱 어금니의 뼈 높이 부족은 별도 수술입니다 <상악동거상술 링크>\n④ 차별점\n1. 치주과 전문의가 직접 시행하는 고난도 영역입니다\n2. 다른 곳에서 불가 판정을 받은 케이스를 다수 진료해 왔습니다\n3. 결손 형태에 따라 차폐막·소세지 테크닉·티타늄 메쉬 중 맞는 방법을 골라 씁니다\n4. 자가골 채취부터 고정, 각화치은 이식까지 한 원장이 이어서 진행합니다\n5. 단계마다 CT로 골화를 확인한 뒤 다음으로 넘어갑니다\n6. 수술 시간이 길어 수면(의식하진정) 병행 가능 <수면임플란트 링크>\n7. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 3D CT 정밀진단 (뼈의 폭·높이·잔존 골량 확인) → ② 뼈이식 수술 (자가골 채취 · 이식재 충전 · 차폐막 고정, 조건이 되면 식립 동시 진행) → ③ 치유 대기 및 골화 확인 (CT 재촬영) → ④ 임플란트 식립 또는 치유지대주 연결 후 보철\n⑥ 전후 사례\n골증강술 / 수직 골증강술(소세지 테크닉) / 티타늄 메쉬를 이용한 광범위 골재건 / 각화치은 이식 병행 케이스 3~4건\n⑦ FAQ\nQ. 뼈가 없다고 들었는데 정말 임플란트가 가능한가요?\nA. 대부분 가능합니다. 꺼진 자리를 메우거나 얇아진 뼈를 두껍게 만드는 뼈이식으로 심을 토대를 다시 만들 수 있습니다. 다만 결손 범위에 따라 방법과 기간이 달라지므로 3D CT 검사 후 판단합니다.\nQ. 뼈이식 후 얼마나 기다려야 하나요?\nA. 이식한 뼈가 단단해지는 데 보통 수개월이 필요합니다. 사람마다 차오르는 속도가 달라, CT로 충분히 골화된 것을 확인한 뒤 다음 단계로 넘어갑니다.\nQ. 내 뼈를 쓰나요, 인공뼈를 쓰나요?\nA. 상황에 따라 다릅니다. 결손이 큰 경우 아래턱 등에서 본인의 뼈를 소량 채취해 이식재와 함께 사용하기도 합니다. 어떤 재료를 쓸지는 진단 후 미리 설명드립니다.\nQ. 티타늄 메쉬가 무엇인가요?\nA. 티타늄으로 만든 얇은 그물망입니다. 이식한 뼛가루가 눌리거나 흩어지지 않도록 뼈 모양대로 구부려 덮고 나사로 고정합니다. 차폐막만으로는 형태를 유지하기 어려운 넓은 결손이나 높이 재건이 필요한 경우에 사용합니다.\nQ. 티타늄 메쉬는 몸에 계속 남아 있나요?\nA. 아닙니다. 새 뼈가 충분히 자란 것을 CT로 확인한 뒤, 2차 수술 때 제거합니다. 티타늄은 인체에 안정적인 금속이라 그 기간 동안 거부 반응 걱정은 크지 않습니다.\nQ. 차폐막은 나중에 빼야 하나요?\nA. 재료에 따라 다릅니다. 흡수성 차폐막은 몸에서 자연히 흡수되고, 비흡수성 차폐막과 티타늄 메쉬·고정 나사는 골화가 확인된 뒤 제거합니다.\nQ. 뼈이식을 하면 많이 붓나요?\nA. 이식 범위가 클수록 붓기가 있을 수 있습니다. 보통 2~3일째 가장 심하고 일주일 안에 가라앉으며, 냉찜질과 처방 약으로 관리합니다.\nQ. 뼈이식 없이 짧은 임플란트로 대신할 수는 없나요?\nA. 가능한 경우가 있습니다. 남은 뼈의 양과 형태, 씹는 힘을 함께 보고 어느 쪽이 유리한지 상담 시 함께 정합니다.\nQ. 담배를 피우면 안 되나요?\nA. 흡연은 이식한 뼈의 치유를 방해하는 가장 큰 위험 요인입니다. 수술 전후 기간에는 금연을 권해드립니다.\nQ. 뼈이식이 잘 안 되면 어떻게 되나요?\nA. 골화가 충분하지 않으면 추가 이식을 하거나 식립 시점을 미룹니다. 그래서 단계마다 CT로 확인한 뒤 진행합니다.\nQ. 예전에 심은 임플란트 주변 뼈가 녹았는데 이것도 되나요?\nA. 가능한 경우가 많습니다. 노출된 임플란트 표면을 정리한 뒤 골재생술을 더해 기존 임플란트를 살려 쓰기도 합니다. <임플란트 재수술 링크>\nQ. 수면으로 받을 수 있나요?\nA. 가능합니다. 뼈이식은 시간이 길고 움직임 억제가 중요한 수술이라 의식하진정을 권해드리는 경우가 많습니다. <수면임플란트 링크>\n연결\n상악동거상술 / 임플란트 재수술 / 전체 임플란트 / 치주염 / 수면임플란트\n영상 자산\n''어려운 케이스도 해결! 골증강술의 모든 것'', ''발치 후 오래 방치하면 임플란트가 어려워진다고?''\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 뼈가 없다고 들었는데 정말 임플란트가 가능한가요?\n현재 답변: 결손 형태에 따라 뼈이식으로 식립할 토대를 만들 수 있는 경우가 있습니다. 다만 모든 경우에 가능한 것은 아니며 남은 뼈와 전신 상태를 확인해 방법·기간·한계를 설명합니다.\n\n질문: 뼈이식 후 얼마나 기다려야 하나요?\n현재 답변: 이식한 뼈가 성숙하는 데 수개월이 필요할 수 있습니다. 치유 경과와 필요한 검사를 통해 다음 단계로 진행할 시점을 결정합니다.\n\n질문: 티타늄 메쉬는 몸에 계속 남아 있나요?\n현재 답변: 치유 후 제거하는 방식으로 사용하는 경우가 많습니다. 사용한 재료와 수술 계획에 따라 제거 시점을 안내하며 노출·감염 등 합병증 가능성도 설명합니다.\n\n질문: 담배를 피우면 안 되나요?\n현재 답변: 흡연은 이식 부위의 혈류와 치유에 영향을 주는 위험 요인입니다. 수술 전후 금연을 권하며 장기적인 유지 관리에서도 중요합니다.\n\n질문: 뼈이식이 잘 안 되면 어떻게 되나요?\n현재 답변: 골화가 충분하지 않으면 추가 이식이나 식립 시점 변경이 필요할 수 있습니다. 감염이나 이식재 노출 여부를 확인하고 다음 방법을 설명합니다.\n\n질문: 수면으로 받을 수 있나요?\n현재 답변: 의식하진정이 도움이 될 수 있지만 모든 분께 적합하지는 않습니다. 전신 상태·복용 약·기도 위험과 치료 범위를 확인한 뒤 결정하며, 필요한 경우 상급 의료기관 진료를 안내합니다.", "source": "제공 개편 제안서 641–710행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-sinus-lift','{"key": "copy-review-sinus-lift", "category": "approval", "branch": "all", "title": "상악동거상술 · 상악동 염증 치료 · 원문/현재 답변 대조", "body": "제공 제안서 711–816행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑥ 상악동거상술 · 상악동 질환 치료   ( /treatments/sinus-lift )\n윗턱 어금니, 뼈 높이가 부족하거나 염증이 있다면\n윗턱 어금니 위쪽에는 상악동이라는 빈 공간이 있습니다. 이 공간이 내려와 뼈 높이가 부족하면 거상술로 공간을 만들고, 염증이 생겼다면 먼저 치료한 뒤 임플란트를 진행합니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 상악동 거상술이 필요한 경우\n· 윗턱 어금니에 임플란트를 해야 하는데 뼈 높이가 부족하다고 들었어요.\n· \"상악동을 건드려야 해서 어렵다\"는 말을 들었어요.\n· 윗어금니를 뽑고 오래 지났어요.\n· 나이가 많은데 상악동 수술이 부담돼요.\n· 축농증이 있는데 위쪽 임플란트가 가능한지 궁금해요.\n\n· 상악동 염증 치료가 필요한 경우\n· 상악동 수술을 한 후에 냄새가 나요.\n· 위쪽 임플란트를 한후부터 물을 마시면 코로 물이 넘어가는 느낌이 나요.\n· 한쪽 코만 막히고 누런 콧물이 나와요.\n· 이비인후과에서 축농증 치료를 받았는데 자꾸 재발해요.\n· CT에서 상악동에 물혹이 있다고 들었어요.\n③ 치료 설명\n상악동 거상술이란?\n상악동은 윗턱뼈 안에 있는 빈 공간(부비동)입니다. 윗어금니를 오래 비워두면 이 공간이 아래로 내려와 잇몸뼈 높이가 얇아지고, 임플란트를 심을 높이가 나오지 않습니다. 상악동 거상술은 상악동을 감싸는 얇은 막을 위로 들어 올린 뒤 그 아래 생긴 공간에 뼈이식재를 채워, 임플란트를 안정적으로 심을 높이를 확보하는 수술입니다.\n\n· 접근 방법 2가지\n  - 치조정 접근법 : 임플란트를 심을 자리에서 위쪽으로 막을 들어 올립니다. 절개 범위가 작고, 남은 뼈 높이가 어느 정도 확보된 경우에 선택합니다\n  - 측방 접근법 : 옆쪽 뼈에 작은 창을 만들어 접근합니다. 뼈 높이가 많이 부족하거나 넓은 범위가 필요할 때 선택합니다\n\n· 상악동 안에 격벽(septum)이 있거나 점막이 두꺼운 경우처럼 해부학적 구조가 까다로운 케이스도 있어, 접근법을 달리해 진행합니다\n· 남은 뼈 높이가 어느 정도 확보되면 거상술과 임플란트 식립을 한 번에 진행하고, 많이 부족하면 이식 후 골화를 기다렸다가 나중에 심습니다\n· 회복 기간 : 이식한 뼛가루와 기존 치조골의 골화·유착까지 대개 2~6개월. ISQ 장비로 유착 정도를 수치로 확인한 뒤 보철에 들어갑니다\n· 잇몸뼈의 폭이 함께 부족한 경우 뼈이식을 병행합니다 <고난도 뼈이식 링크>\n\n\n상악동 염증 치료(상악동염)란?\n상악동은 코와 자연공(ostium)이라는 작은 구멍으로 연결되어 공기가 드나듭니다. 이 구멍이 막히면 안에 분비물이 고여 세균이 번식하고 염증이 생기는데, 이것이 상악동염(축농증)입니다. 상악동염이 있는 상태에서 거상술이나 임플란트를 진행하면 감염 위험이 커지므로, 염증을 먼저 정리한 뒤 식립합니다.\n\n· 치성 상악동염 — 원인이 치아인 경우\n윗턱 어금니 뿌리 끝은 상악동 바닥과 얇은 뼈 한 겹으로 맞닿아 있습니다. 뿌리 끝 염증, 발치, 임플란트를 통해 세균이 상악동으로 번진 경우로, 원인 치아를 해결하지 않으면 코 치료만으로 낫지 않고 재발합니다.\n\n· 비치성 상악동염 — 원인이 코인 경우\n코 쪽에서 시작된 염증입니다. 이비인후과 진료가 먼저 필요하며, 임플란트를 계획 중이시면 처치 후 진행합니다.\n\n· 주요 증상\n한쪽 코막힘, 누런 콧물, 볼·광대 부위 압통, 두통, 입이나 코에서 나는 냄새\n\n· 함께 확인하는 질환\n저류성 낭종(상악동 안의 물혹) / 곰팡이성 상악동염 / 구강-상악동 누공(입과 상악동이 뚫린 상태) / 임플란트가 상악동 안으로 들어간 경우\n\n· 치료 방법\n원인 치아 처치 · 상악동 배농 및 세정 · 상악동 근치술 · 누공 폐쇄술 · 필요 시 이비인후과 협진\n④ 차별점\n1. CBCT로 잔존 골량·상악동 막 두께·격벽 유무를 미리 확인하고 접근법을 정합니다\n2. 치조정 접근법과 측방 접근법을 모두 시행합니다\n3. 모의 수술로 식립 위치와 깊이를 먼저 잡고 들어갑니다\n4. ISQ 수치로 골유착을 확인한 뒤 보철에 들어갑니다\n5. 상악동 염증이 동반된 경우 배농·세정과 근치술을 원내에서 시행합니다\n6. 염증 처치부터 거상술, 임플란트까지 한 곳에서 이어집니다\n7. 고령·전신질환 환자는 수면(의식하진정) 병행 가능 <수면임플란트 링크>\n⑤ 치료 과정\n· 상악동 거상술\n① 파노라마 + CBCT 정밀진단 (상악동까지의 거리·잔존 치조골·골질 확인, 모의 수술) → ② 상악동 거상술 (치조정 또는 측방 접근으로 막 거상 후 뼈이식재 충전, 조건이 되면 임플란트 동시 식립) → ③ 골화·유착 대기 (대개 2~6개월, ISQ 수치 확인) → ④ 지대주 체결 후 크라운 장착\n\n· 상악동 염증 치료\n① CBCT 정밀진단 (염증 범위·자연공·원인 치아 확인) → ② 원인 처치 (원인 치아 치료 또는 발치, 항생제) → ③ 상악동 배농·세정 또는 근치술, 누공이 있으면 폐쇄 → ④ 회복 확인 후 거상술·임플란트 진행\n⑥ 전후 사례\n치조정 / 측방 접근법 비교 케이스, 80대 고령 환자 상악동 거상술, 골증강술·유리치은이식(FGG) 동시 진행 케이스, 비치성 상악동염 근치술 후 임플란트 식립·저류성 낭종 제거, 축농증 수술 병행 전체 임플란트, 구강-상악동 누공 폐쇄 후 재식립\n⑦ FAQ \nQ. 염증이 있는데 위쪽 임플란트가 가능한가요?\nA. 못 하는 것은 아니고 순서가 다릅니다. 염증이 있는 상태에서 거상술을 하면 감염 위험이 커지므로, 염증을 정리하고 회복을 확인한 뒤 식립합니다.\nQ. 상악동 수술 후에 냄새가 나는데 왜 그런가요?\nA. 상악동에 염증이 남아 있거나 새로 생긴 경우일 수 있습니다. 한쪽에서만 나고 코막힘이 함께 있다면 CBCT로 확인이 필요합니다.\nQ. 물을 마시면 코로 물이 넘어가는 느낌이 나요.\nA. 입과 상악동이 뚫린 구강-상악동 누공일 수 있습니다. 저절로 막히지 않는 경우가 많아 폐쇄 수술이 필요하며, 방치하면 만성 상악동염으로 이어집니다.\nQ. 상악동 거상술은 위험한가요?\nA. 상악동을 감싸는 얇은 막을 들어 올리는 수술이라 정밀함이 필요합니다. CBCT로 막의 두께와 격벽 유무를 미리 확인하고 접근법을 정한 뒤 진행합니다.\nQ. 왜 윗턱 어금니 임플란트 할때 이수술이 필요한가요?\nA. 윗턱 어금니 위쪽에 상악동이라는 빈 공간이 있기 때문입니다. 치아를 오래 비워두면 이 공간이 아래로 내려와 임플란트를 심을 뼈 높이가 부족해집니다.\nQ. 축농증인데 왜 치과에 가야 하나요?\nA. 원인이 치아인 치성 상악동염일 수 있기 때문입니다. 이 경우 코 치료만으로는 재발합니다. CBCT로 원인 치아가 있는지 확인해야 정확합니다.\nQ. 치조정 접근법과 측방 접근법은 무엇이 다른가요?\nA. 치조정 접근법은 임플란트를 심을 자리에서 위로 막을 들어 올리는 방식으로 절개 범위가 작습니다. 측방 접근법은 옆쪽 뼈에 창을 만들어 접근하며, 뼈 높이가 많이 부족하거나 넓은 범위가 필요할 때 선택합니다.\nQ. 상악동 막이 찢어지면 어떻게 되나요?\nA. 수술 중 확인해 바로 처치합니다. 범위에 따라 이식을 미루고 회복을 기다린 뒤 다시 진행하기도 합니다.\nQ. 임플란트를 동시에 심을 수 있나요?\nA. 남은 뼈 높이가 어느 정도 확보되면 거상술과 식립을 한 번에 진행할 수 있습니다. 높이가 많이 부족하면 이식 후 골화를 기다렸다가 나중에 심습니다.\nQ. 회복까지 얼마나 걸리나요?\nA. 이식한 뼈와 기존 치조골이 붙는 데 대개 2~6개월이 걸립니다. ISQ 수치로 유착 정도를 확인한 뒤 보철을 올립니다.\nQ. 80대인데 상악동 거상술이 가능한가요?\nA. 나이 자체가 제한은 아닙니다. 다만 고령일수록 전신질환을 함께 확인해야 하므로, 복용 중인 약과 지병을 미리 알려주시면 그에 맞춰 계획합니다. <전신질환 임플란트 링크>\nQ. 수술 후 코를 풀어도 되나요?\nA. 일정 기간 코를 세게 풀거나 재채기를 참는 등 주의가 필요합니다. 압력이 이식 부위에 영향을 줄 수 있어 수술 후 안내드리는 주의사항을 지켜주셔야 합니다.\nQ. 상악동 근치술이 무엇인가요?\nA. 상악동 안에 고인 농과 염증 조직을 제거하고 세정하는 수술입니다. 배농만으로 해결되지 않는 만성 염증에 시행합니다.\nQ. 상악동에 물혹이 있다는데 위험한가요?\nA. 저류성 낭종은 대부분 증상이 없어 경과만 보는 경우가 많습니다. 다만 크기가 크거나 거상술을 계획 중이면 미리 제거하기도 합니다.\nQ. 임플란트가 상악동으로 들어갔다는데 어떻게 하나요?\nA. 상악동 안에 남아 있으면 염증의 원인이 되므로 제거해야 합니다. 위치를 확인한 뒤 꺼내고, 뚫린 부위를 막은 다음 회복을 기다려 다시 식립합니다. <임플란트 재수술/재치료 링크>\nQ. 뼈이식과 상악동 거상술은 무엇이 다른가요?\nA. 뼈이식은 잇몸뼈의 폭과 높이를 재건하는 수술이고, 상악동 거상술은 윗턱 어금니에서 상악동 막을 들어 올려 높이를 확보하는 수술입니다. 두 가지를 함께 진행하는 경우도 있습니다. <고난도 뼈이식 링크>\nQ. 수면으로 받을 수 있나요?\nA. 가능합니다. 시간이 길고 부담이 큰 수술이라 의식하진정을 권해드리는 경우가 많습니다.\n연결\n고난도 뼈이식 / 전체 임플란트 / 임플란트 재수술·재치료 / 자연치아 살리기 / 수면임플란트 / 전신질환 임플란트\n영상 자산\n''상악동 거상술 동반하는 이유 — 치조정 / 측방 접근법'', ''수면 임플란트 상악동 거상술 : 80대 가능할까요?'', ''비치성 상악동염 상악동근치술 후 임플란트 식립''\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 물을 마시면 코로 물이 넘어가는 느낌이 나요.\n현재 답변: 구강-상악동 누공 등 입과 상악동이 연결된 상태일 수 있어 신속한 진료가 필요합니다. 구멍의 크기와 염증 상태에 따라 처치가 달라지므로 스스로 확인하려고 압력을 가하지 마세요.\n\n질문: 상악동 거상술은 위험한가요?\n현재 답변: 점막 천공, 출혈, 감염과 상악동염, 이식 실패 등의 위험이 있습니다. 영상으로 해부학적 구조를 확인하고 방법을 선택하지만 위험을 완전히 없앨 수는 없습니다.\n\n질문: 축농증인데 왜 치과에 가야 하나요?\n현재 답변: 원인이 치아인 치성 상악동염일 수 있기 때문입니다. 치과 검사와 이비인후과 평가를 통해 원인을 확인하고 필요한 치료를 함께 진행합니다.\n\n질문: 회복까지 얼마나 걸리나요?\n현재 답변: 뼈이식 범위와 회복 속도에 따라 수개월이 걸릴 수 있습니다. 치유와 골유착 상태를 확인한 뒤 보철을 진행하며 일정은 개인별로 안내합니다.\n\n질문: 수술 후 코를 풀어도 되나요?\n현재 답변: 일정 기간 코를 세게 풀지 말고, 재채기는 입을 벌리고 하며 억지로 참지 마세요. 압력이 수술 부위에 영향을 줄 수 있어 개별 안내를 따르세요.\n\n질문: 수면으로 받을 수 있나요?\n현재 답변: 의식하진정이 도움이 될 수 있지만 모든 분께 적합하지는 않습니다. 전신 상태·복용 약·기도 위험과 치료 범위를 확인한 뒤 결정하며, 필요한 경우 상급 의료기관 진료를 안내합니다.", "source": "제공 개편 제안서 711–816행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-implant-disabled','{"key": "copy-review-implant-disabled", "category": "approval", "branch": "all", "title": "장애인 임플란트 · 원문/현재 답변 대조", "body": "제공 제안서 817–856행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑦ 장애인 임플란트   ( /treatments/implant-special-needs )\n거동이 불편하셔도, 임플란트 받으실 수 있습니다\n진료 협조가 어렵거나 오래 앉아 계시기 힘든 분도 수면(의식하진정) 상태에서 안전하게 식립할 수 있습니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 몸을 움직이기 어려워서 휠체어를 이용하는데 가능한가요?\n· 발달·지적 장애로 의사소통이 잘안되는데 임플란트가 가능한가요?\n· 어디가 아픈지 의사소통이 잘되지 않는데 임플란트가 가능할까요?\n· 파킨슨병이나 치매가 있으면 임플란트하기 어려운가요?\n· 오래 입을 벌리기 힘들어요.\n· 몸이 불편해서 치과에 여러 번 가기 어려워요\n③ 치료 설명\n틀니는 매일 빼고 끼우고 세척해야 해 본인은 물론 보호자도 부담이 됩니다. 임플란트는 뼈에 고정되어 있어 착탈 과정이 없고, 칫솔질만으로 관리할 수 있습니다.\n\n· 진행 방식 : 보호자 사전 상담 → 적응 시간 확보 → 필요 시 수면 하 식립 → 회복 확인 후 귀가\n· 한 번에 여러 부위를 진행해 내원 횟수를 최소화하는 계획\n· 시설 안내 : 휠체어 접근 동선 · 엘리베이터 · 보호자 동반 공간\n④ 차별점\n1. 보호자 사전 상담을 먼저 진행합니다\n2. 대기 없이 진료 가능하도록 시간을 별도 배정합니다\n3. 수면 하 통합 치료로 내원 횟수를 줄입니다\n4. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 보호자 사전 상담(복용약·평소 상태·이전 치과 경험) → ② 적응 방문 및 검진 → ③ 수면 하 식립 → ④ 회복 확인 및 정기 관리 안내\n⑥ 전후 사례\n\n⑦ FAQ\nQ.장애인도 임플란트를 받을 수 있나요?A.대부분 가능합니다. 협조가 어려운 경우 수면(진정)이나 전신마취를 병행하며, 전신 상태와 구강 관리 여건을 함께 고려해 치료 계획을 세웁니다. <장애인 수면치료 링크>\nQ.의사소통이나 협조가 어려운데 치료가 될까요?A.진정 상태에서는 몸에 힘이 빠지고 반사적인 움직임이 줄어 안정적으로 수술할 수 있습니다. 발달장애·중증 뇌병변 환자분도 치료받으실 수 있습니다. <장애인 수면치료 링크>\nQ.휠체어를 탄 채로 진료가 가능한가요?A.진료실까지 휠체어로 이동하실 수 있으며, 이동이 어려운 경우 보호자와 함께 도와드립니다. 방문 전 미리 알려주시면 동선과 진료실을 준비해 두겠습니다. <오시는길 안내>\nQ.장애인 치과 진료비 지원이나 감면이 있나요?A.지역별 장애인 구강진료센터나 보건소에서 진료비 감면을 운영하는 경우가 있으며, 대상과 금액은 지자체마다 다릅니다. 임플란트는 대부분 비급여라 지원 범위가 제한적이므로 거주지 보건소에 확인해 보시는 것이 좋습니다. <비용안내 링크\nQ.뇌전증이나 지병이 있는데 마취해도 되나요?A.발작이나 질환이 조절되고 있다면 가능합니다. 복용 중인 약 목록과 최근 발작·입원 시기를 미리 알려주시면 그에 맞춰 준비합니다. <장애인 수면치료 링크\nQ.수술 후 관리는 어떻게 하나요?A.임플란트는 충치가 생기지 않지만 임플란트 주위염으로 뼈가 녹을 수 있어 관리가 중요합니다. 스스로 관리가 어려우면 보호자·활동지원사 교육을 함께 진행하고 3~6개월마다 정기검진을 권합니다. <>\nQ.보호자가 대신 상담을 받아도 되나요?A.가능합니다. 다만 치료 계획 확정과 동의서 작성 시에는 본인 또는 법정대리인의 확인이 필요하므로, 후견인 등록 여부를 미리 알려주시면 절차를 안내해 드립니다.\n연결\n수면센터 > 장애인 수면치료 페이지와 상호 링크\n예약 안내\n사전 전화 예약 권장 — 대기 없이 바로 진료 가능하도록 시간 배정\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 장애인도 임플란트를 받을 수 있나요?\n현재 답변: 가능한 경우가 있습니다. 전신 상태와 구강 관리 여건, 자세 유지와 협조 정도를 함께 확인합니다. 의식하진정으로 어렵거나 전신마취가 필요하면 가능한 상급 의료기관을 안내합니다.\n\n질문: 의사소통이나 협조가 어려운데 치료가 될까요?\n현재 답변: 의사소통 방식과 평소 반응을 보호자와 먼저 상담합니다. 진정으로 부담을 줄일 수 있는지 평가하되 협조가 어려운 모든 상황을 해결할 수 있는 것은 아닙니다.\n\n질문: 휠체어를 탄 채로 진료가 가능한가요?\n현재 답변: 휠체어 이동 동선과 진료 의자로의 이동 가능 여부는 지점과 진료 내용에 따라 확인이 필요합니다. 내원 전에 미리 알려주시면 필요한 도움과 준비를 상담합니다.\n\n질문: 뇌전증이나 지병이 있는데 마취해도 되나요?\n현재 답변: 최근 발작이나 입원 시기, 복용 약과 질환 조절 상태를 먼저 확인합니다. 필요하면 주치의와 상의해 진정과 수술의 적합성을 결정합니다.\n\n질문: 보호자가 대신 상담을 받아도 되나요?\n현재 답변: 보호자가 사전 상담을 받을 수 있습니다. 실제 치료 동의는 환자 본인의 의사와 의사결정 능력을 존중하고, 필요한 경우 법정대리인·후견 관계 등 적법한 권한을 확인해 안내합니다.", "source": "제공 개편 제안서 817–856행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-implant-systemic','{"key": "copy-review-implant-systemic", "category": "approval", "branch": "all", "title": "전신질환 임플란트 · 원문/현재 답변 대조", "body": "제공 제안서 857–903행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑧ 전신질환 임플란트   ( /treatments/implant-medical-compromised )\n지병이 있어 임플란트를 미루셨다면\n고혈압·당뇨·골다공증이 있거나 항응고제를 복용 중이셔도, 사전 검토를 거쳐 안전하게 식립할 수 있습니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 신장 투석을 받고 있는데 임플란트가 가능한가요?\n· 골다공증 약 먹는중인데 임플란트 할수있나요?\n· 뇌전증이 있어 항경련제를 먹고있어요.\n· 아스피린이나 항응고제를 먹고있으면 임플란트가 어렵다고 들었어요.\n· 항암치료 받았었는데 임플란트가 가능한가요?\n· 대학병원에 가보라는 안내를 받았다\n· 섬유근육통이 있어 진통제나 신경 관련 약을 드시는데 임프란트 어렵지 않을까요?\n· 고혈압약 먹는중인데 치료 중 혈압이 오르진 않을까요?\n· 정신질환 약 복용하고있는데 임플란트 가능한가요?\n③ 치료 설명\n· 대상 : 고혈압 · 당뇨 · 심혈관질환 · 골다공증(비스포스포네이트 복용) · 항응고제 복용 · 투석 · 섬유근육통 · 뇌전증\n· 사전 절차 : 문진 → 복용약 확인 → 필요 시 주치의 소견 확인 → 모니터링 장비로 상태를 확인하며 수술\n· 질환별 주의점 : 당뇨는 혈당 조절, 골다공증은 약제 관련 악골괴사, 항응고제는 지혈\n④ 차별점\n1. 복용약과 검사 수치를 먼저 확인한 뒤 계획을 세웁니다\n2. 수술 중 모니터링 장비로 상태를 확인합니다\n3. 긴장을 낮추면 혈압이 안정되므로 수면 병행이 도움이 되는 경우가 있습니다\n4. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 문진 및 복용약 확인 → ② 필요 시 주치의 소견 확인 → ③ 모니터링 하 식립 → ④ 회복 경과를 일반보다 자주 확인\n⑥ 전후 사례\n고령 환자 전체 임플란트 케이스와 상호 연결\n⑦ FAQ\nQ. 지병이 있으면 임플란트를 못 하나요?A. 그렇지 않습니다. 질환이 있다는 사실 자체보다 지금 얼마나 조절되고 있는지, 어떤 약을 드시는지가 더 중요합니다. 복용약과 최근 검사 수치를 확인한 뒤 계획을 세우며, 필요하면 치료 순서를 조정하거나 내과 진료를 먼저 권해드립니다.\nQ. 병원에 무엇을 가져가야 하나요?A. 세 가지면 충분합니다. 복용 중인 약 목록(처방전이나 약 봉투를 그대로 가져오시면 가장 정확합니다), 최근 건강검진이나 혈액검사 결과지, 그리고 다니시는 병원과 진료과 이름입니다.\nQ. 약을 끊고 가야 하나요?A. 임의로 중단하지 마시고 먼저 알려주세요. 혈압약처럼 그대로 드셔야 하는 약이 있고, 항응고제나 골다공증 주사제처럼 조절이 필요한 약이 있습니다. 중단 여부와 시점은 처방하신 주치의와 상의한 뒤 결정합니다.\nQ. 전신질환이 있으면 임플란트 성공률이 낮나요?A. 조절되지 않는 상태라면 감염 위험이 높고 치유가 느려질 수 있습니다. 반대로 잘 조절되고 있다면 일반적인 경우와 큰 차이가 없습니다. 그래서 수술 전 조절 상태 확인을 가장 중요하게 봅니다.\nQ. 치료 기간이 더 오래 걸리나요?A. 치유 속도가 느릴 수 있어 골유착 확인까지 여유를 두거나, 경과를 더 자주 확인하는 경우가 있습니다. 진단 시 예상 일정을 함께 안내드립니다.\nQ. 전신질환이 있으면 수면(진정)이 더 위험하지 않나요?A. 긴장이 완화되면 혈압과 맥박이 안정되어 오히려 도움이 되는 경우가 많습니다. 진정 중에는 혈압·맥박·산소포화도를 계속 확인하여 안전합니다 <전신질환 수면치료 링크>\nQ. 당뇨가 있으면 임플란트가 잘 안 붙나요?A. 혈당이 조절되지 않으면 감염 위험이 높고 잇몸과 뼈가 아무는 속도가 느려집니다. 반대로 잘 조절되고 있으면 일반적인 경우와 큰 차이 없이 진행됩니다.\nQ. 골다공증 주사제맞는데 가능한가요?A. 먹는 약보다 더 신중하게 봅니다. 마지막 주사 시점과 다음 주사 예정일을 알려주시면, 주치의와 상의해 임플란트 수술 시점을 잡습니다.\nQ. 스테로이드를 오래 복용 중인데 괜찮을까요?A. 감염에 대한 저항력이 떨어지고 치유가 지연될 수 있어, 복용 용량과 기간을 확인한 뒤 항생제와 회복 계획을 조정합니다.\nQ. 신장 투석을 받고 있는데 가능한가요?A. 가능한 경우가 있습니다. 투석 당일은 지혈에 영향을 주는 약이 사용되어 피하고, 대개 투석 다음 날로 일정을 잡습니다. 투석 요일을 알려주시면 그에 맞춰 조율합니다.\nQ. 뇌경색·뇌출혈을 겪었는데 임플란트가 되나요?A. 현재 상태와 항혈소판제 복용 여부를 확인한 뒤 판단합니다. 장시간 진료가 부담되시면 수술을 나누거나 수면(진정)을 함께 계획합니다.\nQ. 파킨슨병이나 치매가 있는 부모님도 가능한가요?A. 가능한 경우가 있습니다. 오래 입을 벌리고 계시기 어렵거나 진료 협조가 힘든 경우 수면(진정)으로 한 번에 진행하는 방법을 검토합니다. 보호자분께서 먼저 상담받으셔도 됩니다. <장애인 임플란트 링크>\nQ. 공황장애가 있어 치과 의자에 앉기가 힘듭니다.A. 치과 환경 자체가 증상을 유발할 수 있어, 수면(진정)을 함께 계획하거나 치료 시간을 나누어 부담을 줄입니다. <수면치료 링크>\nQ. 항암치료를 끝낸 지 얼마 안 됐는데 임플란트가 가능한가요?\nA. 가능한 경우가 있습니다. 정해진 대기 기간보다 현재 상태가 기준이라, 백혈구·혈소판 수치가 회복되고 주치의 소견이 확인되면 진행합니다.\n연결\n수면센터 > 전신질환 수면치료 페이지와 상호 링크\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 전신질환이 있으면 임플란트 성공률이 낮나요?\n현재 답변: 질환이 조절되지 않으면 감염과 치유 지연 위험이 높아질 수 있습니다. 조절되어 있어도 질환·약물별 위험이 남으므로 수술 전 상태를 확인하고 개별적으로 설명합니다.\n\n질문: 전신질환이 있으면 수면(진정)이 더 위험하지 않나요?\n현재 답변: 의식하진정이 도움이 될 수 있지만 모든 분께 적합하지는 않습니다. 전신 상태·복용 약·기도 위험과 치료 범위를 확인한 뒤 결정하며, 필요한 경우 상급 의료기관 진료를 안내합니다.\n\n질문: 당뇨가 있으면 임플란트가 잘 안 붙나요?\n현재 답변: 혈당이 조절되지 않으면 감염과 치유 지연 위험이 높아집니다. 최근 검사 수치와 치료 상태를 확인해 적절한 수술 시점을 결정합니다.\n\n질문: 골다공증 주사제맞는데 가능한가요?\n현재 답변: 약의 종류·투여 목적·기간과 최근 투여 시점을 확인해야 합니다. 약제 관련 턱뼈괴사 위험과 약 중단의 위험을 함께 고려하며 임의로 주사를 미루거나 중단하지 않습니다.\n\n질문: 신장 투석을 받고 있는데 가능한가요?\n현재 답변: 가능한 경우가 있습니다. 투석 일정과 지혈 관련 약, 검사 결과를 주치의와 확인해 수술 일정을 정합니다. 임의로 투석이나 약 복용 일정을 바꾸지 마세요.\n\n질문: 항암치료를 끝낸 지 얼마 안 됐는데 임플란트가 가능한가요?\n현재 답변: 항암치료 종류와 종료 시점, 혈액 수치, 면역 상태, 턱 부위 방사선치료 여부 등을 확인해야 합니다. 주치의와 협의해 수술 적합성과 시기를 판단합니다.", "source": "제공 개편 제안서 857–903행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-implant-denture','{"key": "copy-review-implant-denture", "category": "approval", "branch": "all", "title": "틀니 임플란트 · 원문/현재 답변 대조", "body": "제공 제안서 904–963행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑨ 틀니 임플란트   ( /treatments/implant-overdenture )\n기존 틀니의 단점을 보완하고 장점을 결합한 임플란트 틀니\n기존 틀니와 다르게 빠질 염려가 없는 편안한 착용감과 저렴한 치료 비용으로 부담이 적은 장점이 있으며, 잇몸뼈 소실로 임플란트 시술이 어려우신 분들에게 적합합니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 전체 임플란트는 비용이 너무 부담돼요.\n· 임플란트는 뼈이식까지 해야 한다는 말에 망설이고 있어요.\n· 잇몸뼈가 많이 녹아 임플란트가 어렵다고 들었어요.\n· 틀니가 자꾸 빠지거나 흔들려요.\n· 틀니를 끼면 잇몸이 아파 씹기 어려워요.\n③ 치료 설명\n틀니 임플란트란?\n잇몸뼈에 최소한의 임플란트를 심고 그 위에 틀니를 고정하는 방식입니다. 잇몸에 얹기만 하는 일반 틀니와 달리 단단히 걸려 있어 빠질 염려가 적고, 씹는 힘도 훨씬 잘 전달됩니다.\n\n· 전체 임플란트보다 비용 부담이 훨씬 적습니다\n전체 임플란트는 치아 자리마다 심어야 하지만, 틀니 임플란트는 아래턱 기준 2~4개만 심고 나머지를 틀니로 연결합니다. 심는 개수 자체가 크게 줄어 비용 부담이 훨씬 적습니다.\n  - 여기에 만 65세 이상 건강보험(임플란트 평생 2개 + 틀니)을 조합하면 부담을 한 번 더 낮출 수 있습니다\n  - 일반 틀니 · 틀니 임플란트 · 전체 임플란트 3자 비교 표 (비용·착용감·식립 개수·저작력)\n\n· 뼈이식 없이 가능한 경우가 많습니다\n전체 임플란트는 치아 자리마다 심어야 해서 뼈가 부족한 부위마다 이식이 필요합니다. 반면 틀니 임플란트는 뼈가 비교적 잘 남아 있는 자리를 골라 최소 개수만 심기 때문에, 뼈이식 없이 진행 가능한 경우가 많습니다.\n  - 이식이 빠지면 치료 기간이 짧아지고 수술 부담과 비용도 함께 줄어듭니다\n  - 오래 틀니를 사용해 잇몸뼈가 주저앉으신 분, 치주염으로 뼈가 많이 녹으신 분께 특히 적합합니다\n  - 다만 남은 뼈의 양은 3D CT로 확인해야 하며, 부족하면 소량의 이식을 병행하기도 합니다\n\n· 만 65세 이상 건강보험 적용 안내\n④ 차별점\n1. 전체 임플란트보다 비용 부담이 훨씬 적습니다\n2. 잇몸뼈가 부족하더라도 뼈이식 없이 진행 가능한 경우가 많습니다\n3. 만 65세 이상 보험 임플란트와 보험 틀니를 조합해 부담을 한 번 더 낮춰 드립니다\n4. 원내 기공소 제작으로 조정이 빠릅니다\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 진단 및 설계(식립 개수·틀니 형태) → ② 임플란트 식립 → ③ 골유착 대기 · 임시 틀니 사용 → ④ 최종 틀니 연결 및 조정\n⑥ 전후 사례\n무치아/틀니 → 임플란트 틀니 전환 케이스 (25.7.29/25.4.27/26.2.27/)\n->before/after 전체임플란트로 링크\n⑦ FAQ\nQ. 전체 임플란트보다 얼마나 저렴한가요?A. 심는 개수가 적어 비용부담이 크게 줄어듭니다. 다만 임플란트 개수와 틀니 종류, 뼈이식 여부에 따라 달라지므로 진단 후 서면 견적서로 안내드립니다. <비용안내 링크>\nQ. 뼈이식을 꼭 해야 하나요?\nA. 틀니 임플란트는 뼈가 비교적 잘 남아 있는 자리를 골라 최소 개수만 심기 때문에, 뼈이식 없이 진행 가능한 경우가 많습니다. 남은 뼈의 양은 3D CT로 확인한 뒤 판단합니다.\nQ. 뼈이식을 안 하면 무엇이 좋은가요?\nA. 치료 기간이 짧아지고 수술 부담과 비용이 함께 줄어듭니다. 뼈이식은 골화를 기다리는 데만 수개월이 걸리기 때문입니다.\nQ. 잇몸뼈가 거의 없다는데 가능한가요?\nA. 가능한 경우가 많습니다. 오히려 잇몸뼈 소실이 심해 일반 임플란트가 어려운 분께 적합한 치료입니다. 부족한 정도에 따라 소량의 이식을 병행하기도 합니다.\nQ. 일반 틀니와 무엇이 다른가요?A. 고정 방식이 다릅니다. 일반 틀니는 잇몸 위에 얹혀 있어 말하거나 웃을 때 움직일 수 있지만, 틀니 임플란트는 임플란트에 걸려 있어 흔들리지 않습니다. 씹는 힘도 훨씬 잘 전달됩니다.\nQ. 전체 임플란트와는 무엇이 다른가요?A. 심는 개수와 고정 방식이 다릅니다. 전체 임플란트는 치아 자리마다 심어 고정하고, 틀니 임플란트는 최소 개수만 심어 틀니를 끼웠다 뺍니다. 비용 부담이 적은 대신 저작력은 상대적으로 약합니다. <전체 임플란트 링크>\nQ. 빼서 닦아야 하나요? 아니면 끼운채로 자나요?A. 대부분 빼서 세척하는 방식입니다. 매일 틀니를 분리해 닦으시고, 임플란트가 나와 있는 부위도 부드러운 칫솔로 함께 닦아 주셔야 합니다. 고정식으로 만드는 방법도 있어 손 사용이 불편하시면 상담 시 함께 정합니다.Q. 기존 틀니를 그대로 쓸 수 있나요?A. 상태에 따라 다릅니다. 쓰시던 틀니를 그대로 가져오시면 확인해 드립니다.\nQ. 보험이 되나요?\nA. 만 65세 이상은 조건에 따라 임플란트와 틀니 각각에 건강보험이 적용됩니다. 임플란트는 부분 무치악에 한해 평생 2개까지이며, 완전 무치악은 임플란트 보험 대상에서 제외되고 틀니 보험이 적용됩니다. <비용 안내 링크>\nQ. 임플란트를 몇 개 심나요?\nA. 아래턱은 2~4개, 위턱은 뼈가 무르고 상악동이 있어 4개 이상 필요한 경우가 많습니다. 잇몸뼈 상태와 틀니 형태를 보고 최소 개수로 안정적인 고정을 얻는 방향으로 설계합니다.\nQ. 완성까지 얼마나 걸리나요?\nA. 임플란트가 뼈와 붙는 기간을 포함해 보통 2~4개월입니다. 뼈이식이 필요 없으면 이 기간이 더 짧아집니다. 그 사이에는 임시 틀니로 생활하십니다.\n연결\n전체 임플란트 / 고난도 뼈이식 / 전신질환 임플란트 / 심미보철\n이미지\n기존 sec4_slide02 재사용\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 잇몸뼈가 거의 없다는데 가능한가요?\n현재 답변: 남은 뼈를 활용할 수 있는지 확인하지만 뼈 소실이 심하면 이식이나 다른 대안이 필요할 수 있습니다. 잇몸뼈가 부족한 모든 분께 적합한 것은 아닙니다.\n\n질문: 일반 틀니와 무엇이 다른가요?\n현재 답변: 고정 방식이 다릅니다. 일반 틀니는 주로 잇몸의 지지를 받고, 임플란트 틀니는 연결 장치로 유지력을 보완합니다. 움직임이 완전히 없어지는 것은 아니며 장치의 마모와 잇몸 변화에 따른 조정이 필요합니다.\n\n질문: 전체 임플란트와는 무엇이 다른가요?\n현재 답변: 전체 고정식 보철은 필요한 위치의 임플란트를 연결하고, 임플란트 틀니는 주로 분리 가능한 틀니를 연결 장치로 유지합니다. 두 방법 모두 식립 개수는 뼈 상태와 설계에 따라 달라지며 비용·관리·기능을 함께 비교합니다.\n\n질문: 보험이 되나요?\n현재 답변: 보험 적용 여부는 연령, 구강 상태, 진료 목적과 항목별 현행 기준에 따라 달라집니다. 진단 후 적용 가능한 항목과 비급여 항목을 구분해 안내받으세요. 진정 비용과 함께 받는 치료 비용도 별도로 확인해야 합니다.\n\n질문: 완성까지 얼마나 걸리나요?\n현재 답변: 골유착과 틀니 제작·조정에 수개월이 필요할 수 있습니다. 뼈이식과 회복 속도에 따라 달라지며 임시 틀니의 사용 여부도 개별 안내합니다.", "source": "제공 개편 제안서 904–963행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-implant-oneday','{"key": "copy-review-implant-oneday", "category": "approval", "branch": "all", "title": "원데이 임플란트 · 원문/현재 답변 대조", "body": "제공 제안서 964–1005행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑩ 원데이 임플란트   ( /treatments/implant-oneday )\n진단부터 식립까지 — 단, 하루 만에 진행하는 원데이 임플란트\n\n일반적인 임플란트는 발치 후 1·2차 수술을 거쳐 수개월에 완성되지만, 원데이 임플란트는 치아 발치 후 즉시 식립한 후 당일 임시 보철물 장착까지 가능합니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 앞니라 이가 없는 상태로 다닐 수 없다\n· 바빠서 자주 내원하기 어렵다\n· 지방·해외에 거주해 내원 횟수를 줄여야 한다\n· 정해진 일정(행사·출국)이 있다\n③ 치료 설명\n· 발치 → 즉시 식립 → 당일 임시 보철물 장착까지가 ''하루''에 해당\n· 최종 보철까지는 골유착 확인 후 「○」개월이 더 필요함을 명시\n· 가능한 조건과 불가능한 조건을 명확히 구분 — 모든 환자에게 적용되지 않음을 반드시 명시\n· 일반 임플란트와의 기간 비교 표\n④ 차별점\n1. 원내 기공소에서 당일 임시 보철물을 제작합니다\n2. 3D CT로 즉시 식립 가능 여부를 먼저 확인합니다\n3. 지방·해외 거주 환자 일정 조율 상담\n4. 고령·전신질환 환자는 확인 후 수면 병행 가능\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 3D CT 진단 및 즉시 식립 가능 여부 판단 → ② 발치 및 즉시 식립 → ③ 당일 임시 보철물 장착 → ④ 골유착 확인 후 최종 보철\n⑥ 전후 사례\n당일 임시 보철 케이스 2~3건\n⑦ FAQ\nQ. 정말 하루에 끝나나요?A. 발치·식립·임시 보철물 장착까지가 하루입니다. 최종 보철은 임플란트가 뼈와 붙는 것을 확인한 뒤 진행하므로 「○」개월이 더 필요합니다. 다만 그 사이에도 임시치아로 생활하시기 때문에 이 없이 지내는 기간은 없습니다.\nQ. 누구나 할 수 있나요?A. 아닙니다. 발치 부위의 염증 상태와 임플란트가 처음에 얼마나 단단히 고정되는지에 따라 결정됩니다.\nQ. 염증이 있는 치아도 당일식립이 가능한가요?A. 염증 범위에 따라 다릅니다. 제한적인 경우에는 염증 조직을 깨끗이 정리한 뒤 식립이 가능하지만, 뼈까지 광범위하게 녹아 있으면 먼저 아물기를 기다린 후 진행하는 편이 안전합니다.\nQ. 앞니도 되나요?A. 가능하며, 오히려 앞니에서 요청이 가장 많습니다. 이가 빈 상태로 다니기 어려운 부위이기 때문입니다. 다만 심미가 중요해 임시 보철의 형태와 잇몸 라인을 함께 확인하며 진행합니다. <앞니 임플란트 링크>\nQ. 뼈가 부족한데 원데이가 가능한가요?A. 소량의 뼈이식은 함께 진행할 수 있습니다. 다만 이식 범위가 크면 당일 보철은 어려울 수 있어, 식립만 하고 보철은 나중에 올리는 방식으로 계획합니다. <고난도 뼈이식 링크>\nQ. 전체 임플란트도 하루에 되나요?A. 조건이 맞으면 가능합니다. 다만 고령이시거나 지병이 있으시면 한쪽 턱씩 나누어 진행하는 편이 회복에 유리합니다. <전체 임플란트 링크>\nQ. 임시치아는 얼마나 쓰나요?A. 골유착을 확인할 때까지 보통 2~4개월입니다. 그 사이 잇몸이 자연스러운 형태로 아물도록 돕는 역할도 합니다.\nQ. 임시치아가 티 나지 않나요?A. 원내 자체 기공소에서 형태와 색을 맞춰 제작합니다. 최종 보철 전에 모양을 함께 확인하시고 수정하실 수 있습니다.\nQ. 원데이 임플란트도 수면으로 할 수 있나요?A. 가능합니다. 발치·식립·보철을 한 번에 진행해 시간이 길어지므로 의식하진정이 도움이 되는 경우가 많습니다. <수면임플란트 링크>\nQ. 임플란트 뺀날 바로 다시 심을 수 있나요?A. 임플란트 재수술 당일식립은 염증 범위와 남은 뼈의 양에 따라 달라지므로 CT 확인 후 판단합니다. < 임플란트 재수술 링크>\n연결\n앞니 임플란트 / 네비게이션 임플란트 / 전체 임플란트\n이미지\n기존 sec4_slide03 재사용\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 정말 하루에 끝나나요?\n현재 답변: 조건이 맞는 경우 발치·식립·임시 보철물 장착까지를 하루에 진행합니다. 최종 보철은 골유착과 치유를 확인한 뒤 진행합니다. 당일 임시치아도 모든 환자에게 가능한 것은 아닙니다.\n\n질문: 앞니도 되나요?\n현재 답변: 가능한 경우가 있습니다. 다만 앞니는 잇몸선과 임시 보철 형태를 함께 확인해야 하며 염증과 초기 고정 상태에 따라 즉시 연결이 어려울 수 있습니다.\n\n질문: 임시치아는 얼마나 쓰나요?\n현재 답변: 골유착과 잇몸 회복을 확인할 때까지 사용하며 기간은 개인마다 다릅니다. 임시치아에는 강한 힘을 주지 않도록 식사와 관리 방법을 안내합니다.\n\n질문: 원데이 임플란트도 수면으로 할 수 있나요?\n현재 답변: 의식하진정이 도움이 될 수 있지만 모든 분께 적합하지는 않습니다. 전신 상태·복용 약·기도 위험과 치료 범위를 확인한 뒤 결정하며, 필요한 경우 상급 의료기관 진료를 안내합니다.", "source": "제공 개편 제안서 964–1005행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-implant-navigation','{"key": "copy-review-implant-navigation", "category": "approval", "branch": "all", "title": "네비게이션 임플란트 · 원문/현재 답변 대조", "body": "제공 제안서 1006–1044행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑪ 네비게이션 임플란트   ( /treatments/implant-navigation )\n컴퓨터 모의 수술을 통해 안전성과 정확도를 높인 네비게이션 임플란트\n\n실제 수술 전 3차원 3D-CT를 이용하여 정밀진단과 가상수술을 통해 임플란트를 식립할 위치·방향·깊이 등 환자 개인의 수술 조건을 사전에 파악한 뒤 식립합니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 신경이 가까워 위험하다는 말을 들었다\n· 잇몸뼈가 얇아 식립 방향이 중요하다\n· 윗턱이라 상악동과 거리가 짧다\n· 여러 개를 한 번에 심어야 한다\n· 잇몸 절개를 최소화하고 싶다\n③ 치료 설명\n· 가이드 제작 과정 도식 : CT 촬영 → 가상 수술 설계 → 가이드 제작 → 식립\n· 무절개 식립 가능 여부 안내\n· 모든 케이스에 필요한 것은 아니며, 적용이 어려운 경우(맨 뒤 어금니·개구 제한 등)도 함께 명시\n④ 차별점\n1. 보유 장비 : HDX willmaster 3D CT · 3shape 트리오스 5 구강스캐너\n2. 신경관·상악동과의 거리를 사전에 계산해 계획합니다\n3. 수술 시간이 짧아져 고령 환자 부담이 줄어듭니다\n3. 고령·전신질환 환자는 확인 후 수면 병행 가능\n4. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 3D CT · 구강스캔 → ② 가상 수술로 위치·방향·깊이 확정 → ③ 수술용 가이드 제작 → ④ 가이드 식립 및 보철\n⑥ 전후 사례\n신경 인접 부위 · 무절개 식립 케이스\n⑦ FAQ\nQ. 기계가 알아서 심는 건가요?A. 아닙니다. 계획을 세우고 식립하는 것은 의사입니다. 가이드는 정해진 위치와 각도로만 드릴이 들어가도록 잡아주는 도구이며, 계획과 실제 식립 사이의 오차를 줄이는 역할을 합니다.\nQ. 신경이 가까워 위험하다고 들었는데 도움이 되나요?A. 가장 도움이 되는 경우입니다. 아래턱 어금니의 하치조신경관은 잇몸을 열어도 눈에 보이지 않습니다. CT에서 신경관이 지나가는 경로를 미리 확인하고 안전 거리를 두고 계획합니다.\nQ. 가이드 제작에 얼마나 걸리나요?A. 보통 1~2주입니다. CT와 구강스캔을 촬영하고 가상 수술로 계획을 확정한 뒤 제작에 들어갑니다. 준비 기간이 필요한 대신 수술 자체는 짧아집니다.\nQ. 몇 번 내원해야 하나요?A. 진단·스캔 1회, 식립 1회가 기본입니다. 절개하지 않은 경우 실밥 제거가 없어 이후 경과 확인과 보철 과정만 남습니다.\nQ. 비용이 얼마나 더 드나요?A. 가이드 제작 비용이 임플란트 비용과 별도로 발생합니다. 정확한 금액은 진단 후 서면 견적서로 안내드립니다. <비용 안내 링크>\nQ. 수술 시간이 짧아지나요?A. 계획이 확정된 상태로 들어가기 때문에 단축되는 경우가 많습니다. 고령이시거나 오래 앉아 계시기 어려운 분께 부담이 줄어듭니다.\n연결\n원데이 임플란트 / 고난도 뼈이식 / 병원 둘러보기(장비)\n이미지\n기존 sec5_bg 재사용\n\n4-3. [b] 수면센터 — 3개 페이지\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 신경이 가까워 위험하다고 들었는데 도움이 되나요?\n현재 답변: 신경관의 경로를 미리 확인해 계획하는 데 도움이 될 수 있습니다. 다만 가이드가 있어도 오차와 신경 손상 위험을 없앨 수는 없어 안전 거리와 적용 가능성을 신중히 평가합니다.\n\n질문: 가이드 제작에 얼마나 걸리나요?\n현재 답변: 스캔과 설계·제작 과정에 시간이 필요합니다. 수술 조건과 제작 일정에 따라 달라지므로 진단 후 준비 기간을 안내합니다.\n\n질문: 몇 번 내원해야 하나요?\n현재 답변: 진단·스캔, 수술, 경과 확인과 보철 과정이 필요합니다. 뼈이식이나 절개 여부, 치유 상태에 따라 내원 횟수가 달라집니다.", "source": "제공 개편 제안서 1006–1044행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-sedation','{"key": "copy-review-sedation", "category": "approval", "branch": "all", "title": "수면치료 · 의식하진정 · 원문/현재 답변 대조", "body": "제공 제안서 1045–1121행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n① 수면치료 (의식하진정)   ( /treatments/sedation )\n무서웠던 기억이 남지않도록\n치과 공포증으로 치과진료를 미뤄오신 분도 가수면 상태에서 편안하게 치료받으실 수 있습니다.\n수면치료란? - 수면치료는 정맥 내 진정제를 투여해 환자가 편안히 잠든 듯한 상태에서 치과 치료를 받는 방법입니다. 의식은 흐려지지만 자발 호흡은 그대로 유지되는 ''의식하 진정'' 방식으로, 치료 중 불안과 통증에 대한 기억이 거의 남지 않습니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 치과 특유의 냄새·소리만으로 공포를 느낀다\n· 마취 주사가 가장 무섭다\n· 입에 기구가 들어오면 헛구역질이 난다\n· 치료할 곳이 많아 여러 번 와야 한다\n· 오래 입을 벌리고 있기 어렵다\n③ 치료 설명\n\n수면치료란?\n핵심 장점 7가지 (기존 자료 4가지 + 추가 3가지)\nㄱ. 치과 특유의 냄새·소리 등 공포와 트라우마 극복이 가능합니다.\nㄴ. 갑작스러운 움직임을 방지하여 정확하고 질 높은 수술이 가능합니다.\nㄷ. 의식과 신경을 차단하는 전신마취가 아니기에 인체에 무해하며 안전합니다.\nㄹ. 치과 불안감을 최소화할 수 있도록 담당 전문의가 자세하게 설명해 드립니다.\nㅁ. 한 번에 여러 부위를 동시에 치료할 수 있어 전체 치료 기간과 내원 횟수가 줄어듭니다.\nㅂ. 구역 반사가 심하신 분도 편안하게 치료받으실 수 있습니다.\n\n· ''전신마취와 무엇이 다른가요?'' 비교 표 — 환자분이 가장 많이 하는 질문\n④ 차별점\n1. 대한치과마취과학회 정회원 원장이 환자 상태에 맞춰 진정 깊이를 조절합니다\n2. 시술 내내 모니터링 장비로 환자 상태를 확인합니다 (infunix 환자 모니터링 장비 사진 재사용)\n3. 수면으로 진행 가능한 진료는 어떤 것이 있나요?— 임플란트 · 사랑니 발치 · 고난도 뼈이식 등 진료 페이지 링크\n4. 다수케이스 숙련경험\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 상담 및 전신 상태 확인(복용약·기저질환) → ② 사전 준비(금식·보호자 동반 안내) → ③ 진정 유도 후 치료 진행(모니터링) → ④ 회복 확인 후 귀가 · 당일 운전 금지 안내\n⑥ 전후 사례\n수면으로 진행한 다수 치료 케이스 → 비포/애프터 연결\n⑦ FAQ\nQ. 정말 잠드나요?\nA. 깊이 잠든 것처럼 느끼시지만 완전한 수면은 아닙니다. 의식이 옅게 남아 있어 스스로 호흡하시고 부르면 반응하시지만, 대부분 치료 과정을 기억하지 못하십니다.\nQ. 전신마취와 무엇이 다른가요?\nA. 전신마취는 기도에 관을 넣고 호흡을 기계가 담당합니다. 수면치료(의식하진정)는 스스로 호흡을 유지하므로 삽관이 필요 없고 회복이 빠릅니다.\nQ. 수면치료 후 운전해도 되나요?\nA. 절대 안 됩니다. 판단력과 반응 속도가 완전히 돌아오지 않아 음주 운전과 비슷한 위험이 있습니다. 보호자와 동행하시고 대중교통 단독 이용도 피해 주세요.\nQ. 추가 비용은 얼마인가요?\nA. 수면(진정)은 비급여이며 치료 시간과 범위에 따라 달라집니다. 치료 본 비용과 별도로 발생하며 상담 시 함께 안내드립니다. <비용안내 링크>\nQ. 금식은 몇 시간 해야 하나요?\nA. 보통 6~8시간 전부터 음식을, 2시간 전부터는 물도 제한합니다. 진정 중 위 내용물이 역류하는 것을 막기 위해서입니다.\nQ. 수면치료로 어떤 치료까지 받을 수 있나요?\nA. 임플란트뿐 아니라 매복 사랑니 발치, 충치·신경치료, 뼈이식, 상악동거상술, 잇몸 수술까지 가능합니다. 여러 치료를 한 회차에 묶어 진행할 수도 있습니다.\nQ. 치과가 무서워서 몇 년째 못 갔는데 저도 받을 수 있나요?\nA. 치과공포증이 있는 분들을 위한 진료입니다. 오래 미루신 만큼 치료할 곳이 늘어나 있는 경우가 많은데, 수면치료로 한 번에 정리하는 계획을 세울 수 있습니다.\nQ. 수면치료 중에 아픈 걸 느끼나요?\nA. 진정과 국소마취를 함께 시행하므로 통증을 느끼기 어렵습니다. 소리와 진동도 대부분 인지하지 못하십니다.\nQ. 수면치료 약물이 몸에 해롭지 않나요?\nA. 안정성이 확보된 약제를 사용하며, 진정 중에는 혈압·맥박·심전도·산소포화도를 계속 감시합니다. 다만 전신 상태에 따라 적합하지 않은 경우가 있어 사전 확인이 필요합니다.\nQ. 수면치료를 받으면 정말 기억이 안 나나요?\nA. 대부분 부분적으로만 기억하시거나 거의 기억하지 못하십니다. 이 점이 치과 공포증을 넘어서는 데 큰 도움이 됩니다.\nQ. 구역질이 심한데 수면치료가 도움이 되나요?\nA. 도움이 됩니다. 진정 상태에서는 구역 반사가 억제되어, 기구가 들어오면 헛구역질이 나 치료를 미뤄오신 분도 편안하게 진행하실 수 있습니다.\nQ. 아이도 수면치료를 받을 수 있나요?\nA. 연령과 협조 정도, 전신 상태에 따라 판단이 달라집니다. 보호자분께서 먼저 상담을 받아보시길 권해드립니다.\nQ. 고혈압·당뇨가 있는데 수면치료가 가능한가요?\nA. 조절되고 있다면 가능한 경우가 많습니다. 오히려 긴장이 완화되면 혈압과 맥박이 안정되어 치료가 원활해지기도 합니다. 복용 중인 약을 미리 알려주세요. <전신질환 수면치료 링크>\nQ. 수면치료 받으려면 보호자가 꼭 필요한가요?\nA. 동반을 권해드립니다. 회복 후에도 판단력이 완전히 돌아오지 않아 귀가 시 도움이 필요할 수 있습니다.\nQ. 수면치료 후 얼마나 쉬어야 하나요?\nA. 회복실에서 30분~1시간 안정을 취한 뒤 귀가하십니다. 당일은 무리한 활동과 음주를 피하시고, 다음 날부터는 대부분 일상생활이 가능합니다.\nQ. 수면치료를 하면 치료를 한 번에 끝낼 수 있나요?\nA. 여러 치료를 묶어 진행할 수 있어 내원 횟수가 줄어듭니다. 멀리서 오시거나 시간을 내기 어려운 분께 특히 유용합니다.\nQ. 수면치료가 안 되는 경우도 있나요?\nA. 있습니다. 임신 중이시거나 금식이 어려운 경우, 조절되지 않는 중증 질환이 있는 경우에는 권해드리지 않습니다. 사전 상담에서 판단해 다른 방법을 안내드립니다.\nQ. 수면치료 비용은 보험이 되나요?\nA. 수면(진정)은 비급여입니다. 다만 함께 받으시는 치료 중 신경치료·발치·잇몸치료 등은 건강보험이 적용됩니다. <비용안내 링크>\n\n연결\n수면으로 진행 가능한 진료 목록 → 수면임플란트 · 사랑니 발치 · 고난도 뼈이식 · 충치치료\n영상 자산\n''수면치료 후 왜 운전이 위험할까요'' 내용 텍스트화\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 정말 잠드나요?\n현재 답변: 잠든 것처럼 느낄 수 있지만 완전히 의식이 없어지는 전신마취와 다릅니다. 의식이 옅게 남아 있고 반응할 수 있으며 기억 정도에는 개인차가 있습니다.\n\n질문: 전신마취와 무엇이 다른가요?\n현재 답변: 의식하진정은 보통 스스로 호흡하고 말이나 자극에 반응할 수 있는 상태입니다. 전신마취는 의식이 없는 상태로 기도·호흡 관리가 필요합니다. 다만 진정도 예상보다 깊어져 호흡 억제가 생길 수 있어 상태 관찰과 응급 대응이 필요합니다.\n\n질문: 금식은 몇 시간 해야 하나요?\n현재 답변: 금식은 위 내용물의 역류와 흡인 위험을 줄이기 위해 필요합니다. 음식 종류와 진정 계획, 건강 상태에 따라 기준이 다르므로 예약 시 받은 개별 안내를 따르세요. 안내와 다르게 드셨다면 숨기지 말고 알려주세요.\n\n질문: 수면치료로 어떤 치료까지 받을 수 있나요?\n현재 답변: 임플란트, 사랑니 발치, 충치·신경치료, 뼈이식, 상악동거상술, 잇몸 수술 등에서 검토합니다. 진정의 적합성과 한 번에 진행할 범위는 전신 상태와 치료 계획에 따라 결정합니다.\n\n질문: 치과가 무서워서 몇 년째 못 갔는데 저도 받을 수 있나요?\n현재 답변: 치과공포증 때문에 미뤄오셨다면 어떤 부분이 무서웠는지부터 말씀해 주세요. 의식하진정은 선택지 중 하나이며, 검진 후 나누어 치료하거나 설명과 적응 시간을 조정하는 방법도 함께 안내합니다.\n\n질문: 수면치료 중에 아픈 걸 느끼나요?\n현재 답변: 진정은 불안과 긴장을 낮추고, 통증 조절에는 국소마취를 병행합니다. 감각과 기억에는 개인차가 있어 전혀 아프지 않다고 보장하지 않습니다.\n\n질문: 수면치료 약물이 몸에 해롭지 않나요?\n현재 답변: 진정 약물도 호흡 억제·저산소증·혈압 변화·오심·알레르기 등의 위험이 있습니다. 병력과 복용 약을 확인하고 진정부터 회복까지 상태를 관찰합니다. 위험이 높으면 다른 진료 환경을 안내합니다.\n\n질문: 수면치료를 받으면 정말 기억이 안 나나요?\n현재 답변: 기억이 줄거나 일부만 남을 수 있지만 개인과 진정 깊이, 약물에 따라 다릅니다. 기억이 전혀 남지 않는다고 보장하지 않습니다.\n\n질문: 구역질이 심한데 수면치료가 도움이 되나요?\n현재 답변: 구역반사를 줄이는 데 도움이 될 수 있습니다. 다만 정도와 원인, 전신 상태를 먼저 확인하며 반사가 완전히 없어지는 것은 아닙니다.\n\n질문: 고혈압·당뇨가 있는데 수면치료가 가능한가요?\n현재 답변: 의식하진정이 도움이 될 수 있지만 모든 분께 적합하지는 않습니다. 전신 상태·복용 약·기도 위험과 치료 범위를 확인한 뒤 결정하며, 필요한 경우 상급 의료기관 진료를 안내합니다.\n\n질문: 수면치료 받으려면 보호자가 꼭 필요한가요?\n현재 답변: 성인 보호자와 동행해 주세요. 깨어난 것처럼 느껴도 판단력과 반응이 저하될 수 있어 혼자 귀가하거나 운전하지 않습니다.\n\n질문: 수면치료 후 얼마나 쉬어야 하나요?\n현재 답변: 회복 시간은 약물과 전신 상태에 따라 다릅니다. 의료진이 회복을 확인한 뒤 성인 보호자와 귀가합니다. 당일 운전·음주·기계 조작·중요한 의사결정은 피하고, 활동 재개는 개별 안내를 따르세요.\n\n질문: 수면치료를 하면 치료를 한 번에 끝낼 수 있나요?\n현재 답변: 여러 부위를 묶어 진행해 내원 부담을 줄일 수 있는 경우가 있습니다. 그러나 치료량과 전신 상태, 치유 과정 때문에 여러 번의 진료가 필요할 수 있습니다.\n\n질문: 수면치료 비용은 보험이 되나요?\n현재 답변: 보험 적용 여부는 연령, 구강 상태, 진료 목적과 항목별 현행 기준에 따라 달라집니다. 진단 후 적용 가능한 항목과 비급여 항목을 구분해 안내받으세요. 진정 비용과 함께 받는 치료 비용도 별도로 확인해야 합니다.", "source": "제공 개편 제안서 1045–1121행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-sedation-disabled','{"key": "copy-review-sedation-disabled", "category": "approval", "branch": "all", "title": "장애인 수면치료 · 원문/현재 답변 대조", "body": "제공 제안서 1122–1159행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n② 장애인 수면치료   ( /treatments/sedation-special-needs )\n진료 협조가 어려우셔도 괜찮습니다\n발달장애·지적장애·지체장애·뇌전증 등으로 진료 중 협조가 어려운 분도 가수면 상태에서 필요한 치료를 받으실 수 있습니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 몸을 움직이기 어려워서 휠체어를 이용하는데 가능한가요?\n· 진료받는동안 몸을 가만히 있기 어려워요.\n· 발달·지적 장애로 의사소통이 어려워요.\n· 어디가 아픈지 의사소통이 잘되지 않아요.\n· 파킨슨 병이 있어서 치과치료 받기가 힘들어요.\n· 오래 입을 벌리기 힘들어요.\n· 몸이 불편해서 치과에 여러 번 가기 어려워요\n· 오랫동안 앉아있기 힘들어요.\n③ 치료 설명\n· 보호자 상담 우선 — 평소 상태, 복용 중인 약, 이전 치과 경험을 먼저 확인합니다\n· 한 번에 여러 부위를 치료해 내원 횟수를 최소화합니다\n· 항경련제 등 진정에 영향을 주는 약은 반드시 사전 확인\n④ 차별점\n1. 보호자만 먼저 오셔서 상담하실 수 있습니다\n2. 대기 시간 없이 진료 가능하도록 시간을 별도 배정합니다\n3. 시설 안내 : 휠체어 접근 동선(엘리베이터) · 보호자 동반 공간 · 조용한 대기 공간\n4. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 보호자 사전 상담 → ② 적응 방문 및 검진 → ③ 진정 하 통합 치료 → ④ 회복 확인 및 정기 관리 주기 안내\n⑥ 전후 사례\n게재 동의를 받은 케이스만 노출\n⑦ FAQ\nQ. 협조가 전혀 안 되는데 가능한가요?A. 진료가 어려운 이유는 대부분 치료 자체가 아니라 오래 앉아 있고 입을 벌리고 있는 상황을 견디기 어렵기 때문입니다. 의식하진정으로 그 부담을 줄이면 필요한 치료를 진행할 수 있습니다.\nQ. 지적장애가 있어 설명을 이해하기 어려운데요?A. 치료 내용은 보호자분께 충분히 설명드리고 함께 결정합니다. 환자분께는 이해하실 수 있는 수준으로 짧고 반복해서 안내드립니다.\nQ. 뇌병변으로 몸이 계속 움직이는데 수술이 가능한가요?A. 진정 상태에서는 긴장이 풀리고 불수의적인 움직임이 줄어들어 안정적으로 진행할 수 있습니다. 다만 움직임의 정도와 원인 질환에 따라 다르므로 사전 확인이 필요합니다.\nQ. 어디가 아픈지 표현을 못 하는데 어떻게 찾나요?A. 파노라마와 3D CT로 전체를 확인합니다. 표현이 어려우신 분은 문제가 커진 뒤에 발견되는 경우가 많아, 통증이 없더라도 정기적으로 촬영해 두시는 편이 좋습니다.\nQ. 발달장애나 자폐가 있는데 진료가 되나요?A. 평소 어떤 자극에 예민하신지, 이전 치과 경험은 어땠는지를 미리 여쭤보고 그에 맞춰 준비합니다.\n연결\n장애인 임플란트 페이지와 상호 링크\n예약 안내\n사전 전화 예약 권장 — 대기 시간 없이 진료 가능하도록 시간 배정\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 협조가 전혀 안 되는데 가능한가요?\n현재 답변: 어려운 상황과 평소 반응을 먼저 확인합니다. 의식하진정으로 부담을 줄일 수 있는 경우가 있지만 협조가 전혀 어려우면 원내 진정으로 충분하지 않을 수 있어 상급 의료기관의 전신마취 진료를 안내할 수 있습니다.\n\n질문: 지적장애가 있어 설명을 이해하기 어려운데요?\n현재 답변: 환자분께 이해하실 수 있는 방식으로 짧고 반복해서 안내합니다. 보호자와 치료 내용을 상의하되 본인의 의사와 의사결정 능력을 존중하고, 필요한 동의 권한과 절차를 확인합니다.\n\n질문: 뇌병변으로 몸이 계속 움직이는데 수술이 가능한가요?\n현재 답변: 움직임의 정도와 원인 질환, 기도 위험을 확인해야 합니다. 진정이 도움이 될 수 있지만 불수의적인 움직임을 완전히 막지는 못하므로 다른 마취 방법이나 진료 환경이 필요할 수 있습니다.\n\n질문: 어디가 아픈지 표현을 못 하는데 어떻게 찾나요?\n현재 답변: 보호자에게 식사·수면·행동 변화와 불편 반응을 여쭤보고 구강 검진을 진행합니다. 방사선 검사는 필요성을 판단해 선택하며 통증을 표현하지 못한다는 이유만으로 정기 CT를 일률적으로 촬영하지 않습니다.", "source": "제공 개편 제안서 1122–1159행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-sedation-systemic','{"key": "copy-review-sedation-systemic", "category": "approval", "branch": "all", "title": "전신질환 수면치료 · 원문/현재 답변 대조", "body": "제공 제안서 1160–1205행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n③ 전신질환 수면치료   ( /treatments/sedation-medical-compromised )\n지병이 있어도, 긴장을 낮춘 상태에서\n치과 진료 시 혈압이 오르거나 긴장이 심해지는 분께, 상태를 확인하며 진행하는 수면치료를 권해드립니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 신장 투석을 받고 있는데 수면치료 가능한가요?\n· 골다공증 약 먹고있는데 수면치료 받아도 되나요?\n· 뇌전증이 있어 항경련제를 먹고있는데 안전하게 치과치료 받고싶어요.\n· 아스피린이나 항응고제를 먹고있는데 임플란트할 때 수면으로 치료받아도 될까요?\n· 항암치료 받았었는데 수면치료가 가능한가요?\n· 질환 때문에 치과진료를 거절당했어요.\n· 섬유근육통이 있어 신경 관련 약을 드시는데 수면치료 안전한가요?\n· 고혈압약 먹는중인데 치료 중 혈압이 오르진 않을까요?\n· 정신질환 약 복용하고있는데 수면치료 받는게 가능한가요?\n· 오랫동안 앉아있기 힘들어요.\n③ 치료 설명\n· 대상 : 고혈압 · 당뇨 · 심혈관질환 · 항응고제 복용 · 투석 환자 · 섬유근육통 · 뇌전증\n· 긴장으로 인한 혈압 상승을 낮춘 상태에서 치료할 수 있다는 점이 핵심 이점입니다\n· 진정이 권장되지 않는 경우도 있어 반드시 사전 상담이 필요하다는 점을 함께 명시\n④ 차별점\n1. 문진과 복용약 확인을 먼저 진행합니다\n2. 필요 시 주치의 소견을 확인한 뒤 진행합니다\n3. 모니터링 장비로 산소포화도·맥박·혈압을 확인하며 진행합니다\n4. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 문진 및 복용약 확인 → ② 필요 시 주치의 소견 확인 → ③ 모니터링 하 진정 및 치료 → ④ 회복 확인 후 귀가\n⑥ 전후 사례\n전신질환 환자 치료 케이스 → 비포/애프터 연결\n⑦ FAQ\nQ.먹던 약을 끊어야 하나요?A.임의로 중단하지 마시고 먼저 알려주세요. 혈압약·심장약처럼 끊으면 오히려 위험한 약은 수술 당일 아침에도 소량의 물과 함께 복용하는 경우가 많고, 항응고제·당뇨약·일부 정신과 약은 진정제와 상호작용이 있어 조절이 필요할 수 있습니다. 복용 중인 약 목록을 지참해 주시면 처방 병원과 상의해 개별 안내드립니다.\nQ.질환이 있으면 수면치료가 어려운 경우도 있나요?A.있습니다. 심한 수면무호흡증, 조절되지 않는 심부전·폐질환, 중증 비만, 진정제 부작용 이력이 있는 경우에는 호흡 억제 위험이 있어 제한될 수 있습니다. 이런 경우 국소마취로 나누어 진행하거나, 마취과 전문의 상주 병원에서의 치료를 안내해 드립니다.\nQ.전신질환이 있는데 수면치료를 받아도 안전한가요?A.질환이 조절되고 있다면 대부분 가능합니다. 오히려 치료 중 긴장으로 혈압이 오르거나 협심증이 유발되는 것을 막아주는 경우도 있어, 고혈압·심혈관질환 환자에게 진정이 도움이 되기도 합니다. 다만 사전 검사와 약물 확인이 반드시 선행됩니다.\nQ.수면치료와 전신마취는 어떻게 다른가요?A.수면치료는 의식이 옅게 남아 있는 진정 상태로, 스스로 호흡하며 부르면 반응할 수 있습니다. 기도에 관을 넣고 호흡을 기계가 담당하는 전신마취와 달리 회복이 빠르고 부담이 적어 치과 치료에 주로 사용됩니다.\nQ.수면치료를 받을 수 없는 경우도 있나요?A.심한 수면무호흡증, 조절되지 않는 심부전이나 폐질환, 중증 비만, 진정제 알레르기가 있는 경우에는 제한될 수 있습니다. 이런 경우 국소마취로 나누어 진행하거나 마취과 협진이 가능한 병원 치료를 권해드립니다.\nQ.수술 전에 금식을 해야 하나요? 먹던 약은요?A.보통 시술 6~8시간 전부터 음식과 음료를 제한합니다. 다만 혈압약·심장약처럼 중단하면 위험한 약은 소량의 물과 함께 복용하시는 경우가 많으므로, 복용 중인 약 목록을 미리 알려주시면 개별 안내드립니다.\nQ.치료 중에는 어떻게 관찰하나요?A.진정 시작부터 회복까지 혈압, 맥박, 심전도, 산소포화도를 지속적으로 감시합니다. 응급 상황에 대비한 산소 공급 장치와 응급 약제를 갖춘 상태에서 진행하며, 이상 징후가 보이면 즉시 치료를 중단하고 회복시킵니다.\nQ.끝나면 바로 집에 갈 수 있나요?A.회복실에서 30분~1시간 정도 안정을 취한 뒤 귀가하십니다. 당일에는 운전과 음주가 불가능하고 판단력이 완전히 돌아오지 않을 수 있으므로 반드시 보호자와 동행해 주셔야 하며, 고령이거나 지병이 있는 분은 당일 혼자 지내지 않으시는 것이 좋습니다.\n\n연결\n전신질환 임플란트 페이지와 상호 링크\n4-4. [c] 일반 · 보존 진료 — 10개 페이지\n파트 공통 슬로건 — 더굿모닝치과는 자연치아 살리기를 우선으로 생각합니다\n\n아무리 완벽한 치료와 좋은 재료여도, 가장 좋은 것은 자연치아입니다.\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 먹던 약을 끊어야 하나요?\n현재 답변: 임의로 중단하지 마시고 먼저 알려주세요. 복용 중인 약 목록과 처방 병원을 확인해 유지·조정 여부를 개별 안내합니다. 금식 중 약 복용도 반드시 받은 안내를 따르세요.\n\n질문: 전신질환이 있는데 수면치료를 받아도 안전한가요?\n현재 답변: 의식하진정이 도움이 될 수 있지만 모든 분께 적합하지는 않습니다. 전신 상태·복용 약·기도 위험과 치료 범위를 확인한 뒤 결정하며, 필요한 경우 상급 의료기관 진료를 안내합니다.\n\n질문: 수면치료와 전신마취는 어떻게 다른가요?\n현재 답변: 의식하진정은 보통 스스로 호흡하고 말이나 자극에 반응할 수 있는 상태입니다. 전신마취는 의식이 없는 상태로 기도·호흡 관리가 필요합니다. 다만 진정도 예상보다 깊어져 호흡 억제가 생길 수 있어 상태 관찰과 응급 대응이 필요합니다.\n\n질문: 수술 전에 금식을 해야 하나요? 먹던 약은요?\n현재 답변: 금식은 위 내용물의 역류와 흡인 위험을 줄이기 위해 필요합니다. 음식 종류와 진정 계획, 건강 상태에 따라 기준이 다르므로 예약 시 받은 개별 안내를 따르세요. 안내와 다르게 드셨다면 숨기지 말고 알려주세요. 복용 약은 임의로 중단하지 말고 미리 알려주세요.\n\n질문: 치료 중에는 어떻게 관찰하나요?\n현재 답변: 진정부터 회복까지 혈압·맥박·산소포화도 등 환자 상태를 관찰하고 이상이 있으면 필요한 응급 대응을 시행합니다. 모니터링이 위험 자체를 없애는 것은 아닙니다.\n\n질문: 끝나면 바로 집에 갈 수 있나요?\n현재 답변: 회복 시간은 약물과 전신 상태에 따라 다릅니다. 의료진이 회복을 확인한 뒤 성인 보호자와 귀가합니다. 당일 운전·음주·기계 조작·중요한 의사결정은 피하고, 활동 재개는 개별 안내를 따르세요.", "source": "제공 개편 제안서 1160–1205행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-natural-tooth','{"key": "copy-review-natural-tooth", "category": "approval", "branch": "all", "title": "자연치아 살리기 · 원문/현재 답변 대조", "body": "제공 제안서 1206–1268행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n① 자연치아 살리기   ( /treatments/tooth-preservation )\n뽑기 전에, 살릴 방법을 먼저 찾습니다\n아무리 완벽한 치료와 좋은 재료여도 가장 좋은 것은 자연치아입니다. 발치를 결정하기 전에 보존 가능성부터 확인합니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 다른 치과에서 뽑아야 한다는 말을 들었어요.\n· 신경치료를 받았는데 계속 아프고 고름이 나와요.\n· 치아가 잇몸선 아래로 부러졌어요.\n· 치주염으로 이가 흔들리는데 뽑지않고 더 쓸수없나요?\n· 뿌리 끝에 물혹(낭종)이 있다고 들었어요.\n· 임플란트는 아직 하고 싶지 않아요.\n③ 치료 설명\n자연치아 살리기란?\n발치 여부는 흔들림 하나로 결정되지 않습니다. 남아 있는 잇몸뼈의 양, 뿌리의 상태, 뿌리 끝 염증의 범위, 남은 치아 구조의 양을 함께 보고 판단합니다. 더굿모닝치과는 발치를 결정하기 전에 보존 가능성부터 확인합니다.\n\n· 살리기 위해 시행하는 술식\n  - 재신경치료(재근관치료) : 이전 신경치료가 완전하지 않아 염증이 남은 경우 근관을 다시 정리합니다\n  - 치근단 절제술 : 뿌리 끝 염증이나 낭종을 직접 제거하고 뿌리 끝을 밀봉합니다\n  - 치관연장술(CLP) : 잇몸선 아래로 부러진 치아에서 잇몸과 뼈를 다듬어 보철을 씌울 높이를 확보합니다\n  - 치주조직유도재생술(GTR) : 치주염으로 녹은 잇몸뼈 부위에 조직 재생을 유도해 지지 조직을 되살립니다\n  - 치근 절제술 : 어금니에서 여러 뿌리 중 문제가 있는 뿌리만 제거하고 나머지를 살립니다\n  - 치주 수술 · 골이식 : 깊은 치주낭을 열어 염증과 치석을 제거하고 필요 시 골이식을 병행합니다\n\n· 살릴 수 없는 경우도 있습니다\n뿌리가 세로로 갈라지는 치근 수직파절은 세균이 들어가기 쉽고 다시 붙이기도 어려워 대부분 보존이 어렵습니다. 남은 치아 구조가 거의 없거나 잇몸뼈가 대부분 소실된 경우도 마찬가지입니다. 이런 경우에는 솔직하게 말씀드리고 다음 단계를 함께 계획합니다.\n\n· 자연치아를 더 오래 쓰면 그동안 잇몸뼈가 보존되어, 이후 임플란트를 하더라도 조건이 유리해집니다\n④ 차별점\n1. 발치 전에 보존 가능성을 먼저 검토하는 것을 원칙으로 합니다\n2. 치주과 전문의가 치근단 절제술·치관연장술·치주조직유도재생술을 직접 시행합니다\n3. 타 치과에서 발치 판정을 받고 오신 케이스를 다수 진료해 왔습니다\n4. 살릴 수 없는 경우는 가능성이 낮다고 솔직하게 말씀드립니다\n5. 여러 치아를 한 번에 정리해야 하는 경우 수면(의식하진정) 병행 가능\n6. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 정밀 재검진 (CT·구내 검사로 잔존 골량·뿌리 상태·파절 여부·염증 범위 확인) → ② 보존 가능성 판단 및 설명 (어떤 술식이 필요한지, 예상 사용 기간) → ③ 보존 치료 시행 (재신경치료·치근단 절제술·치관연장술·치주 수술 등) → ④ 필요 시 크라운으로 보호 후 정기 경과 관찰\n⑥ 전후 사례\n타 치과 발치 판정 치아 보존 케이스 / 치근단 절제술 / 치관연장술로 잇몸선 아래 부러진 치아 보존 / 치주조직유도재생술 케이스 → 비포/애프터 연결\n⑦ FAQ\nQ. 다른 치과에서 뽑으라고 했는데 살릴 수 있나요?\nA. 가능한 경우가 있습니다. 실제로 발치 판정을 받고 오신 치아를 보존한 사례가 있습니다. 다만 상태에 따라 어려운 경우도 있어 CT로 먼저 확인합니다.\nQ. 치근 수직파절은 살릴 수 없나요?\nA. 대부분 어렵습니다. 뿌리가 세로로 쪼개지면 세균이 들어가기 쉽고 다시 붙이기도 어렵기 때문입니다. 정확한 판단은 검진을 통해 이루어집니다.\nQ. 신경치료 후 고름이 생겼는데 다시 살릴 수 있나요?\nA. 가능한 경우가 있습니다. 근관을 다시 정리하는 재신경치료나, 뿌리 끝 염증을 직접 제거하는 치근단 절제술을 시행합니다.\nQ. 잇몸선 아래로 부러졌는데 씌울 수 있나요?\nA. 치관연장술로 잇몸과 뼈를 다듬어 보철을 씌울 높이를 확보할 수 있는 경우가 있습니다. 발치라는 말을 들으셨더라도 먼저 확인해 보시길 권합니다.\nQ. 흔들리는 이는 다 뽑아야 하나요?\nA. 그렇지 않습니다. 흔들림의 원인과 정도, 남은 잇몸뼈의 양에 따라 판단이 달라집니다. 치주치료로 안정되는 경우도 있습니다.\nQ. 녹은 잇몸뼈가 다시 생기나요?\nA. 자연적으로 회복되지는 않습니다. 다만 조직 재생을 유도하는 치료로 일부 회복을 기대할 수 있는 경우가 있습니다.\nQ. 살려도 얼마나 쓸 수 있나요?\nA. 남은 뼈와 뿌리 상태에 따라 다릅니다. 예상되는 범위를 솔직하게 말씀드리고 함께 결정합니다.\nQ. 결국 임플란트를 하게 되면 손해 아닌가요?\nA. 자기 치아를 더 쓰는 동안 잇몸뼈가 보존된다는 이점이 있습니다. 다만 가능성이 낮은 경우까지 무리해 권하지는 않습니다.\nQ. 보존 치료도 수면으로 받을 수 있나요?\nA. 가능합니다. 여러 치아를 한 번에 정리해야 하거나 치주 수술이 필요한 경우 의식하진정을 권해드립니다. <수면치료 링크>\nQ. 보험이 되나요?\nA. 신경치료와 잇몸치료 등 상당수 항목이 건강보험 적용됩니다. 수술적 처치와 보철은 항목에 따라 다르며 상담 시 안내드립니다.\n연결\n충치치료 / 신경치료 / 크라운 / 치주염 / 잇몸치료 / 잇몸라인\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 다른 치과에서 뽑으라고 했는데 살릴 수 있나요?\n현재 답변: 가능한 경우가 있습니다. 남은 치아 구조와 뿌리·잇몸뼈 상태를 다시 확인하고 보존의 가능성과 한계를 설명합니다. 보존이 어렵다면 그 이유와 대안을 함께 안내합니다.\n\n질문: 결국 임플란트를 하게 되면 손해 아닌가요?\n현재 답변: 자연치아를 더 사용할 수 있다는 이점이 있지만 예후가 나쁘거나 염증이 지속되면 주변 조직에 불리할 수도 있습니다. 가능성이 낮은 경우까지 무리하게 권하지 않고 예상 이점과 위험을 함께 비교합니다.\n\n질문: 보존 치료도 수면으로 받을 수 있나요?\n현재 답변: 의식하진정이 도움이 될 수 있지만 모든 분께 적합하지는 않습니다. 전신 상태·복용 약·기도 위험과 치료 범위를 확인한 뒤 결정하며, 필요한 경우 상급 의료기관 진료를 안내합니다.\n\n질문: 보험이 되나요?\n현재 답변: 보험 적용 여부는 연령, 구강 상태, 진료 목적과 항목별 현행 기준에 따라 달라집니다. 진단 후 적용 가능한 항목과 비급여 항목을 구분해 안내받으세요. 진정 비용과 함께 받는 치료 비용도 별도로 확인해야 합니다.", "source": "제공 개편 제안서 1206–1268행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-cavity','{"key": "copy-review-cavity", "category": "approval", "branch": "all", "title": "충치치료 · 원문/현재 답변 대조", "body": "제공 제안서 1269–1302행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n② 충치치료   ( /treatments/cavity )\n충치는 스스로 낫지 않습니다. 빠를수록 적게 깎습니다\n치아는 재생능력이 없기 때문에 한 번 생긴 충치 치료는 시간을 지체한 만큼 시간과 비용, 고통이 필요합니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 찬물이 시리다\n· 음식물이 자꾸 낀다\n· 치아에 검은 점이 보인다\n· 씹을 때 특정 부위가 불편하다\n③ 치료 설명\n· 충치 진행 정도에 따른 치료법 — 초기는 레진, 범위가 넓으면 인레이·온레이, 신경까지 진행되면 신경치료 후 크라운\n· 빨리 치료했을 때와 미뤘을 때의 비용·기간·삭제량 비교\n· 각 단계에서 해당 진료 페이지로 연결\n④ 차별점\n1. 자연치아 살리기를 최우선으로 합니다.\n2. NO PAIN 무통마취기 사용\n3. 원내 기공소로 인레이·크라운 제작 기간 단축\n4. 수면 병행 가능\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 검진을 통하여 충치의 상태를 확인합니다 → ② 자연치아를 최소삭제하여 충치를 제거합니다 → ③ 빈 공간을 보강하기 위한 충전재료를 제작합니다 → ④ 완성된 재료를 치아에 채워넣습니다 (기존 홈페이지 도식 그대로)\n⑥ 전후 사례\n충치 범위별 치료 케이스\n⑦ FAQ\nQ. 충치 초기 증상은 어떻게 알 수 있나요?A. 찬물이 시리거나 음식이 자꾸 끼는 것이 가장 흔한 신호입니다. 치아에 검은 점이 보이기도 하지만 착색과 구분이 어렵습니다. 초기 충치는 통증이 없어 엑스레이로 확인해야 정확합니다.\nQ. 겉은 멀쩡한데 안쪽이 썩었다는 게 무슨 말인가요?A. 치아 표면은 단단해 작은 구멍만 남고, 그 아래 무른 상아질부터 넓게 퍼지기 때문입니다. 그래서 엑스레이로 보면 예상보다 범위가 큰 경우가 흔합니다.\nQ. 치아 사이 충치는 왜 잘 안 보이나요?A. 인접면 충치는 치아와 치아가 맞닿은 면에서 시작해 겉에서 보이지 않습니다. 칫솔이 닿지 않는 부위라 치실을 쓰지 않으면 진행되기 쉽고, 엑스레이로만 확인됩니다.\nQ. 충치치료가 무서워서 몇 년째 미뤘습니다.A. 그런 분들을 위해 수면(의식하진정)으로 진행하는 방법이 있습니다. 오래 미뤄 다발성 충치가 된 경우 여러 개를 한 회차에 묶어 정리할 수 있습니다. <수면치료 링크>\nQ. 충치를 예방하려면 어떻게 해야 하나요?A. 칫솔질만으로는 치아 사이가 닦이지 않아 치실이나 치간칫솔을 함께 쓰셔야 합니다. 6개월~1년마다 스케일링과 검진을 받으시면 초기에 발견할 수 있습니다. <스케일링 링크>\n\n연결\n레진치료 / 인레이·온레이 / 신경치료 / 크라운 (관문 페이지 역할)\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 충치 초기 증상은 어떻게 알 수 있나요?\n현재 답변: 찬물이 시리거나 음식이 끼고 검은 점이 보일 수 있지만 충치만의 증상은 아닙니다. 초기에는 통증이 없기도 하므로 구강 검사와 필요한 영상 검사로 확인합니다.\n\n질문: 치아 사이 충치는 왜 잘 안 보이나요?\n현재 답변: 치아가 맞닿는 면에서 시작해 겉에서 잘 보이지 않을 수 있습니다. 치실 관리와 함께 구강 검사·필요한 영상 검사로 확인합니다.\n\n질문: 충치치료가 무서워서 몇 년째 미뤘습니다.\n현재 답변: 무서웠던 이유를 먼저 말씀해 주세요. 치료 시간을 나누거나 의식하진정을 검토할 수 있습니다. 진정과 한 회차의 치료 범위는 전신 상태와 충치의 양을 확인한 뒤 결정합니다.", "source": "제공 개편 제안서 1269–1302행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-resin','{"key": "copy-review-resin", "category": "approval", "branch": "all", "title": "레진치료 · 원문/현재 답변 대조", "body": "제공 제안서 1303–1339행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n③ 레진치료 ( /treatments/resin )\n당일에 끝나는, 가장 부담 적은 충치치료\n\n치아 색과 유사한 재료로 삭제량을 최소화해 당일에 복원합니다. 본을 뜨지 않아 한 번 내원으로 마무리됩니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 충치가 초기라고 들었다\n· 치아 사이에 좁은 틈이 생겼다\n· 앞니가 살짝 깨졌다\n· 한 번에 끝내고 싶다\n③ 치료 설명\n· 적용 가능한 범위 : 초기~중기 충치, 앞니 작은 파절, 치아 사이 좁은 틈\n· 적용이 어려운 경우 : 충치 범위가 넓거나 씹는 힘을 많이 받는 부위 → 인레이·온레이 권장\n· 인레이와 비교 표 : 비용 · 수명 · 삭제량 · 내원 횟수\n· 유지 관리 : 변색·마모 가능성과 정기 점검 주기\n④ 차별점\n1. 삭제량 최소화 원칙\n2. 만 12세 이하 영구치 광중합형 복합레진 충전 건강보험 적용 안내\n3. 당일 1회 내원 완료\n4. 수면 병행 가능\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 검진 및 범위 확인 → ② 충치 제거(최소삭제) → ③ 색 선택 후 레진 충전 → ④ 형태 성형 및 연마 (1회 내원)\n⑥ 전후 사례\n앞니 파절 · 치아 사이 충치 케이스\n⑦ FAQ\nQ. 레진은 얼마나 쓰나요?A. 보통 5년 안팎입니다. 씹는 힘을 많이 받는 어금니일수록 짧아지고, 범위가 작을수록 오래 유지됩니다.\nQ. 변색되나요?A. 시간이 지나면 경계 부위가 누렇게 변하거나 착색될 수 있습니다. 커피·흡연이 영향을 줍니다. 변색되면 표면을 다듬거나 다시 채워 넣습니다.\nQ. 심미레진과 무엇이 다른가요?A. 목적이 다릅니다. 레진치료는 충치를 제거하고 메우는 치료이고, 심미레진은 충치가 없어도 벌어진 앞니나 깨진 부위의 모양을 개선하는 치료입니다. <심미레진 링크>\nQ. 어떤 경우에 레진으로 하나요?A. 초기에서 중기 정도의 충치, 앞니가 작게 깨진 경우, 치아 사이 좁은 틈에 적합합니다. 씹는 힘을 크게 받지 않는 부위일수록 유리합니다.\nQ. 어금니도 레진으로 되나요?A. 범위가 작으면 가능합니다. 씹는 면을 넓게 덮어야 할 정도면 레진은 깨지거나 닳기 쉬워 인레이·온레이를 권해드립니다. <인레이·온레이 링크>\nQ. 레진과 인레이 중 무엇이 나은가요?A. 레진은 치아를 덜 깎고 당일에 끝나며 비용이 적습니다. 인레이는 본을 떠 제작해 넓은 범위에 더 튼튼합니다. 충치 범위와 씹는 힘을 보고 정합니다.\nQ. 미백을 하면 레진도 같이 밝아지나요?A. 아닙니다. 미백은 자연치아에만 작용해 레진 부위만 어둡게 남습니다. 미백을 계획하고 계시면 미백을 먼저 하고 그 색에 맞춰 레진을 다시 하시는 편이 좋습니다. <치아미백 링크>\n연결\n충치치료 / 인레이·온레이 / 심미레진 (이 페이지는 충치 치료, 심미레진은 앞니 형태·색 개선)\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 레진은 얼마나 쓰나요?\n현재 답변: 범위와 위치, 씹는 힘, 구강 위생에 따라 달라집니다. 일정한 수명을 보장하지 않으며 마모·파절·변색과 경계의 충치를 정기적으로 확인합니다.\n\n질문: 심미레진과 무엇이 다른가요?\n현재 답변: 목적에 차이가 있습니다. 레진치료는 충치나 손상 부위를 채우는 치료이고, 심미레진은 앞니의 작은 틈이나 파절 등 형태 개선에 중점을 둡니다.\n\n질문: 레진과 인레이 중 무엇이 나은가요?\n현재 답변: 레진은 구강 안에서 직접 수복하고 인레이는 별도 제작해 붙입니다. 충치 범위·남은 치아 구조·씹는 힘과 비용·일정을 함께 보고 결정합니다.", "source": "제공 개편 제안서 1303–1339행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-crown','{"key": "copy-review-crown", "category": "approval", "branch": "all", "title": "크라운 · 원문/현재 답변 대조", "body": "제공 제안서 1340–1372행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n④ 크라운   ( /treatments/crown )\n남아있는 자연치아를 보호하는 보철치료\n\n충치나 잇몸질환, 전신질환, 외상 등에 의해 치아 일부 또는 전부가 상실되거나 손상되어 제 역할을 하지 못할 경우, 인공 보철물로 치아를 보호해주는 치료입니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 신경치료를 받았다\n· 치아가 크게 깨졌다\n· 기존 보철물이 오래되어 들뜬다\n· 씹을 때 갈라지는 느낌이 난다\n③ 치료 설명\n보철치료의 종류 3가지 (기존 홈페이지 설명 텍스트 그대로)\nㄱ. 골드 크라운 : 금으로 만들어진 재료입니다. 강도와 탄성이 자연치아 재질과 가장 유사하며, 구강 내 알레르기 반응을 일으키지 않아 주로 큰 범위에 가장 많이 사용합니다.\nㄴ. PFM 크라운 : 저렴한 비용으로 부담이 적고 골드 크라운보다 심미기능이 뛰어난 재료입니다. 내부가 금속으로 되어 있어 강도가 높습니다.\nㄷ. 지르코니아 크라운 : 견고함과 자연치아색을 함께 갖춘 재료입니다. 치아삭제량이 가장 적고 파절 위험성도 적어 가장 많이 선호합니다.\n④ 차별점\n1. 원내 자체 기공소 — 제작부터 당일 조정까지 한 건물에서 (내원 횟수 최소화)\n2. 치과보철과 전문의가 설계와 교합을 담당합니다\n3. 3shape 트리오스 5 구강스캐너로 본을 떠 구역감이 적습니다\n4. 수면 병행 가능\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 진단 및 재료 선택 → ② 치아 삭제 및 스캔 → ③ 원내 기공소 제작 · 임시치아 착용 → ④ 최종 장착 및 교합 조정\n⑥ 전후 사례\n크라운 재제작 · 파절 치아 복원 케이스\n⑦ FAQ\nQ. 어떤 재료가 좋나요?A. 부위에 따라 다릅니다. 씹는 힘이 큰 어금니는 강도와 탄성이 좋은 골드, 잘 보이는 부위는 자연치아색에 가까운 지르코니아를 주로 씁니다. PFM은 강도와 심미성을 함께 갖추면서 비용 부담이 적습니다. 치아 위치와 씹는 습관, 비용을 함께 보고 정합니다.Q. 신경치료 후 꼭 크라운을 씌워야 하나요?A. 씌우셔야 합니다. 신경을 제거한 치아는 영양 공급이 끊겨 부서지기 쉬워집니다. 씌우지 않고 쓰다가 뿌리까지 세로로 갈라지면 대부분 발치하게 되어, 결국 임플란트로 이어집니다.\nQ. 크라운은 계속 흰색인가요?A. 시간이 지나면서 경계 부위가 누렇게 변하거나 착색될 수 있습니다. 커피·홍차·와인·흡연이 영향을 줍니다. 변색되면 표면을 다듬거나 다시 채워 넣습니다.\nQ. 앞니와 어금니에 다른 재료를 써도 되나요?A. 그렇게 하는 경우가 많습니다. 앞니는 심미, 어금니는 강도를 우선으로 보기 때문입니다. 다만 여러 개를 함께 하실 때는 색이 어우러지도록 계획합니다.\n연결\n신경치료 / 인레이·온레이 / 심미보철 (크라운은 기능 회복 중심, 심미보철은 앞니 심미 중심)\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 어떤 재료가 좋나요?\n현재 답변: 치아 위치, 남은 구조, 씹는 습관과 심미적 요구에 따라 다릅니다. 골드·PFM·지르코니아의 색·강도·필요 두께·파절 가능성·비용을 함께 비교해 결정합니다.\n\n질문: 신경치료 후 꼭 크라운을 씌워야 하나요?\n현재 답변: 특히 어금니처럼 씹는 힘을 크게 받거나 남은 치아 구조가 적으면 크라운 등 보호 수복을 권할 수 있습니다. 신경치료한 모든 치아에 일률적으로 크라운을 씌우는 것은 아니며 남은 구조와 교합을 평가합니다.\n\n질문: 크라운은 계속 흰색인가요?\n현재 답변: 보철물 자체와 경계의 색 변화는 재료, 표면 착색, 잇몸 변화에 따라 다릅니다. 변색이 보이면 연마로 가능한지, 보철 또는 잇몸 치료가 필요한지 확인합니다.", "source": "제공 개편 제안서 1340–1372행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-inlay','{"key": "copy-review-inlay", "category": "approval", "branch": "all", "title": "인레이 · 온레이 · 원문/현재 답변 대조", "body": "제공 제안서 1373–1405행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑤ 인레이 / 온레이 ( /treatments/inlay )\n충치 범위가 넓다면, 정밀하게 채워 넣습니다\n\n본을 떠 제작한 보철물을 삭제한 부위에 정확히 맞춰 넣는 방식으로, 레진보다 넓은 범위를 튼튼하게 복원합니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 충치 범위가 넓다고 들었다\n· 예전에 한 아말감을 바꾸고 싶다\n· 씹는 면이 자주 깨진다\n· 레진으로는 어렵다고 들었다\n③ 치료 설명\n· 인레이와 온레이의 차이 — 씹는 면(교두)을 덮는 범위에 따라 구분\n· 재료별 비교 : 골드 / 세라믹 / 지르코니아 (강도 · 심미성 · 비용)\n· 레진과의 선택 기준 : 충치 범위 · 씹는 힘 · 수명 · 비용\n④ 차별점\n1. 3shape 트리오스 5 구강스캐너로 본뜨기 — 무른 인상재 없이 촬영해 구역감이 적습니다\n2. 원내 기공소 제작으로 제작 기간 단축\n3. 최소삭제 설계\n4. 수면 병행 가능\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 1차 내원 — 충치 제거 및 스캔 → ② 원내 기공소 제작 → ③ 2차 내원 — 장착 및 교합 조정\n⑥ 전후 사례\n아말감 교체 · 넓은 충치 복원 케이스\n⑦ FAQ\nQ. 인레이와 온레이는 무엇이 다른가요?A. 덮는 범위가 다릅니다. 인레이는 씹는 면 안쪽의 파인 부분만 채우고, 온레이는 볼록한 부분(교두)까지 덮습니다. 치아 벽이 약해져 있으면 온레이로 감싸주어야 갈라지지 않습니다.\nQ. 인레이 재료는 어떤 걸 쓰나요?A. 골드, 세라믹, 지르코니아를 주로 씁니다. 골드는 강도와 탄성이 자연치아와 가장 유사하고, 세라믹과 지르코니아는 치아 색과 비슷해 눈에 띄지 않습니다.\nQ. 인레이와 크라운은 어떻게 정하나요?A. 남은 치아 구조가 기준입니다. 벽이 어느 정도 남아 있으면 인레이로 부분만 채우고, 벽이 거의 없거나 신경치료를 받은 치아는 전체를 덮는 크라운이 안전합니다. <크라운 링크>\nQ. 인레이는 얼마나 쓰나요?A. 관리 상태에 따라 다르지만 보통 7~10년 이상 사용하십니다. 수명을 좌우하는 것은 재료보다 그 아래 치아와 잇몸의 상태입니다.\n연결\n충치치료 / 레진치료 / 크라운\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 인레이와 온레이는 무엇이 다른가요?\n현재 답변: 덮는 범위가 다릅니다. 인레이는 주로 씹는 면 안쪽의 결손을 채우고 온레이는 교두까지 덮습니다. 남은 치아 벽과 파절 위험을 보고 범위를 정합니다.\n\n질문: 인레이 재료는 어떤 걸 쓰나요?\n현재 답변: 골드·세라믹 등에서 치아 위치와 수복 범위, 재료의 두께·접착 조건을 고려해 선택합니다. 재료마다 심미성·강도·비용의 장단점이 있습니다.\n\n질문: 인레이와 크라운은 어떻게 정하나요?\n현재 답변: 남은 치아 구조와 균열, 씹는 힘이 기준입니다. 인레이·온레이로 보존할 수 있는지, 크라운으로 보호해야 하는지 확인합니다. 신경치료 여부만으로 일률적으로 정하지 않습니다.\n\n질문: 인레이는 얼마나 쓰나요?\n현재 답변: 수명은 재료뿐 아니라 남은 치아와 잇몸, 씹는 힘, 위생 관리에 따라 달라집니다. 경계의 충치와 탈락·파절을 정기적으로 확인합니다.", "source": "제공 개편 제안서 1373–1405행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-root-canal','{"key": "copy-review-root-canal", "category": "approval", "branch": "all", "title": "신경치료 · 원문/현재 답변 대조", "body": "제공 제안서 1406–1440행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑥ 신경치료   ( /treatments/root-canal )\n빼지 않고 살리는 마지막 방법\n\n충치가 신경까지 진행된 경우, 감염된 신경을 제거하고 내부를 소독·충전해 자연치아를 보존합니다. 더굿모닝치과가 자연치아 살리기를 우선으로 생각하는 이유입니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 가만히 있어도 욱신거린다\n· 밤에 더 아프다\n· 뜨거운 것에 아프다\n· 잇몸에 고름주머니가 생겼다\n· 예전에 치료한 치아가 다시 아프다\n③ 치료 설명\n· 치료 후 반드시 크라운이 필요한 이유 — 신경을 제거한 치아는 부서지기 쉽습니다\n· 재신경치료(재근관치료) 안내 — 이전에 치료한 치아가 다시 아픈 경우\n· 치료 횟수와 기간 안내 (평균 「○」회 내원)\n④ 차별점\n1. 자연치아 살리기 우선 원칙\n2. NO PAIN 무통마취기로 통증 최소화\n3. 신경치료 후 크라운까지 원내에서 이어서 진행\n4. 수면 병행 가능\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 감염 신경 제거 → ② 근관 내부 세척·소독 → ③ 충전재로 밀봉 → ④ 크라운으로 보호\n⑥ 전후 사례\n고름주머니 · 재신경치료 케이스\n⑦ FAQ\nQ. 신경치료를 해야 하는 증상은 무엇인가요?A. 가만히 있어도 욱신거리거나, 밤에 더 아프거나, 뜨거운 것에 통증이 심해지면 충치가 신경까지 진행된 경우가 많습니다. 잇몸에 고름주머니가 생긴 경우도 해당됩니다.\nQ. 신경치료를 하면 치아가 죽는 건가요?A. 감염된 신경을 제거하므로 감각은 없어집니다. 다만 치아 자체는 그대로 남아 씹는 기능을 하기 때문에, 뽑지 않고 살리는 마지막 방법입니다.\nQ. 신경치료 중에 임시로 때운 게 빠졌어요.A. 그대로 두시면 세균이 근관 안으로 다시 들어갑니다. 가능한 한 빨리 내원해 주시고, 그때까지 그쪽으로 씹지 마십시오.\nQ. 신경치료한 치아가 변색되는데 왜 그런가요?A. 신경을 제거하면 영양 공급이 끊겨 치아가 서서히 어두워집니다. 앞니라면 실활치 미백으로 밝히거나 라미네이트·크라운으로 개선할 수 있습니다. <치아미백 / 라미네이트 링크>\nQ. 신경치료를 받았는데 또 아픕니다.A. 근관 안에 세균이 남아 재감염된 경우가 많습니다. 근관을 다시 정리하는 재신경치료나, 뿌리 끝 염증을 직접 제거하는 치근단 절제술로 살릴 수 있습니다. \n연결\n충치치료 / 크라운 / 치주염\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 신경치료를 하면 치아가 죽는 건가요?\n현재 답변: 치아 내부의 감염된 치수를 제거하고 밀봉하는 치료입니다. 내부 감각은 달라지지만 치아 주변 조직의 감각은 남아 있어 씹을 때 통증이 생길 수도 있습니다. 치아를 보존해 기능하도록 하는 것이 목적입니다.\n\n질문: 신경치료한 치아가 변색되는데 왜 그런가요?\n현재 답변: 남아 있는 조직 성분이나 혈액 분해 산물, 근관 재료 등 여러 원인으로 변색될 수 있습니다. 원인을 확인하고 실활치 미백이나 적절한 보철 방법을 검토합니다.\n\n질문: 신경치료를 받았는데 또 아픕니다.\n현재 답변: 재감염뿐 아니라 균열·교합·잇몸 문제 등 원인이 다양합니다. 원인을 확인해 재신경치료나 치근단 수술로 보존할 수 있는지 평가하고 한계도 설명합니다.", "source": "제공 개편 제안서 1406–1440행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-whitening','{"key": "copy-review-whitening", "category": "approval", "branch": "all", "title": "치아미백 · 원문/현재 답변 대조", "body": "제공 제안서 1441–1477행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑦ 치아미백   ( /treatments/whitening )\n커피·나이로 어두워진 치아를 밝게\n\n치아를 깎지 않고 색만 밝게 하는 가장 부담 적은 심미 치료입니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 커피·와인을 자주 마신다\n· 스케일링을 받아도 색이 그대로다\n· 사진 찍을 때 치아색이 신경 쓰인다\n· 나이가 들며 치아가 누렇게 변했다\n③ 치료 설명\n· 착색 원인 구분 : 외인성(커피·와인·흡연·음식) / 내인성(노화·약물·외상)\n· 미백 방식 비교 : 전문가 미백(내원) / 자가 미백(가정) / 병행 — 기간 · 밝기 · 비용\n· 스케일링으로 해결되지 않는 착색이 있다는 점 안내\n· 미백이 적합하지 않은 경우 : 보철물·레진이 있는 치아, 심한 변색 → 라미네이트·심미레진 연결\n④ 차별점\n1. 착색 원인을 먼저 구분해 미백이 맞는지 판단합니다\n2. 시린 증상 관리 안내\n3. 유지 관리 주기와 재시행 시기 안내\n4. 수면 병행 가능\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 착색 원인 진단 및 방식 결정 → ② 스케일링 등 사전 처치 → ③ 미백 시행(내원 또는 자가) → ④ 색조 확인 및 유지 관리 안내\n⑥ 전후 사례\n미백 전후 케이스\n⑦ FAQ\nQ. 얼마나 밝아지나요?A. 착색 원인에 따라 다릅니다. 커피·와인·흡연으로 인한 겉면 착색은 눈에 띄게 밝아지지만, 노화나 약물로 인한 내부 변색은 개선 폭이 작습니다. 색조 가이드로 기대할 수 있는 정도를 미리 말씀드립니다.\nQ. 시리지 않나요?A. 미백 중이나 직후에 시린 증상이 흔하지만 대부분 며칠 안에 가라앉습니다. 심하면 농도를 낮추거나 간격을 두고 진행합니다.\nQ. 얼마나 유지되나요?A. 보통 1~2년입니다. 커피·와인을 자주 드시거나 흡연하시면 착색이 빨리 돌아오며, 색이 흐려지면 가정용 미백으로 보충하실 수 있습니다.\nQ. 보철물도 같이 밝아지나요?A. 아닙니다. 미백은 자연치아에만 작용해 크라운·라미네이트·레진은 원래 색으로 남습니다. 앞니에 보철물이 있으시면 미백을 먼저 하고 그 색에 맞춰 다시 하는 순서를 권해드립니다. <심미보철 / 심미레진 링크>\n\n연결\n스케일링 / 라미네이트 / 심미레진\n영상 자산\n''스케일링도 소용없는 치아 착색'' 내용 텍스트화\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 얼마나 밝아지나요?\n현재 답변: 변색의 원인과 치아 상태에 따라 다릅니다. 표면 착색은 연마·스케일링으로 개선될 수 있고 치아 자체의 색은 미백 적합성을 평가합니다. 색조 가이드로 기대할 수 있는 범위와 한계를 설명합니다.\n\n질문: 얼마나 유지되나요?\n현재 답변: 유지 기간은 생활 습관과 변색 원인에 따라 다릅니다. 커피·와인·흡연은 재착색에 영향을 주며 추가 미백은 치아와 잇몸 상태를 확인한 뒤 결정합니다.", "source": "제공 개편 제안서 1441–1477행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-prosthesis','{"key": "copy-review-prosthesis", "category": "approval", "branch": "all", "title": "심미보철 · 원문/현재 답변 대조", "body": "제공 제안서 1478–1511행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑧ 심미보철 ( /treatments/prosthesis )\n만족도가 높은 더굿모닝치과 심미보철\n\n개인의 구강상태를 고려하여 가장 적합한 보철물을 통해 치아의 기능적 회복 및 심미적인 부분까지 개선하는 치료입니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 앞니 보철 색이 옆 치아와 다르다\n· 예전에 한 보철이 티가 난다\n· 잇몸 경계가 검게 보인다\n· 앞니 모양을 바꾸고 싶다\n③ 치료 설명\n· 보철물 종류 비교 : 지르코니아 · PFM · 골드 크라운 (크라운 페이지와 동일 표 공유)\n· 앞니 보철과 어금니 보철의 설계 차이 — 앞니는 색조·투명도, 어금니는 강도 우선\n· 라미네이트·심미레진과의 선택 기준\n④ 차별점\n1. 원내 자체 기공소를 운영하여, 보철의 기능적인 면과 주변 치아와 조화롭게 어울릴 수 있도록 심미적으로도 좋은 보철물을 만들어 드립니다\n2. 치과보철과 전문의가 직접 설계합니다\n3. 잇몸 라인이 맞지 않는 경우 치주과 전문의와 협진합니다\n4. 수면 병행 가능\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 상담 및 디자인 구상 → ② 치아 삭제 및 스캔 → ③ 원내 기공소 제작 · 임시 보철로 확인 → ④ 최종 장착 및 조정\n⑥ 전후 사례\n심미보철 치료 케이스 (기존 블로그 연결)\n⑦ FAQ\nQ. 크라운과 무엇이 다른가요?A. 같은 보철이지만 우선순위가 다릅니다. 크라운은 손상된 치아를 덮어 씹는 기능을 회복하는 데 중점을 두고, 심미보철은 여기에 색·형태·잇몸 라인까지 함께 맞춥니다. 주로 잘 보이는 앞니 부위에 적용합니다. <크라운 링크>\nQ. 색을 옆 치아와 맞출 수 있나요?A. 원내 자체 기공소에서 기공사와 직접 확인하며 제작해 색조와 투명도를 세밀하게 조정합니다. 외부 기공소를 오가지 않아 색이 맞지 않으면 당일 수정이 가능합니다.\nQ. 몇 개를 해야 자연스러운가요?A. 웃을 때 보이는 범위를 기준으로 좌우 대칭이 맞도록 정합니다. 한 개만 하면 옆 치아와 색이 달라 보일 수 있어, 최소 개수로 조화를 얻는 방향으로 설계합니다.\nQ. 라미네이트와 어떻게 다른가요?A. 덮는 범위가 다릅니다. 라미네이트는 앞면만 얇게 덧붙이고, 심미보철은 치아 전체를 감쌉니다. 치아가 크게 손상됐거나 신경치료를 받았다면 심미보철이 적합합니다. <라미네이트 링크>\n\n연결\n앞니 임플란트 / 라미네이트 / 크라운 / 잇몸라인\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 색을 옆 치아와 맞출 수 있나요?\n현재 답변: 원내 자체 기공소에서 색조·투명도를 확인하며 조정합니다. 자연치아와 완전히 같은 색을 보장하지 않으며 조정 범위와 일정은 보철 상태에 따라 다릅니다.\n\n질문: 몇 개를 해야 자연스러운가요?\n현재 답변: 필요한 최소 범위부터 검토합니다. 웃을 때 보이는 범위와 옆 치아 색을 확인하되 자연스럽게 보이기 위해 건강한 여러 치아를 반드시 함께 치료해야 하는 것은 아닙니다.", "source": "제공 개편 제안서 1478–1511행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-laminate','{"key": "copy-review-laminate", "category": "approval", "branch": "all", "title": "라미네이트 · 원문/현재 답변 대조", "body": "제공 제안서 1512–1548행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑨ 라미네이트 ( /treatments/laminate )\n치아 겉 표면을 최소삭제 후 얇고 자연스러운 인공치아를 덧붙이는 치아성형술\n\n불만족스러운 치아의 배열, 색상, 크기 등을 수정하여 자신감 있는 미소로 밝은 인상을 만듭니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 미백으로 지워지지 않는 변색이 있다\n· 앞니 사이가 벌어졌다\n· 앞니 모양·길이가 고르지 않다\n· 교정까지는 하고 싶지 않다\n③ 치료 설명\n진행 과정 3단계 (기존 홈페이지 자료 그대로)\n· 디자인 구상 : 충분한 상담을 통해 환자가 원하는 바를 파악하고 보철물 기본 틀을 구상합니다.\n· 디자인 구체화 : 전체적인 구강상태, 잇몸과 치아와의 관계 등을 종합하여 기본 디자인을 구체화합니다.\n· 디자인 구현 : 구체화된 보철물을 바탕으로 색상·위치 등을 고려하여 환자에게 맞는 디자인을 구현합니다.\n\n· 심미레진 · 앞니 임플란트와의 선택 기준 비교 표\n④ 차별점\n더굿모닝치과만의 라미네이트 장점 4가지 (기존 자료)\n1. 퀄리티 높은 맞춤형 보철물 제작 가능\n2. 자연스럽고 건강한 치아성형\n3. 빠른 제작으로 내원 횟수 최소화\n4. 정품 정량의 재료만을 사용\n⑤ 치료 과정\n① 디자인 구상(상담) → ② 디자인 구체화 → ③ 최소삭제 및 스캔 · 임시 보철 → ④ 디자인 구현 및 최종 장착\n⑥ 전후 사례\n라미네이트 케이스 3건 (기존 블로그 연결)\n⑦ FAQ\nQ. 치아를 많이 깎아야 하나요?A. 앞면만 얇게 다듬어 크라운보다 삭제량이 훨씬 적습니다. 다만 치아가 앞으로 나왔거나 겹쳐 있으면 더 깎아야 해서, 진단 때 삭제량을 미리 말씀드립니다.\nQ. 무삭제도 가능한가요?A. 케이스에 따라 가능합니다. 치아가 안쪽으로 들어갔거나 사이가 벌어진 경우에 적합하며, 앞으로 나온 치아에 삭제 없이 붙이면 두꺼워 보입니다.\nQ. 몇 개를 해야 하나요?A. 웃을 때 보이는 범위를 기준으로 보통 4~8개를 진행합니다. 한두 개만 하면 옆 치아와 색이 달라 보일 수 있습니다.\nQ. 미백과 무엇이 다른가요?A. 미백은 치아를 깎지 않고 색만 밝히고, 라미네이트는 모양·길이·벌어진 틈까지 바꿉니다. 색만 고민이시면 미백을 먼저 권해드립니다. <치아미백 링크>\n\n연결\n심미레진 / 심미보철 / 치아미백 / 잇몸라인 (잇몸 비율을 먼저 잡아야 하는 경우)\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 치아를 많이 깎아야 하나요?\n현재 답변: 앞면의 필요한 부분을 다듬습니다. 삭제량은 치아 위치·색·교합과 보철 재료에 따라 달라지며, 삭제가 많아질 수 있는 경우 교정 등 다른 대안도 함께 설명합니다.\n\n질문: 몇 개를 해야 하나요?\n현재 답변: 치료가 필요한 치아와 원하는 변화를 확인해 최소 범위를 정합니다. 건강한 여러 치아를 일률적으로 함께 치료할 필요는 없습니다.", "source": "제공 개편 제안서 1512–1548행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-aesthetic-resin','{"key": "copy-review-aesthetic-resin", "category": "approval", "branch": "all", "title": "심미레진 · 원문/현재 답변 대조", "body": "제공 제안서 1549–1588행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑩ 심미레진 ( /treatments/aesthetic-resin )\n하루 만에, 깎지 않고 자연스럽게\n\n깨지거나 벌어진 앞니, 변색된 치아를 치아 색 레진으로 자연스럽게 복원합니다. 치아를 거의 삭제하지 않고 당일 완성이 가능합니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 앞니가 살짝 깨졌다\n· 앞니 사이가 벌어졌다(치간이개)\n· 일부만 색이 다르다\n· 라미네이트는 부담스럽다\n③ 치료 설명\n· 적합한 경우 : 앞니 파절, 치아 사이 벌어짐, 부분 변색, 작은 충치\n· 라미네이트와의 비교 표 — 비용 · 기간 · 삭제량 · 수명 (환자분이 가장 헷갈려 하는 부분)\n· 유지 관리 : 변색·마모 가능성과 재시행 주기\n④ 차별점\n1. 치아를 거의 삭제하지 않습니다\n2. 당일 1회 내원으로 완성됩니다\n3. 색과 형태를 직접 보면서 조정합니다\n4. 수면 병행 가능\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 상담 → ② 색 선택 → ③ 형태 성형 → ④ 연마 (1회 내원)\n⑥ 전후 사례\n치료 전후 사진 3~5건\n⑦ FAQ\nQ. 라미네이트와 무엇이 다른가요?A. 심미레진은 치아를 거의 깎지 않고 그 자리에서 모양을 만들어 당일에 끝납니다. 라미네이트는 앞면을 다듬고 본을 떠 제작하는 대신 색과 형태가 더 오래 유지됩니다. 한두 곳 부분 개선이면 심미레진, 여러 개를 함께 바꾸려면 라미네이트가 적합합니다. <라미네이트 링크>\nQ. 얼마나 유지되나요?A. 보통 5년 안팎입니다. 앞니처럼 씹는 힘을 덜 받는 부위는 더 오래가고, 이갈이가 있거나 앞니로 단단한 것을 자주 깨물면 짧아집니다.\nQ. 변색되나요?A. 시간이 지나며 경계 부위가 누렇게 변할 수 있습니다. 커피·홍차·와인·흡연이 영향을 줍니다. 변색되면 표면을 다듬거나 다시 채워 넣습니다.\nQ. 정말 하루에 끝나나요?A. 네, 본을 뜨지 않아 한 번 내원으로 마무리됩니다. 다만 굳은 직후가 착색에 취약해 하루 정도는 색이 진한 음식을 피해 주세요.\n\n연결\n라미네이트 / 레진치료 / 치아미백 (레진치료는 충치 제거 목적, 심미레진은 형태·색 개선 목적)\n4-5. [d] 잇몸 · 구강외과 — 7개 페이지\n파트 공통 슬로건 — 치주과 전문의가 직접 보는 잇몸\n\n치주질환은 성인 대부분이 겪는 흔한 질환이지만, 잇몸뼈는 한 번 녹으면 스스로 회복되지 않습니다.\n파트 전체의 담당은 강도욱 원장(치주과 + 통합치의학과 더블보드 전문의)입니다. 7개 페이지 상단에 공통으로 노출합니다.\n고난도 뼈이식이 [a] 임플란트 파트로 이동해 8개에서 7개가 되었습니다.\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 라미네이트와 무엇이 다른가요?\n현재 답변: 심미레진은 구강 안에서 직접 형태를 만들고 라미네이트는 별도 제작한 보철물을 붙입니다. 작은 부분 개선에서는 레진부터 검토할 수 있으며 삭제량·색 안정성·파절 가능성과 비용을 함께 비교합니다.\n\n질문: 얼마나 유지되나요?\n현재 답변: 범위·교합·이갈이·관리 상태에 따라 다릅니다. 마모나 변색, 파절이 있으면 연마·수리·재수복이 필요할 수 있습니다.\n\n질문: 정말 하루에 끝나나요?\n현재 답변: 작은 부위는 당일 마무리할 수 있는 경우가 많습니다. 다만 충치·잇몸·교합 상태에 따라 사전 치료가 필요할 수 있고 착색과 식사 주의는 사용 재료에 맞춰 안내합니다.", "source": "제공 개편 제안서 1549–1588행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-scaling','{"key": "copy-review-scaling", "category": "approval", "branch": "all", "title": "스케일링 · 원문/현재 답변 대조", "body": "제공 제안서 1589–1628행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n① 스케일링   ( /treatments/scaling )\n잇몸 관리의 시작, 1년에 한 번은 건강보험으로\n\n칫솔질로 제거되지 않는 치석을 전문 장비로 없애는 치료입니다. 치주 4단계 도식의 0단계, 즉 건강한 잇몸을 유지하는 출발점입니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 칫솔질할 때 피가 난다\n· 입냄새가 신경 쓰인다\n· 치아 사이에 누런 것이 보인다\n· 1년 넘게 치과에 오지 않았다\n③ 치료 설명\n· 치석과 플라그의 차이, 칫솔질로 제거되지 않는 이유\n· 건강보험 적용 안내 — 만 19세 이상, 연 1회(매년 1월 1일 기준으로 갱신)\n· 스케일링 후 흔한 증상 안내 : 일시적으로 시릴 수 있음, 이 사이가 벌어진 느낌(치석이 빠진 자리)\n· ''스케일링을 받으면 이가 깎이나요?'' 오해 바로잡기 섹션\n· 권장 주기 : 일반 6~12개월 / 치주치료 이력·흡연·당뇨 환자는 3~6개월\n④ 차별점\n1. 치주과 전문의가 잇몸 상태를 함께 평가합니다\n2. 스케일링으로 해결되지 않는 착색은 미백으로 안내드립니다\n3. 필요 시 치근활택술·치주소파술로 바로 이어집니다\n4. 수면 병행 가능\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 초음파 스케일러로 치석 제거 → ② 치면 연마 → ③ 잇몸 상태 확인 → ④ 필요 시 잇몸치료 안내\n⑥ 전후 사례\n치석 제거 전후 · 잇몸 상태 개선 케이스\n⑦ FAQ\nQ. 스케일링을 왜 해야 하나요?\nA. 치석은 세균 덩어리라 그대로 두면 잇몸에 염증을 일으키고, 방치하면 잇몸뼈까지 녹는 치주염으로 진행됩니다. 한 번 녹은 잇몸뼈는 저절로 회복되지 않아, 염증이 뼈까지 내려가기 전에 정기적으로 제거하는 것이 중요합니다. <치주염 링크>\nQ. 스케일링은 얼마나 자주 받아야 하나요?A. 일반적으로 6개월~1년에 한 번을 권해드립니다. 치주치료를 받으셨거나 흡연·당뇨가 있으시면 3~6개월로 주기를 짧게 잡습니다.\nQ. 치석은 왜 칫솔질로 안 지워지나요?A. 플라그가 침 속 미네랄과 만나 딱딱하게 굳은 것이 치석입니다. 굳고 나면 칫솔로 제거되지 않아 초음파 스케일러 같은 전문 장비가 필요합니다.\nQ. 스케일링을 하면 입냄새가 줄어드나요?A. 도움이 됩니다. 입냄새의 상당 부분이 치석과 잇몸 염증에서 나오기 때문입니다. 다만 원인이 혀 설태나 위장 문제인 경우도 있어 함께 확인합니다.\nQ. 스케일링을 하면 피가 많이 나던데 괜찮나요?A. 잇몸에 염증이 있으면 치석을 제거할 때 피가 납니다. 스케일링 때문이 아니라 이미 염증이 있었다는 신호이며, 치료 후 잇몸이 회복되면 출혈도 줄어듭니다.\nQ. 잇몸 아래 깊은 치석도 스케일링으로 되나요?A. 일반 스케일링은 잇몸 위 치석을 제거합니다. 잇몸 속 깊이 붙은 치석은 치근활택술이나 치주소파술로 따로 제거해야 합니다. <잇몸치료 링크>\n연결\n잇몸치료 / 치주염 / 치아미백\n영상 자산\n''스케일링도 소용없는 치아 착색'' 내용 활용\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 스케일링을 왜 해야 하나요?\n현재 답변: 치석에는 세균이 쌓이기 쉬워 잇몸 염증의 원인이 됩니다. 방치하면 지지 조직까지 손상되는 치주염으로 진행할 수 있어 칫솔질·치간 관리와 정기적인 치석 제거가 중요합니다.\n\n질문: 스케일링을 하면 입냄새가 줄어드나요?\n현재 답변: 치석과 잇몸 염증이 원인이라면 도움이 될 수 있습니다. 혀의 설태, 구강건조, 이비인후과 질환 등 다른 원인도 있어 지속되면 함께 확인합니다.\n\n질문: 스케일링을 하면 피가 많이 나던데 괜찮나요?\n현재 답변: 염증이 있는 잇몸은 치료 중 쉽게 피가 날 수 있습니다. 다만 출혈이 많거나 계속되면 복용 약이나 다른 원인도 확인해야 하므로 병원에 알려주세요.", "source": "제공 개편 제안서 1589–1628행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-gum','{"key": "copy-review-gum", "category": "approval", "branch": "all", "title": "잇몸치료 · 원문/현재 답변 대조", "body": "제공 제안서 1629–1665행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n② 잇몸치료   ( /treatments/gum )\n치아의 핵심 잇몸. 잇몸이 튼튼해야 치아가 건강합니다\n치주질환은 일반인 80% 이상이 가지고 있으며, 치석이나 플라그 세균에 의해 잇몸과 뼈에 생기는 흔한 질환으로 초기 치료를 하지 못하면 심각한 치아 손상의 원인이 됩니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 칫솔질할 때 피가 난다\n· 잇몸이 붓는다\n· 입냄새가 신경 쓰인다\n· 이가 길어 보인다\n③ 치료 설명\n잇몸 상태 4단계와 각 단계의 치료법 (기존 홈페이지 도식 그대로)\n· 0단계 건강한 잇몸 → 스케일링\n· 1단계 치은염 → 치근활택술\n· 2단계 초기 치주염 → 치주소파술\n· 3단계 만성 치주염 → 치주수술\n\n· 치료 후 유지 관리 — 3~6개월 정기 점검의 필요성\n④ 차별점\n1. 치주과 전문의가 단계를 직접 진단합니다\n2. 진행된 경우 치주수술까지 원내에서 이어집니다\n3. 전신질환(당뇨 등)과의 관계를 함께 확인합니다\n4. 수면 병행 가능\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 잇몸 상태 검사(치주낭 측정·엑스레이) → ② 스케일링 및 치근활택술 → ③ 필요 시 치주소파술·치주수술 → ④ 3~6개월 정기 점검\n⑥ 전후 사례\n잇몸 상태 개선 케이스\n⑦ FAQ\nQ. 잇몸에서 피가 나는데 그냥 두면 어떻게 되나요?A. 칫솔질할 때 나는 출혈은 잇몸 염증의 첫 신호입니다. 이 단계에서는 스케일링만으로 회복되지만, 방치하면 잇몸뼈까지 녹아 치아가 흔들리는 단계로 넘어갑니다.\nQ. 잇몸약을 먹으면 낫나요?A. 잇몸약은 증상을 일시적으로 완화할 뿐 원인인 치석과 세균을 없애지 못합니다. 약만 드시는 동안 잇몸뼈는 계속 녹을 수 있어, 치석 제거가 먼저입니다.\nQ. 잇몸치료를 받으면 이가 흔들리지 않나요?A. 치석이 치아를 잡아주고 있던 것처럼 느껴지다가, 제거 후 일시적으로 흔들리는 느낌이 들 수 있습니다. 염증이 가라앉으면서 대개 안정됩니다.\nQ. 잇몸치료 후 이 사이가 벌어져 보여요.A. 부어 있던 잇몸이 가라앉으면서 원래 공간이 드러난 것입니다. 치료가 잘못된 것이 아니라 염증이 빠졌다는 뜻이며, 치실과 치간칫솔로 관리하시면 됩니다.\nQ. 잇몸이 안 좋으면 임플란트도 못 하나요?A. 잇몸 염증을 그대로 둔 채 임플란트를 심으면 주위염으로 이어지기 쉽습니다. 잇몸치료로 상태를 안정시킨 뒤 진행하는 것이 순서입니다. <임플란트 재수술 링크>\n연결\n스케일링(4단계 도식의 0단계) / 치주염(진행된 단계) / 잇몸라인 / 고난도 뼈이식\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 잇몸에서 피가 나는데 그냥 두면 어떻게 되나요?\n현재 답변: 출혈은 잇몸 염증의 신호일 수 있어 확인이 필요합니다. 치석 제거와 위생 관리로 개선될 수 있지만 이미 깊은 조직까지 진행되었다면 추가 치료가 필요합니다.\n\n질문: 잇몸치료를 받으면 이가 흔들리지 않나요?\n현재 답변: 치석 제거 뒤 지지가 줄어든 느낌이 들거나 원래의 흔들림을 느낄 수 있습니다. 염증이 가라앉아도 뼈 소실 정도에 따라 흔들림이 남을 수 있으므로 경과를 확인합니다.\n\n질문: 잇몸치료 후 이 사이가 벌어져 보여요.\n현재 답변: 부어 있던 잇몸이 가라앉거나 치석이 제거되어 원래 공간이 드러날 수 있습니다. 원인과 관리 방법을 확인하고 변화가 크거나 불편하면 재검진을 받으세요.", "source": "제공 개편 제안서 1629–1665행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-gum-contouring','{"key": "copy-review-gum-contouring", "category": "approval", "branch": "all", "title": "잇몸라인 · 잇몸이식 · 원문/현재 답변 대조", "body": "제공 제안서 1666–1704행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n③ 잇몸라인   ( /treatments/gum-contouring )\n잇몸 라인이 고르지 않으면 치아도 고르지 않아 보입니다\n치주성형술은 불규칙한 잇몸 라인을 다듬어 치아와 잇몸의 비율을 조정하는 시술입니다. 잇몸 비대칭, 치아 길이 불균형, 잇몸 노출 등을 치아 삭제 없이 개선할 수 있습니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 웃을 때 잇몸이 많이 보인다\n· 좌우 잇몸 높이가 다르다\n· 앞니가 짧아 보인다\n· 잇몸이 내려가 뿌리가 드러났다\n③ 치료 설명\n치주성형술이란?\n치주성형술이란 불규칙한 잇몸 라인을 다듬어 치아와 잇몸의 비율을 맞추는 시술입니다. 치아를 깎지 않고 잇몸만 조정해 짝짝이로 보이던 치아를 고르게 만듭니다.\n· 잇몸성형(치은성형)과 치관연장술의 차이 — 잇몸만 다듬는 경우와 잇몸뼈까지 조정하는 경우\n· 잇몸이 내려간 경우의 치료 : 연조직 이식 · 유리치은이식술\n· 라미네이트·심미보철 전에 잇몸 라인을 먼저 잡아야 하는 이유\n· 치료 과정과 회복 기간, 마취 방식\n④ 차별점\n1. 치주과 전문의가 직접 시행하는 치주성형술입니다\n2. 잇몸 이식(유리치은이식술) 케이스 자산을 보유하고 있습니다\n3. 보철 전 잇몸 라인 설계를 보철과 전문의와 함께 계획합니다\n4. 수면 병행 가능\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 원인 진단(잇몸 노출 원인이 잇몸인지 골격인지 구분) → ② 잇몸 염증 안정화 → ③ 잇몸성형 또는 치관연장술·이식술 → ④ 회복 확인 후 필요 시 보철 진행\n⑥ 전후 사례\n잇몸 라인 개선 · 유리치은이식술 케이스 (기존 유튜브 자산 활용)\n⑦ FAQ\nQ. 잇몸이 내려앉은 걸 되돌릴 수 있나요?A. 가능한 경우가 있습니다. 드러난 뿌리를 다시 덮는 치근피개술이나, 잇몸 두께를 키우는 이식술로 개선합니다. 다만 잇몸뼈까지 녹은 경우에는 회복 범위가 제한되므로, 원인과 남은 뼈 상태를 먼저 확인합니다.\nQ. 잇몸을 어디서 떼어 오나요?A. 대부분 본인의 입천장(구개)에서 채취합니다. 본인 조직이라 색과 질감이 주변과 자연스럽게 어우러집니다. 채취 부위는 보호 장치를 덮어 관리하며 보통 1~2주 안에 아뭅니다.\nQ. 회복까지 얼마나 걸리나요?A. 이식 조직이 자리 잡는 데 보통 1~3개월이 걸립니다. 그 사이 해당 부위는 세게 칫솔질하지 마시고, 안내드리는 관리 방법을 지켜주셔야 합니다.\nQ. 웃을 때 잇몸이 많이 보이는데 방법이 있나요?A. 잇몸이 치아를 과하게 덮고 있는 경우라면 잇몸성형이나 치관연장술로 라인을 올릴 수 있습니다. 다만 원인이 잇몸이 아니라 골격이나 윗입술 움직임이면 접근이 달라져 먼저 진단이 필요합니다.\nQ. 잇몸성형과 치관연장술은 무엇이 다른가요?A. 잇몸성형은 잇몸만 다듬고, 치관연장술은 잇몸 아래 뼈까지 함께 조정합니다. 뼈 위치를 그대로 두고 잇몸만 잘라내면 시간이 지나 원래대로 돌아오는 경우가 있습니다.\nQ. 좌우 잇몸 높이가 다른데 맞출 수 있나요?A. 가능합니다. 앞니는 좌우 대칭이 조금만 어긋나도 눈에 띄기 때문에, 인접 치아와 전체 비율을 함께 보고 라인을 설계합니다.\nQ. 교정하고 나서 잇몸이 내려갔어요.A. 교정 후 치은 퇴축이 생기는 경우가 있습니다. 드러난 뿌리를 다시 덮는 치근피개술로 개선할 수 있으며, 잇몸이 얇은 것이 원인인 경우 이식으로 두께를 함께 확보합니다.\nQ. 잇몸이 얇다고 하는데 문제가 되나요?A. 얇은 잇몸은 시간이 지나며 내려앉기 쉽고, 임플란트나 보철을 한 뒤 경계가 비쳐 보이는 원인이 됩니다. 미리 두께를 확보해 두면 이런 변화를 줄일 수 있습니다.\n연결\n라미네이트 / 심미보철 / 앞니 임플란트 / 잇몸치료\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 좌우 잇몸 높이가 다른데 맞출 수 있나요?\n현재 답변: 원인과 남은 잇몸·뼈 상태에 따라 맞출 수 있는 범위가 다릅니다. 인접 치아와 전체 비율을 함께 보고 예상 변화와 한계를 설명합니다.", "source": "제공 개편 제안서 1666–1704행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-periodontitis','{"key": "copy-review-periodontitis", "category": "approval", "branch": "all", "title": "치주염 · 원문/현재 답변 대조", "body": "제공 제안서 1705–1745행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n④ 치주염   ( /treatments/periodontitis )\n흔들리기 시작했다면, 이미 진행된 상태입니다\n치주 문제로 잇몸뼈가 녹아내릴 경우 다시 자연 회복이 되지 않기 때문에 빠른 치료가 필요합니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 이가 흔들린다\n· 잇몸에서 고름이 나온다\n· 음식을 씹기 어렵다\n· 치아 뿌리가 드러나 보인다\n· 이 사이가 벌어졌다\n③ 치료 설명\n치주염이란? \n치주염이란 잇몸 염증이 치아를 지지하는 잇몸뼈까지 번진 질환입니다. 한번 녹은 잇몸뼈는 자연적으로 회복되지 않아 방치할수록 치아를 잃을 위험이 커집니다.\n\n단계별 상태와 치료법 (기존 홈페이지 설명 텍스트 그대로)\n· 0단계 건강한 잇몸 : 선홍색의 단단한 잇몸으로 이를 닦을 때 피가 나지 않습니다. → 스케일링\n· 1단계 치은염 : 잇몸 연조직의 색이 붉어지고 부어오르며 이를 닦을 때 종종 피가 납니다. → 치근활택술\n· 2단계 초기 치주염 : 잇몸 아래 잇몸뼈까지 문제가 되며 치석이 생기고 뿌리 주변 염증이 발생합니다. → 치주소파술\n· 3단계 만성 치주염 : 잇몸이 붓고 피가 나며 음식물을 씹기 어렵습니다. 치아가 흔들리거나 뿌리가 드러나기도 합니다. → 치주수술\n\n· 방치했을 때의 흐름 : 발치 → 잇몸뼈 소실 → 뼈이식 후 임플란트\n④ 차별점\n1. 치주과 전문의가 치주수술까지 직접 시행합니다\n2. 발치 전에 살릴 수 있는지 먼저 검토합니다\n3. 당뇨 등 전신질환과의 관계를 함께 확인합니다\n4. 수면 병행 가능\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 정밀 검사(치주낭·엑스레이·CT) → ② 스케일링·치근활택술 → ③ 치주소파술 또는 치주수술(필요 시 골이식) → ④ 3~6개월 정기 유지 관리\n⑥ 전후 사례\n치주수술 · 골이식 병행 케이스\n⑦ FAQ\nQ. 치주염 초기 증상은 무엇인가요?A. 칫솔질할 때 피가 나고 잇몸이 붓거나 붉어지는 것이 시작입니다. 진행되면 입냄새가 심해지고 이가 시리거나 뿌리가 드러나 치아가 길어 보입니다.\nQ. 치주염은 왜 자각 증상이 늦게 나타나나요?A. 잇몸뼈가 녹는 과정에는 통증이 거의 없기 때문입니다. 흔들리거나 아파서 오시면 이미 많이 진행된 경우가 많아, 증상이 없을 때 정기검진으로 확인하는 것이 중요합니다.\nQ. 치주염 때문에 이가 흔들리는데 임플란트를 해야 하나요?A. 흔들린다고 모두 발치 대상은 아닙니다. 남은 잇몸뼈의 양에 따라 치주수술이나 골이식으로 살릴 수 있는 경우가 있어, 발치 전에 보존 가능성을 먼저 확인합니다. <자연치아 살리기 링크>\nQ. 치주염이 전신 건강과도 관계있나요?A. 당뇨와는 서로 악화시키는 관계로 알려져 있고, 심혈관질환과의 연관성도 보고되고 있습니다. 지병이 있으시면 잇몸 관리를 더 신경 쓰셔야 합니다. <전신질환 임플란트 링크>\n\n연결\n잇몸치료 / 스케일링 / 고난도 뼈이식 / 전신질환 임플란트\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n", "source": "제공 개편 제안서 1705–1745행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-wisdom-tooth','{"key": "copy-review-wisdom-tooth", "category": "approval", "branch": "all", "title": "사랑니 발치 · 원문/현재 답변 대조", "body": "제공 제안서 1746–1780행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑤ 사랑니 발치   ( /treatments/wisdom-tooth )\n누워 있거나 신경에 가까운 사랑니도\n매복되어 있거나 신경관에 가까운 사랑니는 3D CT로 위치를 정확히 확인한 뒤 발치합니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 사랑니 주변이 붓고 아프다\n· 사랑니가 누워 있다고 들었다\n· 신경과 가까워 대학병원에 가라고 했다\n· 교정 전에 빼야 한다\n· 여러 개를 한 번에 빼고 싶다\n③ 치료 설명\n· 난이도 구분 : 완전 맹출 / 부분 매복 / 완전 매복 / 수평 매복\n· 발치가 필요한 경우와 지켜봐도 되는 경우 구분\n· 발치 후 주의사항 : 지혈 · 부기 · 식사 · 금연 · 실밥 제거 시기\n· 건강보험 적용 안내\n④ 차별점\n1. 3D CT(HDX willmaster)로 하치조신경과의 거리를 미리 확인합니다\n2. 치주과 전문의가 직접 발치합니다\n3. 수면 발치 가능 — 여러 개를 한 번에 빼야 할 때 특히 유용합니다\n4. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 3D CT 정밀 진단 → ② 발치 계획 수립(수면 여부 결정) → ③ 발치 → ④ 지혈·소독 및 실밥 제거\n⑥ 전후 사례\n매복·수평 사랑니 발치 케이스\n⑦ FAQ\nQ. 사랑니를 꼭 빼야 하나요?A. 모두 빼야 하는 것은 아닙니다. 똑바로 나서 잘 맞물리고 칫솔질이 되면 그대로 두기도 합니다. 다만 옆으로 누웠거나 잇몸에 반쯤 덮여 있으면 앞 어금니를 밀고 음식물이 껴 충치와 잇몸 염증을 일으켜 발치를 권해드립니다.\nQ. 4개를 한 번에 빼도 되나요?A. 가능합니다. 수면(의식하진정)으로 진행하면 4개를 한 회차에 정리할 수 있어 여러 번 나눠 오시는 부담이 줄어듭니다. 양측 반매복·완전매복을 한 번에 발치한 사례가 있습니다. 다만 회복 기간에 양쪽으로 씹기 어려워 일정을 함께 보고 정합니다. <수면치료 링크>\nQ. 신경과 붙어 있으면 대학병원에 가야 하나요?A. 반드시 그렇지는 않습니다. 3D CT로 하치조신경관 경로와 뿌리의 관계를 미리 확인하면 원내에서 진행 가능한 케이스가 많습니다. 치주과 전문의가 직접 발치하며, 위험이 크다고 판단되면 상급 의료기관을 안내드립니다.\nQ. 수면으로 뺄 수 있나요?A. 가능합니다. 전신마취가 아닌 의식하진정으로, 진정 중 혈압·맥박·산소포화도를 감시합니다. 소리와 진동을 거의 인지하지 못한 채 끝나 치과 공포증이 있으시거나 여러 개를 빼셔야 하는 분께 권해드립니다. <수면치료 링크>\nQ. 얼마나 붓나요?A. 매복이 깊거나 뿌리가 휘어 잇몸을 열고 진행하면 붓기가 더 큽니다. 보통 2~3일째가 가장 심하고 일주일 안에 가라앉습니다. 첫 이틀은 냉찜질, 이후 온찜질이 도움이 됩니다.\n\n연결\n수면치료 / 잇몸치료 / 병원 둘러보기(3D CT)\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 4개를 한 번에 빼도 되나요?\n현재 답변: 난이도·전신 상태와 회복 중 식사 가능성을 보고 결정합니다. 한 회차에 여러 개를 발치할 수 있는 경우도 있지만 나누어 진행하는 편이 적합할 수 있습니다. 수면치료는 별도 적합성 평가가 필요합니다.\n\n질문: 수면으로 뺄 수 있나요?\n현재 답변: 의식하진정이 도움이 될 수 있지만 모든 분께 적합하지는 않습니다. 전신 상태·복용 약·기도 위험과 치료 범위를 확인한 뒤 결정하며, 필요한 경우 상급 의료기관 진료를 안내합니다.", "source": "제공 개편 제안서 1746–1780행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-tmj','{"key": "copy-review-tmj", "category": "approval", "branch": "all", "title": "턱관절장애 · 원문/현재 답변 대조", "body": "제공 제안서 1781–1813행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑥ 턱관절장애   ( /treatments/tmj )\n입 벌릴 때 소리 나고 아프신가요\n\n턱에서 나는 소리, 통증, 입이 잘 벌어지지 않는 증상은 턱관절장애의 신호일 수 있습니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 딱 소리가 난다\n· 입이 크게 벌어지지 않는다\n· 턱이 아프다\n· 두통·귀 주변 통증이 있다\n③ 치료 설명\n· 원인 : 이갈이·이악물기, 부정교합, 스트레스, 한쪽으로만 씹는 습관, 잘못된 자세\n· 치료 방법 : 스플린트(교합안정장치) · 물리치료 · 행동 습관 교정 · 약물\n· 치료 기간과 내원 주기 안내\n④ 차별점\n1. 측두하악관절장애 임상과정을 수료한 원장이 진료합니다\n2. 원인이 겹치는 이갈이·이악물기를 함께 관리합니다\n3. 원내 기공소에서 스플린트를 제작·조정합니다\n4. 수면 병행 가능\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 자가 체크 및 진단(개구량·소리·통증 확인) → ② 스플린트 제작 → ③ 착용 및 조정 · 물리치료 병행 → ④ 습관 교정 및 경과 관찰\n⑥ 전후 사례\n스플린트 치료 케이스\n⑦ FAQ\nQ. 소리만 나고 안 아프면 놔둬도 되나요?\nQ. 치료 기간이 얼마나 되나요?\nQ. 스플린트는 계속 껴야 하나요?\nQ. 교정을 해야 하나요?\n연결\n이갈이 / 이악물기 페이지와 상호 연결\n\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 소리만 나고 안 아프면 놔둬도 되나요?\n현재 답변: 소리만으로 치료가 필요한 것은 아닙니다. 통증·입 벌리기 제한·걸리는 느낌이 함께 있는지 확인하고, 증상이 새로 생기거나 악화되면 진료받으세요.\n\n질문: 치료 기간이 얼마나 되나요?\n현재 답변: 원인과 증상 기간, 생활 습관에 따라 다릅니다. 보존적 치료 후 경과를 보며 방법과 내원 간격을 조정합니다.\n\n질문: 스플린트는 계속 껴야 하나요?\n현재 답변: 장치 종류와 목적에 따라 착용 시간이 다릅니다. 임의로 계속 착용하지 말고 안내된 방법을 따르며 정기적으로 교합과 적합도를 확인하세요.\n\n질문: 교정을 해야 하나요?\n현재 답변: 턱관절 증상이 있다고 모두 교정이 필요한 것은 아닙니다. 우선 보존적인 치료를 검토하고 필요성이 확인된 경우 관련 진료를 안내합니다.", "source": "제공 개편 제안서 1781–1813행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
INSERT OR IGNORE INTO content_entries(kind,key,draft_json,live_json,revision,updated_at) VALUES('operation','copy-review-bruxism','{"key": "copy-review-bruxism", "category": "approval", "branch": "all", "title": "이갈이 · 이악물기 · 원문/현재 답변 대조", "body": "제공 제안서 1814–1847행. 질문과 답변을 대조하고 의학적·의료광고 검토 후 진료 관리에서 수정하세요. 이 대조 기록은 비공개입니다. 원문 불일치 자체가 오류라는 뜻은 아니며, 안전 표현·설명 보완도 포함합니다.\n\n## 제공 원문\n\n⑦ 이갈이 / 이악물기 ( /treatments/bruxism )\n자는 동안 치아가 닳고 있습니다\n\n본인은 모르는 사이에 치아가 마모되고, 잇몸과 턱관절에도 부담이 쌓입니다.\n블록\n화면에 들어갈 내용\n② 이런 분께\n· 아침에 턱이 뻐근하다\n· 이가 시리다\n· 어금니가 평평해졌다\n· 보철물이 자주 깨진다\n· 가족이 이 가는 소리를 듣는다\n③ 치료 설명\n· 치아 마모 · 시린 증상 · 보철물 파절과의 관계\n· 이갈이가 임플란트와 보철물 수명에 미치는 영향\n· 생활 습관 관리 : 스트레스 · 카페인 · 수면 자세\n④ 차별점\n1. 원내 기공소에서 나이트가드를 제작·조정합니다\n2. 임플란트·보철 계획 시 이갈이를 함께 고려합니다\n3. 턱관절장애와 원인을 묶어 관리합니다\n4. 수면 병행 가능\n5. 주말과 대체공휴일에도 치료받으실 수 있습니다.\n⑤ 치료 과정\n① 마모 정도 및 원인 확인 → ② 나이트가드(마우스피스) 제작 → ③ 착용 및 조정 → ④ 필요 시 교합 조정 · 경과 관찰\n⑥ 전후 사례\n치아 마모 · 보철물 파절 케이스\n⑦ FAQ\nQ. 이갈이를 하는지 어떻게 알 수 있나요?A. 본인은 모르는 경우가 대부분입니다. 아침에 턱이 뻐근하거나 어금니가 시리고, 어금니 씹는 면이 평평하게 닳아 있으면 의심해볼 수 있습니다. 가족이 소리를 듣고 알려주는 경우도 많습니다.\nQ. 이악물기도 이갈이만큼 문제가 되나요?A. 소리가 나지 않아 모르고 지나가지만 치아에 가는 힘은 비슷합니다. 낮 동안 무의식적으로 힘을 주는 경우가 많아, 치아 마모와 턱 근육 통증의 원인이 됩니다.\nQ. 이갈이 때문에 이가 시린가요?A. 그럴 수 있습니다. 치아 표면 법랑질이 닳아 안쪽 상아질이 드러나면 찬 것에 시린 증상이 생깁니다. 치아 목 부위가 파이는 경우도 흔합니다.\nQ. 이갈이가 있으면 보철물이 자주 깨지나요?A. 깨지거나 떨어지는 원인 중 하나입니다. 크라운, 라미네이트, 임플란트 보철 모두 영향을 받아, 치료 계획을 세울 때 이갈이 여부를 함께 고려합니다. <크라운 / 라미네이트 링크>\n\n연결\n턱관절장애 / 임플란트 / 크라운\n\n## 원문과 전체 문자열이 일치하지 않는 현재 답변\n\n질문: 이악물기도 이갈이만큼 문제가 되나요?\n현재 답변: 소리가 나지 않아도 강한 힘이 반복되면 치아 마모와 턱 근육 통증에 영향을 줄 수 있습니다. 낮 동안 무의식적으로 힘을 주는 습관도 함께 살펴야 합니다.", "source": "제공 개편 제안서 1814–1847행", "verified": false, "effectiveDate": "", "items": []}',NULL,1,'2026-10-06T00:00:00.000Z');
